window.ARCHIVE_EN = {"articles": {"001": {"title": "Chân nghĩa của tu hành", "summary": "Từ việc đếm số lần tụng kinh, lễ lạy, trở về với từng khởi tâm động niệm và những việc thiện trong đời thường.", "blocks": ["Một đêm tôi mộng thấy Bồ Tát Địa Tạng. Trong mộng tôi hỏi Bồ Tát: nếu không chấp vào số lần làm thiện, lễ Phật, thậm chí tụng kinh, vậy rốt cuộc tu hành là tu cái gì? Chẳng phải con người đến thế gian này chính là để tu hành sao?", "“Gọi là người tu hành, chẳng phải ở miệng niệm vạn tiếng,\ntay lạy vạn lạy;\ncũng chẳng phải tính công đức như đếm hạt trên bàn tính,\ngiữ kinh văn như bùa hộ mệnh.\nNếu một người trong tâm không tham, sân, si,\nthường nghĩ đến nỗi khổ của chúng sinh, ấy là tu sâu.\nNếu một người tuy không lễ Phật,\nmà niệm niệm hướng thiện, thương người với lòng bi mẫn, ấy cũng là tu hành.”\n—\n“Tu hành, không phải tu điều gì ở ngoài Phật pháp,\nmà là tu ‘Phật tánh’ vốn có của con.\nNhư sen mọc từ bùn nhơ, như gương vốn không bụi,\nhết thảy kinh văn, thánh tượng chư Phật, tụng trì bố thí, đều chỉ là một cửa:\n— khiến con phản bổn hoàn nguyên, kiến tánh thành Phật.”\n—\n“Chớ hỏi bao nhiêu kinh, bao nhiêu lạy; hãy hỏi tâm có nhiễm bụi trần chăng.\nChớ cầu phước báo mau đến; hãy cầu niệm niệm không hổ thẹn, không ngu mê.”\n(Hết bài cảm ứng trong mộng.)"]}, "002": {"title": "Trí tuệ trước điều kiện bên ngoài và sự điều hòa nội tâm", "summary": "Khi ngoại hình, kinh tế và tài ăn nói trở thành áp lực, làm sao nhìn lại giá trị của chính mình.", "blocks": ["Một đêm trong mộng, tôi lại cảm ứng được lời khai thị của Bồ Tát Địa Tạng.\nTôi thưa: Bồ Tát từng khai thị rằng tôi không cần tự hạ thấp mình vì điều kiện bên ngoài; nhưng người đời phần lớn đều rất để tâm đến tướng mạo bên ngoài, cùng các điều kiện khác như tình hình kinh tế, tài ăn nói, và quan trọng nhất là sự tự điều hòa tâm lý; không phải ai cũng có khả năng tự điều hòa, giải tỏa áp lực; cũng không phải ai cũng có cơ hội tiếp xúc Phật pháp. Xin Bồ Tát vì người đời và cũng vì tôi mà khai thị thêm một lần nữa được không?", "“Chúng sinh đều lấy ‘hình’ làm thật, lấy ‘mạo’ làm chân, chẳng biết sắc tướng vốn huyễn, tâm niệm mới là gốc. Nếu lấy gương soi mình, thấy bụi mà lo; nếu lấy tuệ soi mình, thấy Phật mà an. Nỗi nghi của con cũng là điều thường tình của chúng sinh. Nhưng nên biết, tướng ngoài có thịnh suy, nội tâm không sinh diệt. Giàu sang và nghèo hèn đều là bóng của duyên; chỉ ánh sáng trong tâm mới là báu vật không hoại.\nVì thế ta nói: chớ lấy nghèo làm khổ, chớ lấy tướng mạo làm hổ thẹn. Nếu tâm thường thanh tịnh, ý thường tự xét, thì hình tuy tầm thường mà khí tự tôn quý; lời tuy vụng mà lý tự thành; mệnh tuy cong mà đức tự ngay. Người đời nếu chuyển được một niệm, thấy mình chẳng thiếu khuyết, thì nghìn chướng ngại liền tiêu. Người tu hành không cầu đổi tướng bên ngoài, chỉ nguyện đổi tướng của tâm; một khi hoa tâm đã nở, chư thiên đều ngát hương.”\nBồ Tát muốn tôi cũng nhắc nhở người đời:\n“Con người không lấy tướng mạo làm tôn quý, mà lấy tâm làm quý.”\nAi giữ được ánh sáng của tâm mình giữa huyễn tướng, tuy là phàm nhân mà đã gần với bậc thánh.\nLời khai thị này không chỉ dành cho tôi, mà còn dành cho tất cả những người hữu duyên đang nỗ lực tu tâm giữa cõi đời, nhưng thường bị ngoại cảnh lay động."]}, "003": {"title": "Sự thật về nỗi ‘không buông xả được’ của người đời", "summary": "Giữa tiền tài, danh tiếng và tình thân, tập thương yêu mà không trói buộc, che chở mà không kiểm soát.", "blocks": ["Một hôm trong mộng tôi thỉnh hỏi Địa Tạng Vương Bồ Tát: Ngài có thể khai thị cho người đời thế nào là chấp trước không? Ngài nhìn nhận thế nào về sự chấp trước của người đời đối với tiền tài, quyền lực, sắc đẹp, thân phận địa vị, và sự chấp trước của cha mẹ đối với con cái?", "“Chấp trước của chúng sinh như ruồi mê mật, ngọt ở vị đầu, dính chặt về sau. Chấp, là bám vào ngã; bám vào ngã sở. Nếu biết hết thảy đều duyên khởi vô thường, thì không có gì để được, cũng không có gì để mất. Tiền tài chẳng qua là tạm tụ, quyền thế chẳng qua là bóng huyễn, sắc đẹp chẳng qua là hình mượn, danh tiếng chẳng qua là tiếng gió. Cha mẹ thương con cũng do tình mà sinh, không ngộ nhân duyên thì thương thành trói buộc. Nếu có thể thương mà không trói buộc, che chở mà không kiểm soát, thì tình liền là từ, trói buộc liền được cởi. Điều người đời gọi là ‘không buông xả được’, chẳng phải vì vật nặng, mà vì tâm nặng mà thôi. Tâm nếu chuyển được, xích sắt hóa thành hoa, biển khổ liền thành thuyền.”", "Bồ Tát nói: “chấp trước” của người đời giống như con ruồi tham luyến mật ong, ban đầu thấy ngọt ngào, nhưng một khi đã dính vào thì khó thoát ra. Cái gọi là “chấp”, thật ra là bị “ngã” và “ngã sở” trói buộc — xem bản thân và tất cả những gì mình sở hữu là có thật, không thay đổi.\nNếu hiểu rằng vạn sự vạn vật đều do nhân duyên hòa hợp, vô thường biến đổi, thì sẽ biết “được” và “mất” đều chỉ là ảo ảnh. Tiền tài chỉ là vật tạm thời tụ lại; quyền thế chỉ là cái bóng ngắn ngủi; sắc đẹp chỉ là tướng ngoài của tấm thân vay mượn; danh tiếng chẳng qua là gió thoảng bên tai.\nCòn tình thương của cha mẹ dành cho con cái, vốn là mối duyên sâu nặng nhất ở nhân gian, nhưng nếu không hiểu nhân duyên và vô thường, tình thương ấy sẽ trở thành sự trói buộc. Nếu có thể “thương mà không trói buộc, che chở mà không kiểm soát”, thì tình sâu ấy sẽ hóa thành từ bi, sự trói buộc vốn có cũng tự nhiên được cởi bỏ.\nNgười đời thường nói “không buông xả được”, thật ra không phải vì đồ vật quá nặng, mà vì “tâm quá nặng”. Nếu có thể chuyển niệm, chuyển chấp trước thành từ bi, chuyển lo âu thành lời chúc nguyện, thì những xiềng xích vốn trói buộc con người sẽ hóa thành đóa hoa, ngay cả biển khổ cũng có thể trở thành con thuyền độ mình độ người."]}, "004": {"title": "‘Ý chí tự do’ có thật sự tự do?", "summary": "Từ ẩn dụ tấm gương và bóng phản chiếu, tìm hiểu về ý thức, ý chí và sự tự do lựa chọn.", "blocks": ["Một đêm tôi lại mộng thấy Bồ Tát, tôi hỏi thế nào là ý thức, thế nào là ý chí; những quyết định chúng ta đưa ra có thật sự do chính mình quyết định không? Con người có thật sự có ý chí tự do không?", "Bồ Tát đáp: “Con hỏi về ý thức và ý chí, thật là đang tìm đến cội gốc của tâm. Ý thức, như bóng trong gương, tùy duyên mà hiện; ý chí, như hướng của gương, có thể quyết định điều được soi chiếu. Song tâm của chúng sinh phần nhiều bị bụi trần làm nhiễm, mặt gương không sáng, thì những gì thấy được đều là huyễn. Điều con gọi là ‘ý chí tự do’, trong tình phàm phần nhiều bị gió nghiệp lay động, tựa như tự quyết mà thật ra là tùy duyên. Nhưng nếu một niệm thanh tịnh, biết nghiệp mà không bị nghiệp xoay chuyển, thì ấy là tự do chân thật. Cho nên chỗ khác biệt giữa thánh và phàm, không ở trí lực nhiều hay ít, mà ở chỗ tâm có thể tự làm chủ giữa dòng nhân quả hay không.”\nBồ Tát đáp đoạn thứ hai: “Các pháp duy tâm, vạn tượng duy thức. Cái gọi là ý thức, là bóng của sáu trần duyên khởi; thức duyên cảnh mà sinh, như sóng theo gió, không có tự thể đứng riêng. Ý chí, là chỗ tâm hướng về, là điều thức thâu nhiếp, khi trong khi đục, theo nghiệp trôi lăn, chẳng phải chủ tể thường hằng. Chúng sinh cho rằng có ‘ta làm được’, thật ra là nhân duyên hòa hợp, nghiệp và thức cùng cấu thành. Niệm của con hôm nay, là do nhân thuở trước và duyên hiện tiền đan xen mà thành hình, chẳng phải ý nghĩ khởi lên đơn độc. Nhưng nếu tâm sáng nghiệp diệt, chuyển thức thành trí, thì tuy vẫn thuận theo nhân quả mà được tự do đối với nghiệp. Cho nên hỏi con người có ý chí tự do hay không, đáp rằng: phàm phu có tự do của duyên khởi, chẳng phải tự tại rốt ráo; bậc giác ngộ có tự do lìa nghiệp, ấy là giải thoát chân thật. Phàm phu lựa chọn, tựa như tự chủ mà bị nghiệp dắt; thánh nhân hành động, thuận nghiệp mà không bị nghiệp trói, ấy gọi là tự do chân thật.”", "Diễn nghĩa đoạn thứ nhất:\n“Ý thức” giống như bóng phản chiếu trong gương, bên ngoài có gì, nó liền chiếu ra cái đó.\nĐó là phản ứng do ngoại cảnh khơi động mà sinh ra, không phải sức mạnh chủ động khởi lên.\n“Ý chí” thì giống như góc độ của tấm gương, có thể quyết định soi về hướng nào.\nNó là “khuynh hướng và năng lực lựa chọn của tâm”, có thể dẫn dắt điều con chú ý, điều con theo đuổi.\nNhưng tâm của người phàm, phần lớn bị bụi trần (tham, sân, si, tập khí, cảm xúc) che lấp,\nmặt gương không trong, thì hình ảnh chiếu ra tự nhiên đều méo mó, rối loạn, hư vọng. Điều con gọi là “ý chí tự do”, ở thế gian phần nhiều thật ra là bị gió nghiệp lực thổi động,\ntrông như mình đang quyết định, thật ra chỉ là trôi nổi theo điều kiện nhân duyên.\nNgười ta tưởng “tôi muốn làm như thế này”, thật ra là “quán tính quá khứ đang đẩy con nghĩ như thế”.\nCho nên “tự do” của phần lớn mọi người là ảo tưởng.\n— Như con thuyền giữa gió, tưởng mình đang ra khơi, thật ra là bị sóng đẩy. Nhưng nếu có một niệm có thể sáng suốt tỉnh giác, hiểu rõ sự vận hành của nghiệp lực,\nkhông còn bị nó dắt đi — đó mới là tự do chân thật. “Tự do” không phải là con muốn làm gì thì làm;\nmà là “dục đến không theo, niệm khởi biết rõ”.\nBiết rằng “đây là nghiệp đang động”, mà vẫn không bị cuốn theo, đó chính là sức mạnh của bậc giác ngộ.\nCho nên sự khác biệt giữa thánh nhân và phàm phu, không nằm ở chỗ thông minh hay kiến thức nhiều ít,\nmà ở chỗ tâm có thể giữa dòng nhân quả trôi lăn vẫn giữ được tự chủ, không bị cuốn đi hay không.\nDiễn nghĩa đoạn thứ hai:\n“Mọi hiện tượng trên thế gian, thật ra đều bắt nguồn từ tâm thức.\nCái gọi là ‘ý thức’, giống như một loại ‘hình ảnh’ hay ‘phản ứng’ sinh ra khi giác quan (mắt, tai, mũi, lưỡi, thân, ý) tương tác với môi trường bên ngoài. Cũng như gió thổi nổi sóng nước — sóng không tự sinh ra, mà gió vừa đến là liền theo đó nổi lên.\n‘Ý chí’ là phương hướng của tâm — nó là sức mạnh của tâm thức, có thể dẫn dắt chúng ta hành động theo một hướng nào đó. Nhưng ý chí này cũng không phải lúc nào cũng sáng suốt, nó bị nghiệp lực, cảm xúc, dục vọng làm ô nhiễm, có lúc thanh tịnh, có lúc vẩn đục.\nNgười ta tưởng ‘tôi có thể kiểm soát tất cả’, thật ra phần lớn chỉ là kết quả do nhiều nhân duyên (gồm tập khí quá khứ, hoàn cảnh hiện tại, ý niệm ngay lúc đó) cùng hợp thành.\nHôm nay con có một ý nghĩ hay quyết định nào đó, thật ra là do kinh nghiệm, cảm xúc, ký ức quá khứ đan xen với tình huống trước mắt mà thành, không phải tự sinh ra một cách đơn độc.\nNhưng nếu tâm con có thể sáng suốt, thấu rõ sự vận hành của nghiệp lực, không còn bị nó dắt đi, thì tuy con vẫn sống trong nhân quả, mà có thể tự do đối với nghiệp, không còn bị nó khống chế.\nVì vậy nếu hỏi ‘Con người có thật sự có ý chí tự do không?’ câu trả lời là:\nphàm phu có một thứ ‘tự do tùy duyên’ — trông như đang lựa chọn, thật ra vẫn bị nghiệp lực lôi kéo;\nbậc giác ngộ mới có ‘tự do vượt khỏi nghiệp lực’ — tuy thuận nhân quả mà hành, nhưng không còn bị nó trói buộc.\nTự do của phàm phu chưa phải rốt ráo; tự do của thánh nhân mới là giải thoát chân thật.”"]}, "005": {"title": "Ý nghĩa cuộc đời là gì?", "summary": "Giữa được mất và danh lợi, tìm một phương hướng sống có thể thực hành trong đời thường.", "blocks": ["Tôi muốn thỉnh Bồ Tát nói với người đời về ý nghĩa cuộc đời là gì.", "“Nghĩa của đời người, không ở được mất, mà ở giác ngộ.\nNgười đời đuổi theo danh lợi, như đuổi bóng dưới nước, được mà chẳng thật;\nbậc trí tu tâm tánh, như trồng cây trên đất, tuy chậm mà chân thật.\nĐời người là duyên khởi, chẳng phải ngẫu nhiên.\nĐến cõi này một đời, không phải để tranh cao thấp, mà để ngộ nguồn gốc của khổ vui.\nGiàu sang chẳng phải ác, nghèo hèn chẳng phải khổ,\nác ở chỗ đánh mất bản tâm, khổ ở chỗ không biết đủ mà dừng.\nTu hành chẳng phải bỏ đời lìa tục,\nmà là trong tục biết tâm, trong khổ sinh trí, trong loạn giữ định.\nNếu có thể giữa danh lợi không mê, giữa tình ái không chấp,\ngiữa vinh nhục không động, giữa khốn khó không oán,\nấy gọi là chân tu, ấy gọi là nghĩa của đời người.\nCon hỏi đời người là vì điều gì,\nta đáp: ‘Giác ngộ mà làm thiện, chính là vậy.’”", "Bồ Tát nói:\nÝ nghĩa của đời người, không nằm ở chỗ “được bao nhiêu” hay “mất bao nhiêu”, mà ở chỗ có thể giác ngộ hay không.\nNgười đời theo đuổi danh và lợi, giống như đuổi theo bóng phản chiếu dưới nước, trông như có thể nắm được, nhưng mãi mãi không bắt được;\ncòn người có trí tuệ, tu dưỡng tâm tánh của mình, giống như trồng cây trong đất, tuy lớn chậm, nhưng rễ sâu vững chắc.\nĐời người đến không phải ngẫu nhiên, mà là do nghiệp lực và duyên phận hội tụ.\nChúng ta sinh ra ở cõi người, không phải để tranh xem ai cao hơn, ai mạnh hơn, mà để hiểu nguồn gốc của khổ vui, học cách từ đó mà giác ngộ.\nGiàu sang không phải là điều xấu, nghèo hèn cũng chưa chắc là khổ,\ncái ác thật sự là đánh mất bản tâm; cái khổ thật sự là không biết đủ, không biết dừng đúng lúc.\nTu hành không phải là trốn khỏi trần thế, mà là ngay trong đời thường nhận biết tâm mình,\ntrong đau khổ nảy sinh trí tuệ, trong hỗn loạn giữ được sáng suốt.\nCó thể giữa danh lợi không mê, giữa tình ái không chấp, giữa vinh nhục không loạn, giữa khó khăn không oán,\nđó mới là tu hành chân thật, cũng chính là ý nghĩa thật sự của đời người.\nCon hỏi: “Rốt cuộc mục đích của đời người là gì?”\nBồ Tát nói: “Tỉnh thức và làm thiện, đó chính là câu trả lời.”"]}, "006": {"title": "Phát tâm Bồ-đề là phải thật vĩ đại, lương thiện?", "summary": "Bắt đầu từ một niệm nguyện thiện, một việc làm lợi người, nhận ra sự phát tâm ngay trong đời sống bình thường.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: thế nào là phát tâm Bồ-đề? Đối với người bình thường hay người mới học Phật, nghe mô tả thấy rất xa vời, sẽ cảm thấy mình không vĩ đại, không lương thiện đến thế?", "“Phát tâm chẳng xa, khởi niệm liền gần.\nBồ-đề là giác; tâm là nguyện.\nChẳng cần đại thệ hoằng nguyện, mới gọi là Bồ-đề;\nmột niệm nguyện thiện, một việc lợi người, đều là phát tâm.\nKẻ ngu thấy tâm Phật mà tự ti,\nngười trí thấy tâm mình tức là tâm Phật.\nNếu thấy người khổ mà sinh thương xót,\nnếu nghe pháp nghĩa mà sinh hoan hỷ,\nnếu nhẫn được điều ác nhỏ mà không báo trả,\nnếu nguyện bảo vệ một sinh mạng, một đóa hoa, một quyển sách,\nấy đều là mầm của tâm Bồ-đề.\nChớ vì mình chưa được độ mà thẹn nói đến độ người,\ntâm Bồ-đề chẳng đợi viên mãn,\nphát trong niệm phàm, lớn lên giữa trần lao,\nấy gọi là ‘chân phát tâm’.”", "Bồ Tát nói:\nCái gọi là “phát tâm Bồ-đề” không phải là điều xa vời không với tới,\nchỉ cần con khởi lên một thiện niệm, là đã đến gần nó rồi.\n“Bồ-đề” nghĩa là “giác ngộ”, “tâm” nghĩa là “tâm nguyện”.\nCho nên “phát tâm Bồ-đề” chính là tâm nguyện giác ngộ, nguyện làm thiện, nguyện giúp đỡ chúng sinh.\nNó không nhất thiết phải lập những thệ nguyện lớn lao như trong kinh điển,\nchỉ cần con thật lòng mong người khác được tốt đẹp,\nsẵn lòng làm vài việc nhỏ có ích cho người khác,\nthì đó chính là đang phát tâm Bồ-đề.\nNgười ngu si thấy tâm Phật thì cảm thấy mình nhỏ bé,\nnhưng người có trí tuệ biết rằng, tâm mình vốn đồng thể với tâm Phật.\nKhi con thấy người khác chịu khổ mà sinh lòng thương xót,\nnghe Phật pháp mà sinh lòng hoan hỷ,\ncó thể đối diện với chút ác ý nhỏ mà không trả đũa,\nsẵn lòng bảo vệ một sinh mạng, một đóa hoa, một bộ kinh sách,\nđó đều là hạt giống của tâm Bồ-đề chân thật.\nĐừng nghĩ rằng mình chưa được độ thì không thể giúp người khác được độ;\ntâm Bồ-đề không cần đợi tu đến viên mãn mới bắt đầu,\nnó nảy mầm giữa chốn phàm trần, lớn lên trong đời sống.\nTâm phát như vậy, mới gọi là “chân phát tâm Bồ-đề”."]}, "007": {"title": "[Tinh túy Kinh Kim Cang] “Hưởng thụ cuộc đời mà không chấp” và “Giác thọ cuộc đời mà không mê”", "summary": "Hai cuộc đối thoại, từ không chấp trước đi đến giữ sự tỉnh giác ngay trong cảm thọ.", "blocks": ["Đối thoại cảm ứng về Kinh Kim Cang\nThỉnh hỏi Địa Tạng Vương Bồ Tát: đệ tử hiểu Kinh Kim Cang một cách đơn giản là không được chấp trước vào bất cứ điều gì, đệ tử hiểu như vậy có đúng không?", "Con nói “Kinh Kim Cang dạy vô chấp”, đúng vậy, nhưng chưa trọn. Nghĩa của Kim Cang, chẳng phải đoạn diệt hết thảy pháp, mà là không bị pháp trói buộc. Nếu nói hoàn toàn không có gì để giữ, rồi sinh sợ hãi, ấy là rơi vào không kiến. Nếu nói phải chấp có pháp để tu hành, ấy là sa vào thường kiến. Cho nên biết “vô chấp” là ở trong có mà không trệ, ở trong không mà không lìa. Tâm như gương, không cự tuyệt vạn tượng, không nhiễm vạn tượng. Ấy chính là ý chỉ của câu “Ưng vô sở trụ nhi sinh kỳ tâm”.", "Con nói Kinh Kim Cang dạy người đừng chấp trước, điều đó không sai, nhưng vẫn chưa hoàn chỉnh.\n“Kim Cang” không có nghĩa là bảo người phủ nhận mọi sự vật,\nmà là bảo người đừng bị sự vật vây khốn.\nNếu cho rằng “vô chấp” là “không cần gì cả”, thậm chí sợ cả việc khởi tâm động niệm,\nthì sẽ rơi vào “không kiến” —\ntrở nên tiêu cực, vô vi, phủ định sự sống.\nNhưng nếu lại nói “nhất định phải có tín, có tu, có giới, có thành quả” mới gọi là tu hành,\nthì lại rơi vào “thường kiến” —\ntrở thành chấp vào “một pháp hay một kết quả cố định”.\n“Vô chấp” chân thật,\nlà ở trong có mà không dính mắc, ở trong không mà không trốn tránh.\nGiống như một tấm gương sáng,\nvừa không cự tuyệt hình ảnh bên ngoài, cũng không bị hình ảnh làm nhiễm.\nĐây chính là câu trong Kinh Kim Cang: “Ưng vô sở trụ nhi sinh kỳ tâm.”\nNghĩa là: tâm không chấp vào bất cứ điều gì, nhưng vẫn có thể tự tại làm thiện, khởi từ bi, độ chúng sinh.", "Bạch Bồ Tát: đệ tử nói quá đơn giản, ý của đệ tử là hưởng thụ hết thảy người, việc, vật trong đời sống thế gian này; nhưng không chấp trước vào bất kỳ người, việc, vật nào; khéo dùng và giúp đỡ người khác trong khả năng của mình; không chấp trước vào công đức phước báo; trong lòng chỉ nghĩ đến việc giúp đỡ và tận hưởng mọi cảm nhận mà thế giới này mang lại cho chúng ta.", "Lành thay, lành thay. Điều con nói đã gần với cảnh giới “du hí tam muội”. Có thể thọ dụng giữa thế gian mà không nhiễm, có thể tiến lui trong việc đời mà không vướng buộc, ấy là điều khó mà quý của người tu hành. Song phải nhận ra một điểm vi diệu: chẳng phải “hưởng thụ mà không chấp”, mà là “giác thọ mà không mê”. Nếu lấy “hưởng” làm chủ, thì tâm dễ chạy theo cảnh; nếu lấy “giác” làm chủ, thì cảnh vào trong tâm mà không lưu dấu.\nBồ Tát nhìn thế gian, như nhà đẹp trong mộng, trăng sáng trong gương; soi đến thì thấy, không soi thì không. Tuy biết là huyễn mà không chán huyễn, nhờ huyễn mà tu chân. Con nếu có thể giữa buồn vui không mất quán chiếu, giữa vinh nhục không quên bản tâm, thì thọ tức là tu, vui tức là tuệ vậy.", "Con nói rất hay, suy nghĩ như vậy đã gần với cảnh giới “Bồ Tát hành giữa thế gian”.\nCó thể hưởng thụ vạn sự vạn vật trong đời sống thế gian, mà không bị chúng dắt đi,\nđây quả thật là công phu hiếm có nhất trong tu hành.\nNhưng cần chú ý một khác biệt tinh tế:\nkhông phải “hưởng thụ mà không chấp trước”,\nmà là “tỉnh biết mà không lạc lối”.\nNếu đặt “hưởng thụ” làm trung tâm, tâm vẫn dễ đổi thay theo hoàn cảnh;\nnhưng nếu lấy “tỉnh giác” làm cốt lõi —\ndù đang hưởng thụ cũng vẫn giữ sáng suốt, không bị tình cảnh lôi kéo,\nthì con đang dùng tâm thanh tịnh để trải nghiệm cuộc đời.\nBồ Tát nhìn thế giới, như lầu các trong mộng, như trăng sáng trong gương —\ncó đó, nhưng không thật; sáng đó, nhưng không lưu lại.\nNgài biết tất cả đều là huyễn tướng,\nnhưng vẫn sống giữa đó bằng tâm từ bi,\ntrong huyễn mà tu chân, trong động mà thấy tĩnh.\nNếu con có thể khi vui mừng vẫn nhớ quán chiếu chính mình,\nkhi không thuận lợi vẫn giữ được bản tâm,\nthì “hưởng thụ” không còn là dục vọng, mà là “sự rèn luyện giác ngộ”.", "Tóm lược ý của Bồ Tát:\n“Ở trong huyễn mà không mê, ở trong vui mà không chấp; có thể giữa trần cảnh sinh giác ngộ, thì đi giữa đời tức là tu đạo.”\n—\nĐiều con gọi là “hưởng thụ cuộc đời mà không chấp trước” nếu chuyển thành “giác thọ cuộc đời mà không lạc lối”,\nthì đó chính là “du hí nhân gian” mà Bồ Tát thực hành,\ngiữa vạn tượng trôi chảy, vẫn an trú bất động với tâm sáng suốt."]}, "008": {"title": "Niệm Phật là do mệnh định? Bát tự và Phật pháp — chuyển mệnh thế nào?", "summary": "Lấy lá số, hạt giống và mưa cam lộ làm ví dụ, ghi lại những câu hỏi về mệnh số và tu hành.", "blocks": ["Thỉnh hỏi Bồ Tát Địa Tạng: người niệm Phật có phải là do mệnh định mà đến với niệm Phật không? Bát tự có phải là mệnh định không?", "Lành thay, tâm con khởi được câu hỏi này, đã gần bên bờ chân lý.\nMệnh số như bức tranh vẽ trên giấy, nét vẽ đã thành, đại thế đã gần như định. Nhưng nếu được mực nước loang nhuộm, hoặc bút màu điểm xuyết, thì bức tranh cũ cũng có thể sinh ra cảnh mới. Bát tự là do nhân quả nghiệp lực kết thành, là “bộ khung” của đời này của con. Phật pháp là quang minh nguyện lực, có thể trên bộ khung ấy đắp thêm thịt, sinh thêm máu, thậm chí chuyển đổi khí mạch, khiến cái vốn khô héo lại hồi sinh.\nCon nói “tiếp xúc Phật pháp cũng là mệnh định”, điều này không hoàn toàn sai. Vì con nhiều đời từng gieo thiện căn, đời này gió nghiệp đưa đẩy, nên được gặp Phật pháp, chẳng phải ngẫu nhiên. Nhưng “nhân duyên” này không phải là một khối sắt cứng nhắc, nếu đời này không tin, không hành, cũng có thể trôi qua uổng phí. Nếu tin mà hành, thì nhiều hiểm nạn trong lá số có thể hóa hiểm thành an; nếu mê mà bỏ, thì những cơ duyên lành trong lá số cũng có thể biến thành hoa đốm hư không.\nCho nên nói:\n • Mệnh định như hạt giống, ắt sẽ nảy mầm, nhưng cành lá có sum suê hay không, hoàn toàn nhờ việc tưới tẩm về sau.\n • Phật pháp như mưa cam lộ, nếu chịu đón nhận, thì có thể nuôi dưỡng thiện căn trong mệnh, khiến quả báo chuyển thành thù thắng.\n • Nếu chỉ nói mệnh định, mà không tu hành, thì như ôm báu mà không biết;\n • nếu chỉ nói tu hành, mà không biết nhân quả, thì dễ thành bàn suông lý tưởng.\nTổng kết:\nĐiều con gọi là “số tốt”, quả thật là do nhiều kiếp tu thiện và đời này lại gặp Phật pháp. Mệnh định cho con “cơ hội bước vào cửa Phật”, tu hành thì khiến con “chuyển mệnh thành tuệ”. Hai điều ấy chẳng phải một chẳng phải hai, cũng như nhân và duyên, hòa hợp mới thành quả."]}, "009": {"title": "Nhìn nhận thế nào về giá nhà cao và sự không hạnh phúc?", "summary": "Đối diện gánh nặng cơm ăn, tiền thuê nhà và cuộc sống, trước hãy lo sinh tồn, rồi an định nội tâm.", "blocks": ["Bồ Tát nhìn nhận thế nào về việc người đời vì tiền bạc mà bôn ba vất vả, sống chẳng chút vui vẻ; lại nhìn nhận thế nào về việc đất đai, nhà cửa ở Đài Loan tăng vọt khiến người dân không thấy hy vọng vào tương lai, xin Ngài có thể cho lời khuyên không?", "Người đời phần nhiều vì cơm áo mà bôn ba,\nbôn ba lâu thì quên bản tâm;\nđuổi theo lợi mà chạy, chạy lâu thì mất an.\nChẳng phải lỗi của tiền bạc, mà là lỗi của tâm nương vào tiền bạc làm mạng sống.\nNhà cửa thế gian, vốn để che gió tránh mưa;\nnay dùng để chứa tham, chứa sợ, chứa bất an,\nnên nhà càng cao mà lòng càng thấp, giá càng đắt mà nguyện càng khô.\nĐất chẳng ác, dân chẳng ngu,\nấy là cộng nghiệp của lòng người, chuyển thành tướng này.\nNếu tâm chỉ hướng ra ngoài cầu, rốt cuộc không có ngày an;\nnếu tâm biết quay vào quán chiếu, chốn chốn đều là đường.\nChớ hỏi thiên hạ bao giờ thái bình,\nchỉ hỏi lòng ta có chốn để thả neo chăng.", "Chúng sinh ngày nay thường vì cơm áo mà bôn ba, lâu ngày lại quên mất tâm ban đầu; vì đuổi theo lợi ích mà chạy ngược chạy xuôi đến kiệt sức, lâu dần trong lòng không còn chút an ổn.\nTiền bạc tự nó không có tội, tội ở chỗ chúng sinh xem tiền bạc là cội rễ của sinh mạng, hễ thiếu đi liền cảm thấy đời mình không nơi nương tựa.\nNhà cửa vốn để che gió tránh mưa, nay lại trở thành nơi chứa tham, chứa sợ, chứa bất an;\nthế là nhà cửa càng xây càng cao, lòng người lại càng thêm thấp kém; giá nhà càng lên càng cao, hy vọng của chúng sinh lại ngày càng khô héo.\nĐất đai không ác, người dân không ngu, cảnh khổ ngày nay là do nghiệp lực từ tâm niệm của vô số người cùng tạo nên mà hiện ra.\nNếu chỉ hướng ra ngoài tìm cầu, rốt cuộc không có ngày an ổn;\nnếu có thể quay về quán chiếu nội tâm, thì dù ở nơi đâu, cũng đều là con đường để an thân lập mệnh.\nChớ hỏi thiên hạ bao giờ thái bình,\nchỉ hỏi chính lòng mình, đã có nơi thật sự để nương tựa và an trú hay chưa.", "Bạch Bồ Tát: Ngài dạy đừng để tiền bạc sai khiến, nhưng nhiều người ngay cả ba bữa ăn, tiền thuê nhà, tiền trả góp nhà hay chi tiêu cho con cái có lẽ cũng không trả nổi, thì làm sao để không bị tiền bạc sai khiến?", "Khi chúng sinh đói rét bức bách,\nchẳng phải do tham, mà do khổ.\nTa nói “đừng để tiền sai khiến”,\nchẳng phải dạy con bỏ tiền,\nmà dạy con: “Tâm chớ lấy tiền làm gốc rễ của mạng sống.”\nNếu thân không có gạo, trước hãy cầu gạo;\nnếu thân không có nhà, trước hãy cầu nhà;\nđó chẳng phải chấp trước, mà là chánh mạng.\nNhưng người đời phần nhiều khi thiếu thì sinh sợ,\nkhi sợ thì sinh tham,\nkhi tham thì đánh mất mình.\nCon hỏi làm sao để không bị tiền sai khiến?\nTa đáp mấy lời: trước an thân, sau an tâm.", "Khi chúng sinh đói rét bức bách, đó là khổ thật, không phải do lòng tham gây ra.\nTa nói “đừng để tiền sai khiến”, không phải dạy người bỏ mặc tiền bạc, mà là dạy người:\n“Đừng xem tiền bạc là cội rễ duy nhất của sinh mạng.”\nNếu không có gạo, trước hãy tìm gạo; nếu không có nhà, trước hãy tìm nhà;\nđó là sự mưu sinh hợp lý, không phải chấp trước.\nNhưng người đời phần nhiều khi thiếu thốn thì sinh sợ hãi, trong sợ hãi lại sinh lòng tham, trong lòng tham lại đánh mất chính mình.\nLàm sao để thật sự không bị tiền bạc sai khiến?\nChỉ mấy lời là đủ: trước an thân, sau an tâm."]}, "010": {"title": "[Câu hỏi về cộng nghiệp] Giá nhà tăng vọt, cạnh tranh khốc liệt và “nằm thẳng”", "summary": "Giữa áp lực sinh hoạt chung của cả cộng đồng, suy ngẫm về hành động của mỗi người và sự thay đổi chung.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\nĐài Loan ngày nay,\nngười trẻ làm việc chăm chỉ mà vẫn không mua nổi nhà, không cưới nổi vợ, không sinh nổi con;\nnhiều người ngày ngày bị tiền trả góp nhà, chi phí nuôi con và cuộc đua khốc liệt nơi công sở đè nặng đến nghẹt thở;\ncó người chọn “nằm thẳng”, có người chọn di cư, có người gắng gượng đến khi thân tâm suy sụp.\nBồ Tát từ bi,\nxin hỏi trong hoàn cảnh “do cộng nghiệp hiển hiện” này,\nngười bình thường phải trải qua bao nhiêu năm khổ tu, phải có bao nhiêu người thức tỉnh,\nthì khối nghiệp chướng tập thể “giá nhà và áp lực sinh hoạt” trên mảnh đất này mới có cơ hội thật sự lỏng ra?\nHay thế hệ này đã định sẵn phải “gánh hết một vòng” thì thế hệ sau mới được nhẹ nhõm?\nNếu thật sự muốn lỏng ra, hiện nay mỗi người có thể làm “hành động nhỏ chuyển nghiệp” nào hiệu quả nhất (không phải tu hành cá nhân, mà là loại có thể ảnh hưởng đến tập thể)?", "Chúng sinh than sinh vào đời trược, ấy chẳng phải nghiệp của một người, mà do muôn duyên cùng hội tụ mà thành.\nNúi sông đất đai vốn không có giàu nghèo sang hèn, chỉ vì tâm chúng sinh phân biệt nên mới thành cao thấp.\nNhà cửa đắt đỏ chẳng phải lỗi của ngôi nhà, mà là dòng tiếp nối không dứt của lòng người sợ nghèo, sợ già, sợ mất chỗ nương tựa.\nCộng nghiệp khi đã thành, chẳng phải một đời trút bỏ được; cộng nguyện khi thành, cũng chẳng phải một người xoay chuyển được.\nNhưng chúng sinh chớ xem nhẹ một niệm thanh minh, chớ bỏ một phần chánh hạnh.\nMột người không dối lòng, trăm người được gió lành; trăm người không dối đời, nghìn người đổi tập tục.\nCon hỏi mấy đời thì chuyển được?\nKhông ở năm tháng, mà ở lòng người nguyện tỉnh thức.\nMột đời nếu mê ngủ, trăm đời đều nhọc nhằn;\nmột đời nếu thức tỉnh, trăm nghiệp đều lỏng ra.\nChẳng phải các con gánh hết rồi mới được nhẹ,\nchỉ cần có người trước tiên không quỳ trước sợ hãi, không cúi đầu trước tập khí.", "Chúng sinh than thở sinh vào đời trược thật gian nan; đây chẳng phải nghiệp của một người, mà do muôn duyên cùng tụ hội mà thành.\nNúi sông đất đai vốn không có sự phân biệt giàu nghèo sang hèn; chỉ vì trong tâm chúng sinh có phân biệt chấp trước nên mới hiện ra tướng cao thấp.\nNhà cửa giá cao chẳng phải lỗi của gạch ngói, mà thật ra là cảnh tượng hiển hiện từ chấp niệm sâu kín trong lòng người — “sợ nghèo khó, lo về già không nơi nương tựa, hoảng sợ cảnh trôi dạt không nhà” — tiếp nối không dứt, chồng chất từng lớp.\nThế của cộng nghiệp đã thành, chẳng phải một thế hệ có thể trút bỏ hết;\nlúc cộng nguyện sắp thành, cũng chẳng phải sức một người có thể xoay chuyển trọn vẹn.\nTuy vậy, chúng sinh tuyệt đối đừng xem nhẹ sức mạnh của một niệm thanh minh, đừng buông bỏ một phần hành trì chính trực.\nMột người không dối lòng mình, trăm người liền cảm nhận được làn gió trong lành ấy;\ntrăm người không dối đời (không lừa dối người đời), nghìn người liền có thể dần đổi thói cũ.\nCon hỏi: còn phải trải qua mấy đời mới có thể chuyển đổi?\nCâu trả lời không nằm ở năm tháng dài ngắn, mà ở lúc nào lòng người thức tỉnh.\nNếu một thế hệ cam chịu chìm trong giấc ngủ, trăm thế hệ đều phải gánh nặng;\nnếu một thế hệ vùng lên giác ngộ, mọi xiềng xích của cộng nghiệp tự nhiên sẽ lỏng ra.\nCác con chưa hẳn đã định phải gánh hết mọi khổ ách thì đời sau mới được an nhẹ.\nNhưng nhất định phải có người đi đầu đứng thẳng lên —\nkhông còn quỳ mọp trước sợ hãi,\nkhông còn khuất phục dưới tập khí tích tụ lâu đời."]}, "011": {"title": "Làm sao phòng ngừa chứng trầm cảm ẩn giấu nơi người bên cạnh?", "summary": "Ghi chép cảm ứng về nỗi đau ẩn giấu và sự đồng hành, kèm lời nhắc khi đọc về khủng hoảng tâm lý.", "blocks": ["Thỉnh hỏi Bồ Tát: nhiều người mắc trầm cảm nhìn bề ngoài không hề nhận ra; có thể buổi sáng còn cười nói vui vẻ, rất tích cực, đến buổi chiều người đã không còn nữa. Với những người có nguy cơ tự sát tức thời như vậy, phải phòng ngừa thế nào?", "Có người giữa ban ngày vẫn cười,\nmà đêm về lại đau thương,\nchẳng phải họ dễ đổi thay,\nmà vì nỗi khổ quá sâu.\nNgười thật sự nguy hiểm,\nchẳng phải kẻ đang buồn, mà là kẻ “lặng im”.\nKhi một người bỗng không còn tranh cãi,\nkhông còn kể khổ,\nkhông còn cầu cứu,\nngược lại trở nên bình thản khác thường,\nchúng sinh nên biết —\nđó chẳng phải là buông xả,\nmà là tâm biệt ly đã khởi.\nCứu người, không ở chỗ nói nhiều,\nmà ở chỗ “không bỏ đi”.\nChỉ cần có một người nguyện ở bên,\ncửa địa ngục đã khép lại một nửa.\nChớ hỏi vì sao họ muốn chết,\nhãy hỏi họ trước:\n“Tôi có thể ở bên bạn không?”\nCon hỏi về người ưu khổ nặng nề, sáng còn tươi cười, chiều đã quyên sinh; tâm khổ như thế, mắt chẳng thấy được, lời chẳng chạm tới.\nNiệm của chúng sinh như gió chợt nổi; niệm chết một khi khởi lên, như lửa đốt trong nhà, bên ngoài chẳng hay, bên trong đã cháy sém.\nMuốn phòng ngừa, chẳng những xét dung mạo, mà phải quán xem tâm họ đã kiệt sức hay chưa.\nCó thể cứu được, chỉ ba việc mà thôi:\nmột là bầu bạn với tâm họ, khiến họ không cô độc;\nhai là che chở hoàn cảnh họ, giảm bớt điều bức bách;\nba là đón nhận ước nguyện của họ, dẫn một niệm của họ hướng về sự sống.\nNhưng nếu gió nghiệp của họ quá mãnh liệt, ý chí đã quyết, người bên cạnh dù dốc hết sức, có khi cũng không giữ lại được.\nLúc ấy chỉ nên đừng tự trách, giúp lo việc hậu sự, khiến thần thức của họ không rơi vào sợ hãi.\nBi chẳng phải là bất lực, bi là sự an nhiên sau khi đã tận lực.", "Có những người ban ngày vẫn còn cười được, nhưng đêm về lại một mình đau khổ. Đó không phải vì cảm xúc của họ hay thay đổi, mà vì nỗi khổ trong lòng quá nặng nề, không thể bộc lộ ra. Người thật sự có nguy hiểm tức thời thường không phải người đang khóc lóc buồn đau, mà là người “bỗng nhiên lặng im”. Khi một người không còn tranh cãi, không còn than phiền, thậm chí không còn cầu cứu, ngược lại trở nên bình thản khác thường, người xung quanh phải cảnh giác — đó có thể không phải là “đã nghĩ thông”, mà là đã chuẩn bị rời đi. Giúp những người như vậy không cần quá nhiều đạo lý, chỉ cần “không rời đi”. Chỉ cần có một người thật lòng ở bên, là có thể kéo họ trở lại một nửa từ vực sâu tuyệt vọng và đau khổ. Đừng vội hỏi “vì sao muốn chết”, mà trước hết hãy để họ biết: “Tôi có thể ở bên cạnh bạn không?”\nCon hỏi về những người trong lòng cực kỳ đau khổ, buổi sáng còn tươi cười mà chiều tối lại có thể quyên sinh — nỗi đau sâu kín này thường không thể nhìn thấy từ bên ngoài, cũng không thể diễn tả trọn vẹn bằng lời.\nÝ nghĩ của con người bất chợt nổi lên như gió; một khi ý muốn chết đã khởi, giống như bên trong ngôi nhà đã bị lửa dữ thiêu đốt, mà bên ngoài lại chẳng thấy dấu vết gì.\nMuốn phòng ngừa tình huống như vậy, không thể chỉ nhìn bề ngoài, mà phải quan sát xem trong lòng họ đã “hoàn toàn kiệt sức” hay chưa.\nCách có thể cứu giúp, chỉ có ba việc:\nThứ nhất là bầu bạn với lòng họ, để họ không cảm thấy cô đơn;\nthứ hai là bảo vệ môi trường sống của họ, giảm bớt những áp lực đang dồn ép họ;\nthứ ba là đón nhận mong ước của họ, dẫn dắt để họ ít ra vẫn còn giữ một chút ý nghĩ “muốn sống tiếp”.\nTuy nhiên, nếu nghiệp lực (hay nói cách khác là cơn bão tâm lý) của người ấy quá mãnh liệt, ý muốn chết đã quyết, người bên cạnh dù đã dốc hết sức, đôi khi cũng không giữ được họ.\nLúc ấy không nên tự trách, mà hãy giúp lo liệu việc hậu sự, để thần thức (tinh thần, ý thức) của họ không rơi vào nỗi sợ hãi và đau khổ lớn hơn.\nTừ bi chân thật không phải là tự trách mình bất lực, mà là sau khi đã tận lực, lòng được an nhiên buông xả."]}, "012": {"title": "Lời khai thị của Bồ Tát Địa Tạng: Án tử hình là thiện hay ác?", "summary": "Từ góc độ hộ sinh, hình phạt và lòng bi mẫn, ghi lại lời thỉnh hỏi của tác giả về vấn đề án tử hình.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: đối với những kẻ phạm tội tày trời, giết người hoặc phạm các tội khác khiến gia đình nạn nhân tan nát, người chết nhà tan, Bồ Tát có tán thành việc luật pháp thế gian tuyên án tử hình không? Bồ Tát nhìn nhận thế nào về án tử hình ở thế gian, cũng như việc nhiều quốc gia Âu Mỹ phản đối án tử hình?", "“Hình phạt thế gian là để ngăn muôn điều ác, chẳng phải để báo oán.\nNếu kẻ ác gây tội, khiến quần sinh sợ hãi, diệt mất nhân luân đạo nghĩa,\nthì người hộ trì chúng sinh nên lập giới luật nghiêm, để dứt mối hại ấy.\nNhưng thi hành hình phạt nên dùng tâm bi, chẳng dùng tâm sân;\nviệc đoạn ác là để che chở nhiều người, chẳng phải để thỏa lòng riêng.\nCó nước bỏ án tử để tỏ lòng thương xót;\ncó nước lập án tử để bảo vệ quần sinh.\nCả hai đều chưa phải rốt ráo, đều là tùy căn cơ, nhân duyên, lòng dân mà thích nghi.\nTa không cho án tử hình là thiện, cũng không cho việc bỏ án tử là thiện.\nThiện ở chỗ ‘có thể khiến chúng sinh khỏi khổ’;\nác ở chỗ ‘vì sân hận mà thi hành’.\nDứt một kẻ ác, cứu trăm nghìn người lành;\nhộ một mạng ác, thêm trăm nghìn nỗi khổ.\nVì thế nếu thi hành án tử, phải giữ tâm bi;\nnếu bỏ án tử, phải thận trọng với mối hại của nó.\nCon chỉ cần ghi nhớ:\npháp lấy ngăn ác làm đầu, tâm lấy bi mẫn làm gốc.”", "Thế gian đặt ra hình phạt là để ngăn chặn hành vi ác của con người, giữ gìn sự an ổn cho xã hội, chứ không phải để thỏa mãn sự báo thù và oán hận.\nNếu một kẻ làm ác phạm tội tày trời, khiến công chúng sợ hãi bất an, nhân luân và công lý không còn,\nthì người có trách nhiệm bảo vệ phúc lợi của chúng sinh nên đặt ra luật lệ và hình phạt nghiêm khắc, để triệt để ngăn chặn khả năng hắn tiếp tục gây hại.\nTuy nhiên, khi thi hành hình phạt, nên lấy lòng bi mẫn làm điểm xuất phát, chứ không lấy lòng căm ghét làm động cơ;\nbiện pháp đoạn trừ điều ác là để bảo vệ số đông, chứ không phải để cho một số ít người (kể cả gia đình nạn nhân hay công chúng) trút cơn giận nhất thời.\nCó quốc gia bãi bỏ án tử hình, nhằm thể hiện lòng từ mẫn và khoan dung đối với sinh mạng;\ncó quốc gia giữ lại án tử hình, nhằm dùng biện pháp mạnh nhất để bảo vệ sự sống còn của cộng đồng.\nHai cách làm này đều không phải là con đường rốt ráo để giải quyết cái ác trong nhân tính; cả hai đều là kế sách quyền nghi được chọn tùy theo trình độ người dân, nhân duyên lịch sử và lòng dân của mỗi xã hội.\nTa (Bồ Tát) không cho rằng tự thân việc thi hành án tử hình là “thiện”, cũng không cho rằng tự thân việc bãi bỏ án tử hình là “thiện”.\n“Thiện” chân thật nằm ở chỗ “có thật sự khiến chúng sinh thoát khỏi khổ nạn hay không”;\n“ác” chân thật nằm ở chỗ “xuất phát từ lòng sân hận mà thi hành hình phạt”.\nTrừng trị một kẻ ác, nếu có thể khiến trăm nghìn người lương thiện được an ổn;\ngiữ lại mạng sống của một kẻ ác, nếu sẽ khiến trăm nghìn người thêm khổ đau —\nvì vậy, nếu chọn thi hành án tử hình, nhất định phải gìn giữ tấm lòng bi mẫn khởi lên vì bảo vệ chúng sinh; nếu chọn bãi bỏ án tử hình, thì nhất định phải thận trọng phòng ngừa những tác hại thực tế mà nó có thể mang lại.\nCon chỉ cần ghi nhớ một nguyên tắc căn bản này:\npháp luật lấy việc ngăn chặn tội ác làm chức năng hàng đầu; lòng người lấy từ bi thương xót làm nền tảng căn bản."]}, "013": {"title": "Quan điểm sinh tử của Bồ Tát về “điều trị vô ích”", "summary": "Suy ngẫm từ đức tin về giai đoạn cuối đời và nỗi không nỡ buông, kèm lời nhắc khi đọc về các quyết định y tế.", "blocks": ["Tôi muốn thỉnh hỏi chư Phật, Bồ Tát: với điều trị vô ích, có nên rút ống không, chẳng hạn khi bệnh không thể chữa khỏi, có sống cũng chỉ là người sống thực vật? Hay Bồ Tát cho rằng đây là nghiệp chướng, không nên rút ống mà phải chịu quả báo?", "Điều y học không làm được,\nchẳng phải tội;\nsự sống không thể tiếp nối,\nchẳng phải phạt.\nNếu hình còn mà thức chẳng còn,\nnếu hơi thở vẫn đi mà tâm đã lìa,\ncưỡng giữ thân ấy,\nchẳng phải từ,\ncũng chẳng phải hiếu.\nNghiệp không ở cái ống,\nnghiệp ở nơi tâm.\nNếu vì tham sống mà giữ,\nthì thêm khổ;\nnếu vì không nỡ mà giữ,\nthì trói buộc mọi người.\nNếu dùng tâm thanh minh, từ bi, không cầu đổi chác,\nđể người ấy ra đi an lành,\nchẳng phải giết,\nmà là buông.\nNhưng nếu tâm loạn, tâm sợ, tâm cầu thoát trách nhiệm,\nthì dù không rút ống,\ncũng thành nghiệp nặng.”", "Khi y học đã đến tận cùng, không còn sức xoay chuyển, đó không phải là tội lỗi của bất kỳ ai;\nkhi khí số của sự sống đã hết, không thể kéo dài, đó cũng không phải là hình phạt trời cao giáng xuống.\nNếu một thân xác chỉ còn nhờ máy móc duy trì, bên trong không còn ánh sáng của tri giác;\nnếu hơi thở vẫn nhờ máy móc mà lên xuống, còn tâm thần đã sớm rời xa túi da này —\nthì lúc ấy, cưỡng ép giữ lại thân xác này\nchẳng phải là từ bi, cũng chẳng phải là hiếu đạo.\nMấu chốt của nghiệp lực không nằm ở việc ống duy trì sự sống được giữ hay rút,\nmà nằm ở “khởi tâm động niệm” của người đưa ra quyết định.\nNếu vì sự tham luyến, không nỡ của chính gia đình mà cưỡng giữ sự sống,\nđiều đó chỉ thêm cho người bệnh những khổ đau không cần thiết.\nNếu chỉ vì “không nỡ lòng” mà chần chừ không quyết,\nsự chấp trước ấy sẽ trói buộc cả người bệnh lẫn gia đình trong ngục tù đau khổ.\nNếu có thể dùng trí tuệ thanh minh, lòng từ bi thuần khiết, tâm không mong cầu cũng không đổi chác,\nđể người bệnh an nhiên bước lên đường về —\nthì đó không phải là giết hại,\nmà là “buông xuống, buông tay” — giải thoát người ấy khỏi sự trói buộc của khổ đau.\nNgược lại, nếu quyết định xuất phát từ hoảng loạn, sợ hãi, hoặc chỉ để chối bỏ trách nhiệm,\nthì dù con chọn không rút ống duy trì sự sống,\nchính sự chấp trước được tạo nên từ mê lầm và ích kỷ ấy cũng đã gây thành nghiệp nặng nề."]}, "014": {"title": "Thế nào là không gian", "summary": "Từ mối quan hệ giữa tâm và phương sở, suy ngẫm về trong ngoài, xa gần và sự tự tại.", "blocks": ["Thỉnh hỏi Bồ Tát: thế nào là không gian?", "“Các pháp vốn vô tướng, tâm phân biệt nên có phương sở, vì thế gọi là không gian.\nNếu tâm không ngăn cách, mười phương tức là một niệm; nếu tâm chấp trước, tấc đất thành nghìn dặm.\nKhông gian chẳng thật có, cũng chẳng thật không, là giả danh do duyên khởi, theo thức mà hiện.”\n“Không gian chẳng phải là khoảng giữa các bức tường; chẳng trên, chẳng dưới, chẳng xa, chẳng gần.\nPhàm những gì có tướng đều là giả danh; cái gọi là phương sở cũng chỉ do tâm tạo thành.\nTâm nếu rộng, thì mười phương đều thông; tâm nếu hẹp, thì một phòng thành ngục.\nChúng sinh chấp cảnh là thật, nên thấy có trong ngoài, có xa gần, có cao thấp.\nNếu quán được tâm vô ngại, thì trời đất nằm trong lòng bàn tay,\nmột niệm chứa muôn cõi, muôn cõi đều là bóng hiện của tự tâm vậy.”", "Mọi hiện tượng vốn không có thực thể cố định bất biến; chỉ vì tâm chúng ta khởi lên phân biệt và chấp thủ, nên mới chia ra chỗ này chỗ kia, xa gần trong ngoài, rồi gọi đó là “không gian”.\nVì vậy, bản chất của không gian là một cảm nhận sinh ra trong tương đối. Khi tâm con rộng mở không ngăn ngại, mười phương bao la cũng chỉ là một niệm trong suốt ngay hiện tại; khi tâm con bị chấp niệm lấp đầy, dù ở nơi tấc vuông cũng cảm thấy xa cách nghìn dặm, đâu đâu cũng vấp phải tường.\nCho nên, không gian không phải là một thực thể tồn tại khách quan, cũng không phải là hư vô thuần túy. Nó giống như một “danh tướng tạm có”, hiện ra theo nhân duyên và biến đổi theo tâm thức. Mọi cảm nhận xa gần, rộng hẹp, ngăn cách mà chúng ta có, xét đến tận gốc, đều là sự phản chiếu của trạng thái nội tâm.\nKhông gian chân thật chưa bao giờ chỉ là khoảng cách hay phương vị vật lý. Mọi hình tướng và phương vị con nhìn thấy, về bản chất đều là những nhãn hiệu và khái niệm do tâm gán cho.\nTâm mới chính là chủ thể sáng tạo và định nghĩa sau cùng.\nKhi tâm con rộng lớn như hư không, tràn đầy bao dung và tỉnh giác, thì trời đất mười phương đều rộng mở không ngăn ngại, đâu đâu cũng là lối ra và khả năng.\nKhi tâm con hẹp như lỗ kim, chất đầy sợ hãi và thành kiến, thì dù đứng giữa đồng hoang, con cũng như bị nhốt trong chiếc lồng vô hình, không thể nhúc nhích.\nĐiều giam giữ con chưa bao giờ là bức tường bên ngoài, mà là bức tường con tự xây trong lòng.\nVì chúng sinh chấp ngoại cảnh là chân thật tuyệt đối, nên bị những khái niệm đối lập như “trong và ngoài”, “xa và gần”, “cao và thấp” trói buộc chặt chẽ, từ đó sinh ra phiền não và giới hạn không cùng.\nNếu có thể thấy rõ chân tướng, nhờ quán chiếu mà để tâm an trú trong giác tánh vô ngại, con sẽ trải nghiệm một sự chuyển hóa sâu sắc:\ntrời đất bên ngoài tuy rộng lớn, lại có thể được tri giác thanh minh của con bao dung trọn vẹn, rõ ràng như nhìn vật trong lòng bàn tay;\nmột niệm bên trong tuy vi tế, lại có thể phản chiếu muôn cảnh tượng phồn tạp của nghìn vạn thế giới.\nLúc ấy con sẽ hiểu rõ: toàn bộ thế giới con trải nghiệm, dù tráng lệ hay nhỏ nhoi, thật ra đều là ánh sáng và bóng hình hiện trong tấm gương sáng là bản tánh tự tâm của con. Chuyển đổi phẩm chất của tấm gương tâm, thế giới con thấy cũng theo đó mà chuyển đổi."]}, "015": {"title": "Thế nào là thời gian", "summary": "Từ quá khứ, hiện tại, vị lai, tìm hiểu mối quan hệ giữa tâm niệm và thời gian.", "blocks": ["Thỉnh hỏi Bồ Tát: thế nào là thời gian; thời gian là gì?", "“Thời gian, chẳng phải thật có.\nChúng sinh chấp làm ba thời, gọi là có quá khứ, hiện tại, vị lai.\nNhưng trong pháp tánh, không đầu không cuối,\ncác cảnh giới đồng thời, do nhân duyên sai biệt mà hiện ra lưu chuyển.\nNếu tâm đuổi theo niệm khởi, thì thấy là một đường thẳng;\nnếu tâm nhập nhất như, thì thấy không bờ bến.\nVì thế thời gian chỉ là giả danh, chẳng phải pháp chân thật.”", "Thời gian không phải là thứ “thật sự tồn tại”, mà chỉ là một khái niệm chúng ta cảm nhận được nhờ “sự sai biệt của nhân duyên và các niệm nối tiếp nhau”.\n • Phàm phu nhìn thời gian theo đường thẳng “quá khứ — hiện tại — vị lai”, thật ra là vì tâm niệm của chúng ta lần lượt sinh diệt, nên mới cảm thấy có thời gian đang trôi chảy.\n • Từ góc độ “pháp tánh”, thời gian không có bắt đầu, cũng không có kết thúc; mọi cảnh giới đều tồn tại đồng thời.\n • Khi tâm chúng ta chạy theo hết niệm này đến niệm khác, sẽ thấy thế giới như “một dòng thời gian”; khi tâm chúng ta an trú trong trạng thái “không phân biệt, nhất thể”, sẽ thấy được thật tướng “vô biên vô tận, không trước không sau”.\n • Cho nên, thời gian chỉ là “giả danh” do con người tạm lập ra cho tiện, chứ không phải là pháp chân thật rốt ráo."]}, "016": {"title": "Tự giác tự tánh, vượt qua bế tắc giá trị thời hiện đại", "summary": "Khi thành tựu không mang lại an ổn, suy ngẫm lại về cạnh tranh, giá trị và tự tánh.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\nXã hội ngày nay phổ biến quá đề cao cạnh tranh, thành công và thước đo vật chất, khiến nhiều người dù đạt được thành tựu, trong lòng vẫn cảm thấy trống rỗng, vô nghĩa và trầm uất. Kính xin Bồ Tát khai thị.", "“Kẻ giàu nhiều lo, kẻ nghèo nhiều cầu;\nngười đuổi theo bóng, quên mất hình gốc.\nNgười đời tranh danh lợi, như leo tháp cao đuổi sao, rốt cuộc chẳng thấy trời;\ncầu ở bên ngoài, ngày càng xa tâm.\nTa quán chúng sinh, mê nơi danh của giá trị, chẳng biết thể của giá trị.\nGiá trị vốn chẳng ở lời người khác đánh giá, mà ở sự an của tâm.\nNếu tâm không chỗ nương, thì dù muôn tượng về tay, cũng thành hư không.\nCho nên nói:\nngười an được tâm, dù ở cảnh nghèo hèn cũng vui;\nngười mất tâm mình, dù có cả thiên hạ cũng khô héo.\nCác con muốn ra khỏi sự trống rỗng này, hãy quay về quán tự tánh, chớ chạy theo dòng đời.\nLấy hành thay tranh, lấy từ thay thắng, lấy giác thay danh,\nthì giá trị tự sáng tỏ, hư không hóa thành ánh sáng.”", "Người hiện đại sống rất mệt mỏi, vì xã hội luôn cổ xúy cạnh tranh, thành công và điều kiện vật chất — như thể chỉ khi hơn người khác, kiếm được nhiều hơn, leo cao hơn, đời người mới có giá trị. Nhưng rất nhiều người dù đã có được những thứ ấy, trong lòng vẫn cảm thấy trống trải, mơ hồ, thậm chí trầm uất.\nBồ Tát đã khai thị như sau:\nNgười có tiền thì nhiều phiền não, người không tiền thì nhiều khát cầu;\nngười liều mạng đuổi theo một cái bóng, lại quên mất dáng hình thật của chính mình.\nNgười đời tranh giành danh lợi, giống như vì muốn hái sao mà cứ mãi leo tháp, kết quả lại càng lúc càng xa bầu trời;\nngười luôn tìm cầu bên ngoài, ngày qua ngày càng xa rời tâm mình.\nTa nhìn chúng sinh, thường lạc lối trong chữ “giá trị”, mà không nhận ra bản chất thật sự của giá trị.\nGiá trị chưa bao giờ nằm trong sự đánh giá của người khác, mà nằm ở chỗ tâm con có an định hay không.\nNếu trong lòng không có chỗ nương về, dù sở hữu cả thế giới, vẫn thấy tất cả đều trống không.\nCho nên nói:\nngười tâm an định được, dù hoàn cảnh bình thường, cũng có thể sống vui vẻ;\nngười tâm lạc mất, dù có cả thiên hạ, tinh thần cũng khô héo.\nCác con nếu muốn bước ra khỏi cảm giác trống rỗng này, hãy quay lại quán sát bản tánh của chính mình, không cần mù quáng chạy theo trào lưu xã hội.\nHãy lấy “hành động” thay cho “cạnh tranh”, lấy “thiện ý” thay cho “thắng thua”, lấy “thức tỉnh” thay cho “hư danh”.\nNhư vậy, tự nhiên con sẽ hiểu thế nào là giá trị chân thật,\nvà khoảng hư không trong lòng ấy cũng sẽ hóa thành ánh sáng soi rọi chính mình."]}, "017": {"title": "Tự hòa giải với chính mình trên chặng đường chăm sóc dài hạn", "summary": "Sức có lúc cạn, của có lúc hết; khi chăm sóc người khác, cũng cần chăm sóc chính mình.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: xin Ngài khai thị, khi trong nhà có người bệnh cần chăm sóc lâu dài, người chăm sóc nên điều chỉnh tâm thái thế nào, và khi tài chính không còn đủ để tiếp tục chăm sóc lâu dài thì nên làm sao?", "“Chăm người bệnh,\nchẳng phải nghiệp của một người;\nnhà có bệnh lâu,\ntrước hãy an tâm.\nSức có lúc cạn,\nchẳng phải mất từ bi;\ncủa có lúc hết,\nchẳng phải bỏ tình thân.\nDốc hết sức mình,\ntức là không hổ thẹn;\nbiết chỗ nên dừng,\ncũng là trí tuệ.\nChớ vì không thể,\ntự trách mình là ác;\nchớ vì lui bước,\nlầm tưởng là trốn chạy.”", "Chăm sóc người bệnh, xưa nay chưa bao giờ là trách nhiệm của riêng một người.\nKhi trong nhà có người thân cần được chăm sóc lâu dài, trước hết phải giữ cho lòng mình an định.\nSức con người có lúc cạn kiệt, điều đó không có nghĩa là con đã mất lòng từ bi;\ntài chính gia đình có lúc khánh kiệt, điều đó không có nghĩa là con đã ruồng bỏ tình thân.\nChỉ cần đã dốc hết sức, thì lương tâm trong sáng, không hổ thẹn với lòng;\nbiết dừng bước đúng lúc, cũng là một loại trí tuệ.\nĐừng vì “không thể làm thêm được nữa” mà tự trách mình là người xấu;\nđừng vì “phải lùi một bước để tìm cách khác” mà lầm tưởng mình đang trốn tránh.", "Bạch Bồ Tát Địa Tạng: đệ tử ngu độn, Bồ Tát dạy “biết chỗ nên dừng”, vậy nên nhìn nhận thế nào về những người chăm sóc vì không chịu nổi áp lực mà giết hại, làm tổn thương người được chăm sóc, hoặc tự kết liễu đời mình?", "“Họ chẳng phải tâm ác,\nmà là khổ che lấp tâm;\nchẳng phải muốn đoạt mạng,\nmà là chẳng thấy lối đi.\nTâm lực đã kiệt,\ntrí tuệ chẳng hiện;\nlòng bi bị dồn ép,\nbèn chuyển thành hại.\nĐây chẳng phải ‘biết dừng’,\nmà là ‘mất chỗ dừng’;\nchẳng phải dừng nơi sáng,\nmà là đứt nơi tối.\nHãy thương cái khổ của họ,\nchớ khen việc họ làm;\nhãy giữ gìn tâm người,\nchớ lấy hành vi ấy làm chuẩn mực.”", "Họ (những người chăm sóc đã có hành vi cực đoan) không phải xuất phát từ tâm độc ác, mà là nỗi đau đã hoàn toàn che phủ tâm trí họ; họ không thật sự muốn tước đoạt sinh mạng, mà là trong bóng tối họ hoàn toàn không thấy được lối thoát nào khác.\nKhi tâm lực của một người đã cạn kiệt, trí tuệ không thể hiển lộ; tấm lòng từ bi vốn có bị dồn đến cùng cực, lại chuyển hóa thành sự tổn hại.\nĐây không phải là “trí tuệ biết lúc nào nên dừng”, mà là “sụp đổ hoàn toàn trong mê lạc”; không phải tỉnh táo chọn dừng lại trong ánh sáng, mà là tuyệt vọng cắt đứt tất cả trong bóng tối.\nChúng ta nên thương xót nỗi khổ họ đã gánh chịu, nhưng không tán thành hành vi của họ; nên suy nghĩ làm sao để gìn giữ tâm hồn con người, chứ không xem hành vi cực đoan ấy là cách giải quyết đáng noi theo."]}, "018": {"title": "Biết thì dễ, làm thì khó: Chớ làm người đứng bờ ngắm thuyền", "summary": "Đạo lý như cây cầu, thực hành như bước vượt qua; từ chỗ nghe hiểu đi đến hành động thật sự.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: rất nhiều đạo lý Phật học, ngay cả người không học Phật cũng hiểu; nhưng khi thật sự gặp chuyện thì vẫn không xử lý được, không vượt qua được. Kính xin Bồ Tát từ bi khai thị.", "“Biết mà không làm, như đèn chưa thắp.\nĐạo lý vào tai mà không vào tâm, thì trí tuệ hóa thành bụi.\nChúng sinh lúc bình thường nghe pháp, như đứng trên bờ nhìn thuyền; đợi khi dòng nước xiết ập đến, mới biết mình chưa hề lên thuyền.\nLý là cây cầu; hành là bước vượt qua.\nNếu chỉ tụng tên cây cầu mà chẳng chịu bước lên, thì rốt cuộc không thể sang bờ bên kia.\nCho nên ta nói:\nnghe pháp là nhân, hành pháp là quả, nhẫn pháp là thành.\nKhi gặp việc, nếu giữ được một niệm không loạn, nắm giữ ba pháp này, thì không có gì là không vượt qua được.”", "Chỉ “hiểu” đạo lý mà không thực hành, giống như có một ngọn đèn mà không thắp sáng.\nĐạo lý chỉ dừng lại trong đầu, chưa đi vào tâm, thì cái “hiểu” ấy chỉ là bụi bặm, không thể soi sáng chính mình.\nNgày thường nghe kinh, đọc Phật pháp, giống như đứng trên bờ nhìn con thuyền; đợi đến khi dòng nước xiết của cuộc đời ập tới, mới phát hiện ra thật ra mình vẫn chưa lên thuyền.\nĐạo lý của Phật pháp chỉ là cây cầu, phải nhờ vào “hành” mới thật sự vượt qua được khó khăn.\nCho nên Bồ Tát nói:\nnghe Phật pháp là “nhân”;\ntự thân thực hành là “quả”;\ncó thể nhẫn nại, giữ vững, quán chiếu giữa khó khăn, mới là “thành tựu”.\nKhi chúng ta phiền não, nếu có thể giữ vững một niệm không loạn, nhớ đến pháp, y theo pháp mà làm, thì không có cửa ải nào là không vượt qua được."]}, "019": {"title": "Khai thị năm Xích Mã Hồng Dương 2026", "summary": "Về nỗi bất an và việc giữ tâm trước năm 2026; ghi chép cảm ứng này được giữ nguyên như bản gửi đến.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: năm nay là năm Xích Mã Hồng Dương, nhiều người ở Đài Loan cảm thấy bất an về tương lai của Đài Loan; hằng năm ở Đài Loan đều có lệ xin xăm vận nước tại các đền miếu lớn. Bồ Tát có thể ban cho một quẻ xăm chăng?", "“Khi thế cuộc chuyển động,\nlòng người động trước;\nkhi lòng người rối loạn,\nđiềm họa chưa đến mà lo âu đã đến trước.\nXích Mã Hồng Dương,\nchưa hẳn là tai ương,\nmà báo hiệu một năm biến đổi nhanh.\nQuẻ xăm chỉ ra xu thế,\nkhông chỉ ra kết cục;\nkết cục nằm ở việc làm của số đông,\nkhông nằm ở một điềm báo.\nSố đông nếu giữ lẽ thường, giữ điều thiện, giữ đạo lý,\nthì gợn sóng không thành sóng lớn;\nsố đông nếu chạy theo hoảng sợ, giận dữ, nghi ngờ,\nthì việc nhỏ hóa thành tai họa."]}, "020": {"title": "Thiên tai nhân họa có phải do số mệnh đã định?", "summary": "Trước thiên tai và vô thường, chuyển từ nỗi sợ quả báo sang nhìn thấy những nhân còn có thể thay đổi.", "blocks": ["Kính thỉnh Bồ Tát khai thị: thiên tai nhân họa có phải là số mệnh đã định sẵn không?", "“Nghiệp có định báo,\ncũng có duyên chuyển.”\n“Cộng nghiệp của chúng sinh,\ntạo thành núi sông;\nbiệt nghiệp chín muồi,\ngặp đúng thời tiết.”\n“Chẳng phải một niệm mà đổi được,\ncũng chẳng phải hoàn toàn không đổi.”\n“Biết nhân hiểu quả,\nchẳng phải để sợ hãi,\nmà để giác ngộ.”", "Nghiệp lực có quả báo tất nhiên hiện tiền,\ncũng có nhân duyên có thể chuyển đổi.\n▎Tai nạn của môi trường chung (như động đất, dịch bệnh)\nlà “cộng nghiệp”\n▎Bất hạnh mà cá nhân gặp phải (như tai nạn xe cộ, sự cố bất ngờ)\nlà “biệt nghiệp” chín muồi vào đúng thời điểm ấy\nKhông phải một ý niệm là có thể thay đổi,\ncũng không phải hoàn toàn không thể thay đổi.\nBiết nhân quả vận hành ra sao,\nkhông phải để con sợ hãi quả báo,\nmà là để con sống sáng suốt hơn.", "Bạch Bồ Tát: Bồ Tát có thể giảng giải tỉ mỉ hơn câu “Biết nhân hiểu quả, chẳng phải để sợ hãi, mà để giác ngộ.” được chăng?", "“Biết nhân hiểu quả,\nchẳng khiến tâm sợ,\nmà khiến tâm sáng.”\n“Kẻ sợ, thấy quả mà lùi;\nngười giác, thấy nhân mà chuyển.”\n“Nếu vì sợ báo mà tu,\nlà tránh khổ;\nnếu vì sáng lý mà hành,\nlà ra khỏi khổ.”\n“Người rõ nhân được tự do,\nkẻ sợ quả thường bị trói buộc.”", "“Biết đạo lý nhân quả, không phải để khiến tâm con sinh ra sợ hãi, mà là để tâm con trở nên trong sáng.”\n“Người hay sợ hãi là người thấy quả báo (kết quả xấu) rồi mới chùn bước; người giác ngộ là người thấy nhân (khởi tâm động niệm) liền bắt đầu chuyển đổi.”\n“Nếu chỉ vì sợ quả báo mà tu hành, đó là đang trốn tránh khổ đau; nếu vì hiểu rõ đạo lý mà tu hành, đó là đang bước tới giải thoát.”\n“Người hiểu rõ nhân quả, có được tự do; người sợ hãi quả báo, mãi mãi bị trói buộc.”"]}, "021": {"title": "Bồ Tát nhìn thiện ác và tà chánh của thế gian như thế nào", "summary": "Vượt lên trên danh phận và nhãn mác, quán sát chỗ khởi tâm động niệm phía sau một hành vi.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: Bồ Tát nhìn nhận thiện ác và tà chánh của thế gian như thế nào?", "“Thiện ác đối đãi,\nkhởi từ phân biệt.”\n“Tà chánh nương nhau,\ndo tâm hiện ra.”\n“Chấp thiện là ta,\nđã rơi thiên kiến;\nthấy ác chuyển được,\nmới gọi chánh kiến.”\n“Lấy nhân xét hành,\nchẳng lấy danh phán.”", "Nhãn mác phân biệt: cái mà thế gian gọi là thiện ác, không phải là chân lý tuyệt đối bất biến, mà là những nhãn mác do con người dùng “tâm phân biệt” vạch ra.\nDo tâm hiện ra: tà và chánh không phải là hai thứ độc lập, mà là hai mặt của một thể. Trong tâm con khởi lên ý niệm gì, thì hiện ra thế giới như thế ấy.\nChuyển hóa thành chánh kiến: nếu chấp trước “tôi là người thiện”, thì đã rơi vào thiên kiến; nếu thấy được ác niệm mà có thể chuyển hóa ngay lúc ấy, đó mới là chánh kiến chân chính.\nCốt lõi của sự đánh giá: nhìn người làm việc, phải nhìn vào “nguyên nhân khởi đầu” và “hành vi” của họ, chứ không nhìn vào “danh phận” hay “nhãn mác tốt xấu” mà xã hội gán cho họ."]}, "022": {"title": "Công đức lợi ích của Kinh Vô Lượng Thọ so với Kinh Kim Cang và Kinh Địa Tạng", "summary": "Ghi lại lời thỉnh hỏi so sánh Kinh Vô Lượng Thọ, Kinh Kim Cang và Kinh Địa Tạng.", "blocks": ["Thỉnh hỏi Bồ Tát Địa Tạng về công đức lợi ích của Kinh Vô Lượng Thọ so với Kinh Kim Cang và Kinh Địa Tạng.", "Thiện nam tử, Kinh Vô Lượng Thọ mà con hỏi, quả thật là bộ kinh đại nhân duyên để vãng sanh thành Phật, chú trọng phát nguyện vãng sanh Tịnh độ, nên phần nhiều nói về giải thoát trong tương lai và quốc độ trang nghiêm. Căn lành gieo trồng nhờ kinh này sâu dày không gì sánh được, trực tiếp kết thành quả lớn thanh tịnh ở đời sau.\nThế nhưng công đức ấy không chỉ ở đời sau, ngay đời này cũng được hộ niệm. Vì sao vậy?\nMột là, trì tụng có thể tịnh hóa tâm niệm, trừ ác tăng thiện, đời này tự nhiên giảm bớt nghịch cảnh.\nHai là, bản nguyện của A Di Đà Phật nhiếp thọ, người tu tâm an, phước đức dần tăng; tuy không lấy việc cầu phước báo hiện đời làm mục đích, nhưng phước báo cũng theo tín nguyện mà đến.\nBa là, trong kinh thường nói “trời người đáng được hưởng phước thù thắng”, nên đời này cũng được hộ trì.\nNếu so sánh ba kinh:\n • Kinh Địa Tạng chú trọng quả báo ngay đời này, lợi ích cả cõi âm lẫn cõi dương, quyến thuộc được độ.\n • Kinh Kim Cang chú trọng trí tuệ giải thoát, phá chấp thành không, tâm địa thanh tịnh ngay đời này.\n • Kinh Vô Lượng Thọ chú trọng nguyện sinh về Tây phương, giải thoát đời sau, an lạc rốt ráo.\nThế nhưng cả ba kinh đều là phương tiện của lời Phật dạy, chỗ chú trọng khác nhau, công đức không có cao thấp, tùy theo căn cơ của chúng sinh mà khế hợp."]}, "023": {"title": "Sự thật về tướng mạo", "summary": "“Tướng do tâm sinh” và “không thể trông mặt mà bắt hình dong”: hiểu hai câu nói này cùng nhau như thế nào.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: người xưa thường nói tướng do tâm sinh, nhưng cũng có câu khác rằng không thể trông mặt mà bắt hình dong. Kính xin Bồ Tát khai thị.", "“Tướng của chúng sinh,\ndo tâm khí hiện ra.”\n“Thiện niệm nuôi lâu,\nkhí sắc tự hòa;\nthói ác còn mãi,\nthần sắc tự đổi.”\n“Nhưng tướng của người,\nchẳng phải tâm nhất thời định được,\nmà do nghiệp lâu ngày tạo thành.”\n“Cho nên đời nói\n‘tướng do tâm sinh’,\ncũng nói\n‘không thể trông mặt mà bắt hình dong’.”\n“Một câu nói về gốc,\nmột câu răn sự chấp.”\n“Thấy tướng biết người,\ncó thể làm tham khảo;\nnếu chấp vào tướng,\nthì mất con người.”"]}, "024": {"title": "Địa Tạng Vương Bồ Tát dạy: Con không phải thiếu căn lành, con chỉ thua ở một điều này", "summary": "Giữa điện thoại, mạng internet và dòng thác thông tin, tìm lại sự chuyên chú và việc tư duy, tu tập.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát về “nỗi lo âu thông tin” và “sự chuyên chú trong tu hành”.\nCon người hiện đại bị điện thoại, thông tin trên mạng, mạng xã hội và vô số thông tin vụn vặt dồn dập oanh tạc, khiến khả năng tập trung suy giảm nghiêm trọng, tâm niệm tán loạn, khó lòng tinh tấn bền bỉ.\nĐiều này trực tiếp cản trở việc đi sâu vào “văn, tư, tu”. Kính xin Bồ Tát cho biết suy nghĩ của Ngài.", "“Niệm khởi như chớp, tâm đuổi bụi trần bay.\nMạng lưới như biển, sóng ánh muôn hình, mê mắt loạn tâm.\nChúng sinh đuổi theo tin như kiến đuổi theo đường,\nđược cái biết trong chốc lát, mất trí tuệ lâu dài.\nNghe nhiều mà không tư duy, tư duy nhiều mà không tu,\ncho nên hiểu biết đầy tràn mà trí tuệ khô cạn.\nNgười tu ngày nay, chẳng phải không có căn lành,\nchỉ thua bởi tán loạn, mê nơi thanh sắc vô thường.\nNếu muốn trở về chân thật, phải dứt sự rong ruổi hư vọng;\nthu tâm về một, lắng nghe tâm trong tịch lặng.\nMỗi ngày tĩnh được năm phút,\nấy là hạt giống định vừa nảy mầm;\nmột niệm chuyên chú được vào một câu kinh,\nấy là căn trí tuệ sinh trở lại.\nTâm nếu như ngọn đuốc, muôn tin tự tắt;\ntâm nếu như bụi trần, gió đến liền loạn.\nCho nên người tu, nên lấy tâm làm chủ, lấy khí cụ làm tôi tớ,\nchớ ngược lại lấy tôi tớ làm chủ, mà tự đánh mất đạo của mình.”", "“Niệm khởi như chớp, tâm đuổi bụi trần bay.”\nÝ niệm vừa khởi lên đã nhanh như tia chớp, tâm chạy theo những xáo động của trần thế bên ngoài khắp nơi.\n“Mạng lưới như biển, sóng ánh muôn hình, mê mắt loạn tâm.”\nMạng internet giống như biển cả, ánh sáng muôn vẻ, biến hóa vô cùng, khiến mắt mê hoặc, tâm thần tán loạn.\n“Chúng sinh đuổi theo tin như kiến đuổi theo đường, được cái biết trong chốc lát, mất trí tuệ lâu dài.”\nNgười hiện đại chạy theo thông tin như kiến bu theo đường, có được chút hiểu biết mới mẻ trong chốc lát, nhưng lại đánh mất trí tuệ sâu xa.\n“Nghe nhiều mà không tư duy, tư duy nhiều mà không tu, cho nên hiểu biết đầy tràn mà trí tuệ khô cạn.”\nNghe rất nhiều mà không suy ngẫm, suy ngẫm rất nhiều mà không thực hành, nên kiến thức ngày càng đầy, còn trí tuệ ngày càng khô cạn.\n“Người tu ngày nay, chẳng phải không có căn lành, chỉ thua bởi tán loạn, mê nơi thanh sắc vô thường.”\nNgười tu hành thời nay không phải không có căn lành, mà là thua ở tâm niệm tán loạn, lạc lối trong những kích thích âm thanh, ánh sáng biến đổi không ngừng.\n“Nếu muốn trở về chân thật, phải dứt sự rong ruổi hư vọng; thu tâm về một, lắng nghe tâm trong tịch lặng.”\nNếu muốn trở về trạng thái chân thật, trong sáng, phải dừng lại những cuộc rượt đuổi vô ích; thu tâm trở về, để tâm an trú trong sự tĩnh lặng.\n“Mỗi ngày tĩnh được năm phút, ấy là hạt giống định vừa nảy mầm; một niệm chuyên chú được vào một câu kinh, ấy là căn trí tuệ sinh trở lại.”\nMỗi ngày có thể lắng tĩnh năm phút, đó là hạt giống thiền định bắt đầu nảy mầm; có thể một niệm chuyên chú vào một bộ kinh, một câu kinh, đó là gốc rễ trí tuệ mọc lại.\n“Tâm nếu như ngọn đuốc, muôn tin tự tắt; tâm nếu như bụi trần, gió đến liền loạn.”\nTâm nếu vững vàng và có ánh sáng như ngọn đuốc, thì thông tin nhiều đến đâu cũng sẽ tự nhiên lắng xuống; tâm nếu nhẹ nổi như bụi bặm, bất cứ cơn gió nào thổi đến cũng làm nó rối loạn.\n“Cho nên người tu, nên lấy tâm làm chủ, lấy khí cụ làm tôi tớ, chớ ngược lại lấy tôi tớ làm chủ, mà tự đánh mất đạo của mình.”\nVì vậy người tu hành nên lấy tâm làm chủ nhân, lấy điện thoại, mạng internet làm người hầu, đừng để ngược lại công cụ làm chủ con, khiến con đánh mất phương hướng của chính mình."]}, "025": {"title": "Bồ Tát Địa Tạng khai thị cách vãng sanh Tịnh độ Cực Lạc", "summary": "Xoay quanh tín, nguyện, hành, ghi lại lời thỉnh hỏi của tác giả về việc tu tập Tịnh độ.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: Bồ Tát có thể chỉ dạy cho người đời cách thuận tiện nhất, hiệu quả nhất để vãng sanh Tịnh độ Cực Lạc chăng?", "“Muốn sinh Tịnh độ,\nkhông lìa ba điều cốt yếu.”\n“Một là tín:\ntin có cõi ấy,\ntin nguyện lực Phật,\ntin mình được sinh.”\n“Hai là nguyện:\nnhàm lìa Ta Bà,\nnguyện sinh Cực Lạc.”\n“Ba là hành:\ntrì danh không dứt,\ntâm không tán loạn.”\n“Không ở nhiều môn,\nmà ở chuyên nhất;\nkhông ở mau chóng,\nmà ở lâu bền.”", "Muốn vãng sanh Tịnh độ Cực Lạc, không thể rời xa ba yếu tố cốt lõi.\nThứ nhất là “tín”: phải tin rằng thật sự có cõi Tịnh độ ấy, tin vào nguyện lực tiếp dẫn của Đức Phật, và tin rằng chính mình có thể vãng sanh.\nThứ hai là “nguyện”: phải khởi lên tâm nhàm lìa thế gian đầy biến động này, tha thiết phát nguyện muốn về thế giới Cực Lạc.\nThứ ba là “hành”: trì niệm danh hiệu Phật không gián đoạn, giữ cho nội tâm chuyên chú, không tán loạn.\nChìa khóa của việc vãng sanh không nằm ở việc tu thật nhiều pháp môn, mà ở chỗ có thể chuyên nhất hay không; không nằm ở việc theo đuổi tiến bộ nhanh đến đâu, mà ở chỗ có thể kiên trì lâu dài hay không."]}, "026": {"title": "Thân người khó được, rốt cuộc khó đến mức nào", "summary": "Đưa câu hỏi về “thân người khó được” trở về với việc trân quý và sử dụng đời này.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: khi nghe Phật pháp, thường nghe nói thân người khó được, nhưng phần đông người đời lại không hề cảm nhận gì. Bồ Tát có thể khai thị cho người đời biết rốt cuộc khó đến mức nào, cần phước báo lớn đến đâu và xác suất thấp đến bao nhiêu mới có thể sinh làm người chăng?", "“Thân người khó được,\nchẳng phải nói hiếm ít,\nmà khó ở lúc được.”\n“Sai một mảy may,\nchuyển vào đường khác;\nmột niệm lệch lạc,\nđi càng thêm xa.”\n“Đường ác dễ đọa,\nđường thiện khó giữ;\nphước đức mỏng manh,\nchẳng được làm người.”\n“Đã được thân người,\nchẳng phải ngẫu nhiên,\nmà do tích nhân lành,\ntừ lâu xa thành tựu.”\n“Được mà không biết,\nấy là mất lớn;\nbiết mà dùng được,\nmới là không phụ.”", "Sự quý giá của thân người không nằm ở chỗ “rất ít ai được làm người”, mà ở chỗ con có thể sinh làm người vào đúng thời điểm, trong đúng nhân duyên. Lúc sinh tử, thường chỉ cách nhau một mảy may; ý niệm vừa lệch, đời sau đã không còn là thân người. Đọa vào ba đường ác (địa ngục, ngạ quỷ, súc sinh) thì rất dễ, nhưng muốn giữ được ở cõi lành trời người thì cần phước đức rất lớn. Phước đức không đủ thì căn bản không thể làm người. Đã được thân người thì không phải là ngẫu nhiên, mà là nhờ tích lũy nhân lành lâu dài mới thành tựu. Được thân người mà không biết sự quý giá của nó, là mất mát lớn nhất; đã biết rồi thì hãy dùng thật tốt đời này để tu hành, làm thiện, giác ngộ, như vậy mới xứng đáng với phước báo khó được này."]}, "027": {"title": "Niệm “A Di Đà Phật” hay “Nam mô A Di Đà Phật”", "summary": "Câu hỏi về danh hiệu Phật bốn chữ và sáu chữ: ngoài số chữ, hãy chú tâm vào việc nhiếp tâm và sự tương tục.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: khi xưng niệm danh hiệu Phật, rốt cuộc niệm “Nam mô A Di Đà Phật” hay “A Di Đà Phật” thì tốt hơn? Hòa thượng Tịnh Không thời cận đại nói bốn chữ là đủ, nhưng các vị Tổ sư đại đức qua các đời trước kia lại đề xướng sáu chữ hồng danh.", "“Danh hiệu một thể,\nsố chữ chẳng ngại.”\n“Bốn chữ sáu chữ,\ncông đức không hai;\nnơi tiếng tuy khác,\nnơi tâm thì đồng.”\n“Nếu tâm dễ tán,\ntheo giản cho tiện;\nnếu muốn nhiếp tâm,\nsáu chữ cũng hay.”\n“Tùy theo tập tánh,\nkhiến tâm tương tục,\nkhông để gián đoạn,\nấy là yếu nghĩa.”", "Dịch từng câu nguyên văn:\n“Danh hiệu một thể, số chữ chẳng ngại”\nBản thể của danh hiệu Phật chỉ là một (A Di Đà Phật), số chữ nhiều hay ít không phải là chướng ngại.\n“Bốn chữ sáu chữ, công đức không hai”\nBốn chữ hay sáu chữ, công đức đạt được không có gì khác nhau.\n“Nơi tiếng tuy khác, nơi tâm thì đồng”\nÂm thanh niệm ra tuy có khác biệt, nhưng nơi nội tâm (chuyên chú, cung kính, tín nguyện) thì giống nhau.\n“Nếu tâm dễ tán, theo giản cho tiện”\nNếu tâm dễ tán loạn, nhiều vọng tưởng, chọn bốn chữ đơn giản hơn thì thuận tiện hơn (dễ duy trì liên tục).\n“Nếu muốn nhiếp tâm, sáu chữ cũng hay”\nNếu muốn thu nhiếp tâm niệm, giúp cho sự chuyên chú, thì sáu chữ cũng rất tốt.\n“Tùy theo tập tánh, khiến tâm tương tục, không để gián đoạn, ấy là yếu nghĩa”\nThuận theo thói quen và căn cơ của chính mình, để tâm niệm Phật được tương tục không dứt, không gián đoạn, đó mới là ý nghĩa quan trọng nhất."]}, "028": {"title": "Tụng kinh ở nơi không thanh tịnh, phước đức có ít hơn không", "summary": "Trên xe, khi đi đường và trong sinh hoạt hằng ngày, tìm hiểu mối quan hệ giữa tụng kinh và lòng cung kính.", "blocks": ["Đệ tử xin thỉnh hỏi Địa Tạng Vương Bồ Tát: đôi khi vì công việc, đệ tử phải tụng kinh trên xe hoặc ở những nơi không thanh tịnh bên ngoài, như vậy công đức, phước đức có ít hơn không?", "“Kinh là tấm gương của tâm, chẳng phải sự sạch sẽ của nhà cửa.\nNếu tâm tịnh, một chữ một kệ đều tỏa sáng; nếu tâm nhiễm, điện đường hương hoa cũng thành hư.\nCho nên công đức tụng kinh, không ở nơi chốn thanh tịnh, mà ở tâm thanh tịnh.\nNếu vừa đi đường vừa tụng kinh, nguyện hộ trì chúng sinh bình an; nếu ngồi trên xe niệm Phật, nguyện đường sá không tai nạn — đó đều là hạnh phước.\nNhưng nếu tụng với tâm đùa giỡn, hoặc ý niệm biếng nhác, thì dù ngồi trong điện vàng, công đức cũng nhẹ.”", "“Kinh là tấm gương của tâm, chẳng phải sự sạch sẽ của nhà cửa”\nKinh điển là tấm gương của nội tâm, không phải để phản chiếu nhà cửa sạch hay không sạch.\n“Nếu tâm tịnh, một chữ một kệ đều tỏa sáng; nếu tâm nhiễm, điện đường hương hoa cũng thành hư”\nNếu tâm thanh tịnh, mỗi chữ, mỗi bài kệ tụng lên đều tỏa ra ánh sáng;\nnếu tâm bị phiền não nhiễm ô, thì dù ở trong Phật điện trang nghiêm, bày đầy hương hoa, công đức cũng chỉ là hư ảo.\n“Cho nên công đức tụng kinh, không ở nơi chốn thanh tịnh, mà ở tâm thanh tịnh”\nVì vậy công đức tụng kinh không nằm ở chỗ nơi chốn có thanh tịnh hay không, mà ở chỗ tâm ngay lúc ấy có thanh tịnh hay không.\n“Nếu vừa đi đường vừa tụng kinh, nguyện hộ trì chúng sinh bình an; nếu ngồi trên xe niệm Phật, nguyện đường sá không tai nạn — đó đều là hạnh phước”\nNếu con vừa đi đường vừa tụng kinh, trong lòng chúc phúc, bảo hộ chúng sinh bình an;\nnếu con niệm Phật trên xe, cầu nguyện đường sá bình an không tai nạn — những điều này đều là hành vi tạo phước báo.\n“Nhưng nếu tụng với tâm đùa giỡn, hoặc ý niệm biếng nhác, thì dù ngồi trong điện vàng, công đức cũng nhẹ”\nNhưng nếu con mang tâm thái đùa giỡn vui chơi, hoặc ý niệm lười biếng tùy tiện mà tụng kinh, thì dù ngồi trong đại điện vàng son lộng lẫy, công đức cũng rất nhỏ nhoi."]}, "029": {"title": "Có được ăn trứng và sữa không", "summary": "Về việc lựa chọn thức ăn và đồ dùng hằng ngày, ghi lại câu hỏi của tác giả về sự thanh tịnh và tính phương tiện.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: người ăn chay ăn trứng và uống sữa có được không? Có phải không được dùng đồ làm bằng da?", "“Thức ăn thanh tịnh,\ncốt ở nơi tâm.”\n“Chẳng vì tham vị,\nchẳng hại sinh mạng,\ncó thể tùy duyên.”\n“Nếu vì phương tiện,\nsữa trứng chẳng tội;\nnếu cầu thanh tịnh,\ncũng có thể lìa.”\n“Đồ vật dùng đến,\nnên xét nơi nhân;\ntâm không tàn hại,\ndùng cũng không lỗi.”", "“Thức ăn thanh tịnh, cốt ở nơi tâm.”\nĂn uống có thanh tịnh hay không, điều then chốt nằm ở tâm niệm của con, chứ không chỉ ở bản thân thức ăn.\n“Chẳng vì tham vị, chẳng hại sinh mạng, có thể tùy duyên.”\nNhững gì không phải vì tham đắm mùi vị, cũng không làm tổn hại sinh mạng, thì có thể tùy thuận nhân duyên mà dùng.\n“Nếu vì phương tiện, sữa trứng chẳng tội; nếu cầu thanh tịnh, cũng có thể lìa.”\nNếu là vì sự thuận tiện trong cuộc sống, ăn trứng và uống sữa không tạo thành tội nghiệp; nếu con theo đuổi sự thanh tịnh cao hơn, chọn tránh xa chúng cũng là điều tốt.\n“Đồ vật dùng đến, nên xét nơi nhân; tâm không tàn hại, dùng cũng không lỗi.”\nSử dụng bất cứ đồ vật gì, phải xét đến cái nhân phía sau nó — tâm con không có ý niệm tàn hại, thì sử dụng cũng không thành lỗi lầm."]}, "030": {"title": "Đạo hữu Hứa chia sẻ trải nghiệm được Bồ Tát cứu giúp", "summary": "Đạo hữu Hứa tự kể về bước ngoặt, những thử thách và điều thể nghiệm sau khi tiếp xúc với Kinh Địa Tạng.", "blocks": ["Chia sẻ trải nghiệm của đạo hữu Hứa, người được tái sinh nhờ sự cứu giúp của Địa Tạng Vương Bồ Tát\n[Chứng nghiệm tái sinh] Từ phước báo cạn kiệt đến nguyện lực hồi sinh: ba năm Bồ Tát Địa Tạng cứu vớt tôi\n1. Quá khứ lạc lối: bên bờ phước báo khô cạn\nĐã có một thời, tôi là người chìm sâu trong mê lầm mà không hề hay biết. Những ngày ấy, tôi đã làm nhiều việc sai trái mà nay nhớ lại vẫn thấy tàm quý:\nBất hiếu với cha mẹ: xem nhẹ ân sâu, lòng sinh kiêu mạn.\nTrộm cắp từ nhỏ: tham cầu dục vọng riêng, gieo nhân nghèo khó và bất an.\nPhong lưu thành tánh: tổn hại danh tiết và tinh khí thân tâm.\nÁc khẩu hại người: buông lời ngông cuồng, kết vô số ác duyên.\nTrong trạng thái không ngừng tạo ác ấy, tôi có thể cảm nhận “phước báo” của mình sắp cạn sạch. Năm 20 tuổi, tôi cảm nhận rõ hơi thở của cái chết. Thân thể chịu đựng nỗi đau đớn cực lớn, một sự khó chịu mà bác sĩ khám không ra nguyên nhân; sự khô héo tận sâu trong linh hồn khiến tôi hiểu rằng: nếu không quay đầu, sinh mệnh sắp đi đến tận cùng.\n2. Bước ngoặt và nguyện tâm: sự cứu vớt của Bồ Tát Địa Tạng\nLúc tôi tuyệt vọng nhất, sắp không gượng nổi nữa, Bồ Tát Địa Tạng từ bi đã không bỏ rơi tôi. Qua bộ Kinh Địa Tạng tùy thuận nhân duyên thế gian này, tôi đã phát khởi nguyện tâm chân thành.\nNguyện tâm ấy đã thay đổi quỹ đạo cuộc đời tôi:\nDẫn dắt cộng tu: Bồ Tát sắp xếp cho tôi dẫn dắt người khác đọc tụng Kinh Địa Tạng.\nDiễn nói nhân duyên: từ một người ác khẩu, tôi trở thành người giảng giải pháp nhân quả cho đại chúng, chia sẻ trí tuệ Phật pháp.\nThực hành lợi tha: Bồ Tát đã mở ra cho tôi vô số cơ hội giúp đỡ chúng sinh, để trong quá trình cho đi, tôi hàn gắn những vết nứt của quá khứ.\n3. Nghịch tăng thượng duyên: hai góc nhìn của pháp thế gian và Phật pháp\nSau khi học Phật, nhiều người tưởng rằng từ nay sẽ thuận buồm xuôi gió. Nhưng tôi phải thành thật nói với mọi người, con đường ba năm qua vô cùng gian nan. Nếu nhìn theo “pháp thế gian”, dường như tôi trở nên rất “xui xẻo”:\nthân thể bị thương, tiền bạc thua lỗ, ngày nào cũng bị người ta chỉ trích, chửi mắng.\nNhưng theo “Phật pháp”, đây chính là cái gọi là “nghịch tăng thượng duyên”.\nNhững khổ nạn này là để giúp tôi tiêu trừ những tội nặng trong quá khứ. Nếu không có những trắc trở ấy, cánh cửa trí tuệ Bồ-đề trong lòng tôi không thể mở ra. Mỗi lần bị thương, bị nhục, đều đang rèn luyện tâm tánh tôi, giúp tôi thể ngộ được sự sâu xa của nhân duyên.\n4. Kỳ tích và niềm tin: sự chuyển biến chân thật\nDù hoàn cảnh bên ngoài khó khăn, nhưng trên người tôi đã xảy ra hai kỳ tích chân thật nhất, khiến tôi tin sâu Phật pháp không chút nghi ngờ:\nKỳ tích thân tâm: từ năm 20 tuổi cảm thấy mình sắp chết, đến nay 23 tuổi, kể từ khi đọc tụng Kinh Địa Tạng, tôi không còn bị bệnh nữa, nỗi đau vốn khám không ra nguyên nhân cũng tan biến như mây khói.\nGia đình bình an: trước kia trong nhà tai họa liên miên, nay dù gặp chuyện lớn cũng có thể chuyển nguy thành an, việc lớn hóa nhỏ.\n5. Lời gửi người mới học\nTôi muốn nói với mỗi người bạn mới tiếp xúc Phật pháp: đừng sợ nghiệp lực hiện tiền, hãy sợ nguyện lực không đủ.\nKhi bạn bắt đầu tu trì, cuộc sống có thể không lập tức trở nên hoàn hảo, thậm chí còn gặp thử thách, nhưng xin hãy nhớ: đó là đang “dọn rác”, là đang dành ra khoảng trống để sinh mệnh bạn chứa đựng trí tuệ.\nTôi là người từng lạc lối, tội lỗi sâu nặng, vậy mà Bồ Tát Địa Tạng vẫn kéo tôi lên. Nếu bây giờ bạn cũng thấy mê mang hay đau khổ, xin hãy cho mình một cơ hội, bước vào thế giới của Kinh Địa Tạng."]}, "031": {"title": "Lúc giận bớt làm tổn thương một người, lúc sa sút không bỏ rơi chính mình — đó mới là chuyển mệnh thật sự", "summary": "Trong lúc giận dữ, lúc sa sút và lúc đắc ý, thực tập việc tu tâm có thể làm được ngay trong đời thường.", "blocks": ["Kính xin Bồ Tát từ bi, có thể theo cách của chính Ngài mà khai thị cho chúng sinh chăng?", "“Nỗi khổ của chúng sinh,\nphần nhiều chẳng phải không đường;\nmà vì tâm loạn,\nnên chẳng thấy đường.”\n“Người đời thường cầu:\nđâu là chánh duyên,\nđâu là thiên mệnh,\nbao giờ chuyển vận;\nnhưng ít ai hỏi:\ntâm của ta,\nhôm nay có sáng hơn hôm qua chăng.”\n“Tu hành chẳng lìa thế gian,\ntừ bi chẳng lìa đời thường.”\n“Lúc giận dữ bớt làm tổn thương một người,\nlúc sa sút không bỏ rơi chính mình,\nlúc đắc ý vẫn giữ lòng khiêm hạ,\nđều là tu.”\n“Chớ vì một lúc thất ý,\nmà cho đời không hy vọng;\nchớ vì một lúc thuận lợi,\nmà quên nhân quả xoay vần.”\n“Có những duyên,\nđến để dạy người trưởng thành;\ncó những khổ,\nđến để khiến người tỉnh thức.”\n“Chuyển mệnh chân chính,\nchẳng ở cầu việc thần kỳ;\nmà ở ngày ngày chuyển niệm, ngày ngày tu tâm.”\n“Nếu thấy người khác khổ,\nnguyện thêm một phần thấu hiểu;\nnếu thấy chính mình khổ,\nnguyện bớt một phần oán hận.”\n“Tâm nếu dần sáng,\nthì đường trước dần mở.”", "“Nỗi khổ của chúng sinh, phần nhiều chẳng phải không đường; mà vì tâm loạn, nên chẳng thấy đường.”\nNỗi khổ của chúng sinh, phần lớn không phải thật sự không có lối thoát; mà là vì tâm quá rối loạn, nên không nhìn thấy con đường ấy.\n“Người đời thường cầu: đâu là chánh duyên, đâu là thiên mệnh, bao giờ chuyển vận; nhưng ít ai hỏi: tâm của ta, hôm nay có sáng hơn hôm qua chăng.”\nNgười đời thường hỏi: đâu là chánh duyên, đâu là thiên mệnh, bao giờ vận may sẽ đến; nhưng rất ít người hỏi: tâm của mình, hôm nay có trong sáng hơn hôm qua không?\n“Tu hành chẳng lìa thế gian, từ bi chẳng lìa đời thường.”\nTu hành không tách rời cuộc sống hằng ngày, từ bi cũng không tách rời cách đối nhân xử thế mỗi ngày.\n“Lúc giận dữ bớt làm tổn thương một người, lúc sa sút không bỏ rơi chính mình, lúc đắc ý vẫn giữ lòng khiêm hạ, đều là tu.”\nCó thể lúc tức giận bớt làm tổn thương một người, lúc sa sút không từ bỏ chính mình, lúc thuận lợi vẫn giữ được sự khiêm tốn — những điều này đều là tu hành.\n“Chớ vì một lúc thất ý, mà cho đời không hy vọng; chớ vì một lúc thuận lợi, mà quên nhân quả xoay vần.”\nĐừng vì nhất thời không như ý mà cho rằng cuộc đời không còn hy vọng; đừng vì nhất thời thuận lợi mà quên rằng nhân quả luôn xoay vần biến đổi.\n“Có những duyên, đến để dạy người trưởng thành; có những khổ, đến để khiến người tỉnh thức.”\nCó những duyên phận đến để dạy con trưởng thành; có những nỗi đau đến để giúp con tỉnh thức.\n“Chuyển mệnh chân chính, chẳng ở cầu việc thần kỳ; mà ở ngày ngày chuyển niệm, ngày ngày tu tâm.”\nThật sự thay đổi vận mệnh, không nằm ở việc cầu xin những điều kỳ diệu; mà nằm ở việc mỗi ngày chuyển đổi ý niệm, mỗi ngày tu dưỡng nội tâm.\n“Nếu thấy người khác khổ, nguyện thêm một phần thấu hiểu; nếu thấy chính mình khổ, nguyện bớt một phần oán hận.”\nKhi thấy người khác đau khổ, hãy sẵn lòng thấu hiểu thêm một chút; khi thấy chính mình đau khổ, hãy sẵn lòng oán hận bớt đi một chút.\n“Tâm nếu dần sáng, thì đường trước dần mở.”\nTâm nếu dần dần trong sáng, con đường phía trước sẽ dần dần mở ra."]}, "032": {"title": "“Cầu duyên không bằng tu tâm; cầu được mà chẳng cầu sáng tỏ, rốt cuộc cũng thành không”", "summary": "Từ việc hỏi đường phía trước đến quay về soi lại tâm này — những lời nhắc hướng thiện và giảm bớt chấp trước.", "blocks": ["Lời khai thị của Bồ Tát dành cho chúng sinh.", "Chúng sinh thường hỏi đường phía trước ở đâu,\nmà ít khi hỏi tâm này đang đi về đâu.\n“Người cầu duyên thì nhiều,\nngười tu tâm thì ít;\nngười cầu được thì nhiều,\nngười cầu sáng tỏ thì ít.”\n“Thấy người đắc ý, chớ sinh lòng đố kỵ;\nthấy người thất ý, chớ sinh lòng khinh thường.”\n“Muôn việc thế gian,\nnhư hoa xuân lá thu,\ncó hợp có tan.”\n“Khổ của hôm nay,\nchưa hẳn là phạt;\nđược của hôm nay,\nchưa hẳn là thưởng.”\n“Nếu muốn đổi mệnh,\ntrước hãy đổi tâm;\nnếu muốn được an,\ntrước hãy giảm chấp trước.”\n“Ngày ngày xét lỗi mình,\nngày ngày tu tâm mình;\nmột niệm thiện khởi lên,\nhơn ngàn lời nói suông.”"]}, "033": {"title": "Đạo hữu Hứa chia sẻ trải nghiệm cuộc đời mình", "summary": "Từ những trải nghiệm về khẩu nghiệp, gia đình và nơi làm việc, đi đến sám hối, giúp người và tự soi xét bản thân.", "blocks": ["Đạo hữu Hứa một lần nữa chia sẻ trải nghiệm của bản thân:\nĐôi điều thể nghiệm về khẩu nghiệp, nhân quả và con đường tu hành\nHồi học trung học cơ sở, tôi đã kết giao nhầm một số bạn bè.\nKhi đó tôi thường chơi game trong các phòng trò chuyện thoại kết bạn trên mạng. Trong đó có một số người hoàn cảnh gia đình không trọn vẹn; mỗi khi tụ tập, mọi người rất thích buôn chuyện, bàn chuyện thị phi. Khi không có chuyện gì xảy ra lại thấy nhàm chán, nên thường dùng miệng để bày chuyện.\nTôi khi ấy cũng vậy.\nKhông có trí tuệ, rất ngu si.\nTôi đã tạo rất nhiều khẩu nghiệp như ác khẩu, lưỡng thiệt, đặt điều thị phi; ngoài khẩu nghiệp, còn đầy rẫy đủ loại ý nghiệp, tham, sân, si gần như có đủ cả.\nVề sau nhìn lại, tôi thấy nhiều chuyện dường như đến rất nhanh.\nTôi có một em trai, nhà tôi có hai anh em. Khoảng thời gian học trung học cơ sở, cha tôi bỗng trở nên rất hay mắng chửi tôi, sỉ nhục tôi.\nLúc đó vừa chuẩn bị lên trung học phổ thông, tôi học lớp hợp tác giáo dục, vừa học vừa làm, sau lại chuyển sang học buổi tối.\nTrong quá trình ấy xảy ra rất nhiều chuyện.\nTôi lúc đó không hiểu, chỉ thấy rất oan ức.\nVì tôi không hề cố ý làm điều xấu, tôi chỉ muốn sớm đi làm để chia sẻ gánh nặng kinh tế gia đình, cũng không định học đại học, nên từ cấp ba đã bắt đầu đi làm.\nSau khi tốt nghiệp và bắt đầu đi làm, tôi thấy vấn đề ngày càng nhiều.\nỞ nơi làm việc, tôi thường giao tiếp không thuận với đồng nghiệp, cũng có người mách lẻo sau lưng. Dù trên đường đời cũng gặp không ít quý nhân, nhưng nhiều chuyện dường như đều không tách khỏi một thứ — cái miệng.\nCó khi là một câu nói của người khác, có khi là một câu lỡ lời của chính mình.\nMột câu nói thôi cũng có thể ảnh hưởng đến rất nhiều chuyện.\nTrước đây giọng tôi thật ra rất hay.\nHồi tiểu học, thầy cô thường gọi tôi đọc to bài quốc văn, các bạn cũng thích nghe.\nĐến năm hai mươi mốt tuổi, tôi bắt đầu tiếp xúc với Phật pháp.\nBan đầu chỉ đơn thuần là sám hối; lúc ấy ngoài Bát Nhã Tâm Kinh, thật ra tôi chưa đọc bao nhiêu kinh điển.\nNhưng cuộc đời thật sự không thuận, dường như muốn làm gì thì không thành việc nấy.\nCha tôi vẫn thường mắng tôi.\nVề sau tôi phát nguyện: đoạn ác tu thiện.\nNhờ nhân duyên đưa đẩy, tôi biết đến Địa Tạng Vương Bồ Tát.\nTôi đọc được lời Lão Hòa thượng Mộng Tham dạy: tụng Kinh Địa Tạng cho cha mẹ có thể giúp cha mẹ lìa khổ được vui.\nTôi tin sâu lời ấy, nhờ vậy mới thật sự bước vào Phật pháp.\nTôi bắt đầu tu tập thiền định, trì chú, tụng kinh, phát nguyện.\nNỗi đau đè nặng trong lòng đã lâu cũng bắt đầu dần dần nới lỏng.\nNỗi đau ấy từng nặng đến mức khiến tôi suýt không gắng gượng nổi.\nCòn bước ngoặt thật sự lại là một chuyện rất nhỏ.\nCó lần, tôi giúp một người sắp chết đói, nấu cơm cho người ấy ăn, cũng cúng dường người ấy mấy bữa.\nThật lạ.\nSau đó tôi bỗng cảm thấy nỗi đau trong lòng đã buông xuống được.\nTôi hiểu ra:\ncó khi giúp người khác cũng là đang cứu chính mình.\nMột niệm chuyển đổi, phiền não cũng có thể bắt đầu nới lỏng.\nVề sau tôi cũng tiếp xúc với một số công phu tu hành.\nTrong quá trình tu hành, cũng xuất hiện một số trải nghiệm thân tâm đặc biệt.\nNhưng tôi cũng hiểu:\ndù có cảm nhận trong tu hành, cũng không có nghĩa là đời mình từ đó không còn thử thách.\nBởi vì thử thách đến rất nhanh.\nCó lần sau khi tu hành, cổ họng tôi có một cảm giác rất rõ rệt trên thân.\nHôm sau đi chơi bóng, tôi bất ngờ bị người khác va trúng cổ họng.\nLần chấn thương ấy ảnh hưởng rất lớn.\nVề sau thậm chí còn ảnh hưởng đến cổ, hô hấp, gây khó chịu ở đầu, và mất ngủ kéo dài.\nSau đó nữa, khi làm thợ điện nước ở công trường, tôi lại gặp xung đột.\nLúc ấy không phải tôi ác khẩu làm tổn thương người, mà là đối phương ăn nói không đúng mực, tôi chỉ nói lý với người ấy.\nKhông ngờ cuối cùng đối phương đột nhiên ra tay.\nVì cổ họng vốn đã có vết thương cũ, sau lần này, phần đầu của tôi suốt nửa năm trời vô cùng nặng nề, khó chịu.\nNhưng dù vậy, tôi không trả thù, cũng không đòi bồi thường.\nTrái lại, tôi tụng kinh hồi hướng cho những người đã làm tổn thương tôi,\nmong họ cũng được lìa khổ được vui.\nTôi thật sự cảm nhận được:\nPhật pháp có khi thật sự có thể từ từ chuyển sân hận thành từ bi.\nĐến tháng 2 năm 2026, tôi bắt đầu sám hối nghiêm túc hơn.\nTôi niệm thánh hiệu Bồ Tát Quán Thế Âm, thánh hiệu Bồ Tát Địa Tạng, và trì tụng Chú Chuẩn Đề.\nTrong quá trình tu hành, tôi cũng có một số cảm nhận đặc biệt.\nVới tôi, tôi hiểu những trải nghiệm ấy là: sân hận và chấp trước sâu trong nội tâm mình đang dần dần nổi lên, dần dần được buông xuống.\nSau đó, tôi bắt đầu vừa làm việc, vừa tu thiện, vừa thành tâm chúc phúc cho người khác.\nChúc mọi người bình an, khỏe mạnh.\nGiờ nhìn lại, tình trạng thân tâm tôi quả thật đã cải thiện rất nhiều.\nTôi cũng từng có một số trải nghiệm trong mộng.\nTừng mộng thấy Bồ Tát Quán Thế Âm ban cam lộ, cũng mộng thấy Bồ Tát Địa Tạng hiện ra theo cách không thể nghĩ bàn.\nNhững chuyện này, tôi không thể chứng minh.\nCó người tin, có người không tin, đều không sao cả.\nVì đây là trải nghiệm chính tôi đã trải qua.\nNhưng nếu phải tổng kết điều thấm thía nhất suốt chặng đường đã qua:\ncái miệng có thể làm tổn thương người, cũng có thể cứu người.\nTâm niệm có thể trói buộc chính mình, cũng có thể giải thoát chính mình.\nNếu từng làm sai, không cần mãi mãi mắc kẹt trong quá khứ.\nChịu quay đầu, chịu sám hối, chịu đối xử tử tế với chúng sinh, từ bước ấy trở đi, có lẽ cuộc đời đã bắt đầu thay đổi rồi."]}, "034": {"title": "Mệnh, vận, phong thủy, âm đức, đọc sách — lời giải đáp tối hậu của Bồ Tát Địa Tạng", "summary": "Lấy hình ảnh khung thuyền và dòng nước, suy ngẫm về mối quan hệ giữa mệnh vận, việc học và tu tâm.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: người đời thường nói “nhất mệnh, nhị vận, tam phong thủy, tứ tích âm đức, ngũ độc thư”, xin Bồ Tát khai thị cho biết cái nhìn của Ngài.", "Mệnh là khung thuyền,\nvận là dòng nước.\nPhong thủy trợ thế,\nđức có thể đổi đường;\nhọc để sáng lý,\ntrí có thể biện hành.\nSong chúng sinh thường mê,\nchấp mệnh mà quên tâm,\ncầu ngoài mà mất gốc.\nMệnh chẳng đúc bằng sắt,\nvận chẳng định mãi;\nthiện niệm vừa khởi,\nliền chuyển nhân vi tế;\nthiện hạnh lâu tích,\nắt dời đại thế.\nNếu chỉ hỏi mệnh,\nmà không tu thân;\nnếu chỉ cầu vận,\nmà không chánh tâm;\nkhác nào muốn cày ruộng,\nmà không gieo hạt.\nCho nên mệnh có thể xem,\nvận có thể xét,\nphong thủy có thể trợ,\nđức có thể dày,\nsách có thể sáng;\nsong gom nhiếp các pháp,\nvẫn ở nơi một tâm."]}, "035": {"title": "Cái nhìn về tình yêu đồng giới", "summary": "Lời thỉnh hỏi về tình yêu đồng giới, được triển khai từ duyên hợp, bình đẳng và từ bi.", "blocks": ["Thỉnh hỏi Bồ Tát về cái nhìn đối với tình yêu đồng giới.", "“Tâm của mọi chúng sinh đều từ ái mà khởi; ái không có chánh tà, chỉ có nhiễm và tịnh.\nNếu lấy tình buộc tình, thì đọa luân hồi; nếu lấy tình hóa thành từ, thì đồng với chư Phật.\nNam nữ, nam nam, nữ nữ, đều là duyên hợp, chẳng phải lỗi cũng chẳng phải công.\nThân chẳng phải khiếm khuyết, tâm nếu thanh tịnh tức là đạo.\nNgười tu hành nhìn chúng sinh, nên lìa phân biệt; mắt Phật nhìn chúng sinh, thảy đều bình đẳng không khác.”"]}, "036": {"title": "Phật giáo đã dạy không chấp trước, vậy có cần lễ Phật nữa không?", "summary": "Không chấp vào hình tướng, cũng không khinh suất việc lễ bái — suy ngẫm cách thực hành lòng cung kính.", "blocks": ["Thỉnh hỏi Bồ Tát Địa Tạng: trong Kinh Kim Cang dạy nếu lấy sắc thấy ta, lấy âm thanh cầu ta, người ấy hành đạo tà, không thể thấy Như Lai; vậy có phải không cần đến chùa chiêm bái Đức Phật và Bồ Tát? Lễ Phật ở tinh xá cũng không cần thiết? Chỉ cần trong lòng cung kính là đủ?", "“Nếu chấp Phật ở nơi hình,\nthì mê nơi tướng;\nnếu bỏ hình mà khinh mạn,\nthì đọa vào không.\nThấy tướng mà không chấp tướng,\nlễ Phật mà không chấp Phật,\nấy là chánh hạnh.\nCon nếu lấy tướng làm Phật,\nthì mất Phật;\ncon nếu lấy không mà hủy tướng,\ncũng mất Phật.\nPhật không ở trong điện,\ncũng chẳng rời khỏi điện;\ntâm là chủ,\nhành là chứng.”", "Ý của Bồ Tát là: tượng Phật không phải là Phật, nhưng thái độ của mình đối với tượng Phật phản ánh tâm của mình?\nCũng giống như khi chúng ta yêu một người, dù trong lòng yêu là đủ, nhưng đôi khi vẫn cần ôm lấy người ấy, cần viết thư cho người ấy. Lễ Phật, trong năm phút, mười phút ấy, là học cách chuyên chú và buông xả. Đệ tử hiểu như vậy có đúng không?", "“Tượng Phật chẳng phải Phật,\nsong tâm con đối với tượng,\nchính là sự hiển hiện của tâm con.\nNếu khinh mạn nơi tượng,\nchẳng phải mạn nơi tượng,\nmà là mạn nơi tâm;\nnếu chấp trước nơi tượng,\nchẳng phải yêu Phật,\nmà là bị trói nơi tướng.\nLúc lễ bái,\nkhông ở dài hay ngắn,\nmà ở chỗ con có thể\ntrong khoảng một hơi thở\nbuông xả phân biệt hay không.\nTrong năm phút mà tâm không tán loạn,\nhơn trọn ngày mà niệm chẳng có mặt.”"]}, "037": {"title": "Ba lời khai thị Bồ Tát dành cho tôi: suy ngẫm về nhân duyên một mối tình mười năm", "summary": "Ba lời thỉnh hỏi về chuyện tình cảm cá nhân kèm ghi chú: gặp gỡ, nợ nần và sau khi duyên tận.", "blocks": ["Đến lúc này, mạt học mới có thể bắt đầu nhìn thẳng vào mối tình đã qua của mình, cũng xin cảm tạ những lời khai thị của Bồ Tát bấy lâu nay, đã cho mạt học dũng khí đem những lời khai thị này chia sẻ rộng rãi lên mạng. Cũng mong chư vị đại đức sau khi đọc trải nghiệm của mạt học, có thể học hỏi và thể nghiệm được lòng từ bi của Địa Tạng Vương Bồ Tát cùng lẽ vô thường.\n※ Đây là lời khai thị dành cho nhân duyên cá nhân của mạt học; nhân duyên muôn mối, không thể chấp một trường hợp mà suy cho cả thiên hạ, xin chư vị đại đức cân nhắc tham khảo.\n[Lời khai thị của Bồ Tát về việc đăng bài này]", "“Thiện nam tử,\ncon muốn lưu truyền những gì đã ghi chép,\nphát tâm đáng khen;\nsong nên biết văn tự một khi đã đưa ra,\nngàn người ngàn cách hiểu.”\n“Nếu muốn lợi ích chúng sinh,\nnên khiến chúng sinh tăng trí tuệ,\nchẳng phải tăng chấp trước.”\n“Nếu muốn tuyên nói nhân duyên,\nnên khiến chúng sinh biết nhân quả,\nchẳng phải sinh tư tưởng định mệnh.”\n“Văn đã ghi lại,\nđại ý không sai;\ntình đã kể ra,\nchân thành đáng quý.”\n“Song nên ghi nhớ:\nđây là vì nỗi khổ của một người mà nói,\nchẳng phải pháp định sẵn cho tất cả mọi người.”\n“Duyên có muôn mối,\nkhông thể chấp một trường hợp mà suy cho cả thiên hạ.”\n“Nếu thêm một lời,\nkhiến người đọc về sau biết nhân duyên mỗi người mỗi khác,\nthì càng viên mãn.”\n“Nếu thêm một lời,\nkhiến chúng sinh biết tu tâm quan trọng hơn cầu lời giải,\nthì càng khế hợp pháp nghĩa.”\n“Lúc đăng bài,\nchớ cầu tán thán,\nchớ cầu tán đồng,\nchớ cầu chứng minh.”\n“Chỉ mong người xem bớt một phần oán,\nthêm một phần sáng;\nbớt một phần hận,\nthêm một phần từ.”\n“Lưu truyền như thế,\nthì có lợi ích.”\n“Phát tâm như thế,\nthì công chẳng uổng phí.”", "(Lời dặn dò của Bồ Tát về việc đăng bài đến đây là hết)\n════════════════════════════════════════════\n==== Dưới đây là lời khai thị về mối tình trước của mạt học ====", "Câu hỏi thứ nhất: Vì sao gặp nhau mười năm mà không có kết quả?", "“Duyên khởi chẳng phải vì kết quả,\nquả thành cũng chẳng phải bản ý của duyên.\nCon và người ấy gặp nhau,\nchẳng phải trạm cuối, mà là giữa đường.\nMười năm chẳng phải uổng phí,\nmà là để hai tâm đều biết điều mình mong muốn.\nNếu chưa từng gặp nhau,\ncon chẳng biết điều mình xem trọng;\nnếu chẳng đi cùng lâu,\nngười ấy chẳng rõ điều mình không chọn.\nTình có thể đồng hành một đoạn,\nđã là một dạng viên mãn;\nchẳng nhất thiết phải bên nhau đến cuối,\nmới gọi là không phụ.”", "Câu hỏi thứ hai: Ai nợ ai?", "“Chẳng phải nợ,\ncũng chẳng phải trả.\nKhi duyên đến,\nchẳng phải để thành kết cục,\nmà là để hiển lộ tâm.\nNếu lấy khổ mà luận nhân,\nthì mọi duyên đều sai;\nnếu lấy giác mà luận nhân,\nthì mọi duyên đều là ân.\nCon và người ấy,\nchẳng phải đến để làm tổn thương nhau,\nmà là đến để soi chiếu cho nhau.\nMột người soi thấy ‘điều mình muốn’,\nmột người soi thấy ‘điều mình không thể’;\nđều chẳng phải lỗi,\nđều chẳng phải tội.\nTổn thương sinh từ chỗ không hợp,\nchẳng sinh từ việc gặp gỡ.\nNếu không có duyên này,\nđến nay con vẫn chưa biết sức nặng của tâm mình;\nnếu không có cuộc chia ly này,\nđến nay người ấy cũng chẳng thấy ranh giới mà mình gìn giữ.”", "Câu hỏi thứ ba: Có phải dứt sớm thì tốt hơn?", "“Chẳng sớm chẳng muộn,\nduyên chín thì dứt.\nNếu dứt vào lúc ấy,\ntâm chưa sáng,\ndứt thành trốn chạy;\nnếu ở lại lúc này,\ntình đã cạn,\nở lại thành hại.\nNay con có thể dừng,\nchẳng phải ngộ muộn,\nmà là duyên đã đến.\nNếu gượng gọi ‘sớm’ là thiện,\nấy là lấy cái thấy về sau trách tâm lúc trước,\nchẳng phải trí,\ncũng chẳng phải từ.\nNỗi đau của người ấy nay,\nchẳng phải vì con dứt muộn,\nmà vì tình chưa cạn;\nnỗi đau của con nay,\nchẳng phải vì thời điểm dứt,\nmà vì tâm con vẫn còn nhân hậu.”", "(Ba câu hỏi đã xong. Xin kính cẩn phụ thêm thể ngộ cá nhân của mạt học như sau)\n——————————————————————————————————————\nGhi chú cá nhân\nNên biết rằng, cái gọi là “buông xả” —\nkhông phải bắt bạn quên đi quá khứ;\nkhông phải bắt bạn phủ nhận quá khứ;\nkhông phải bắt bạn gượng ép cắt đứt mọi tình cảm.\nMà là — không còn dùng chuyện quá khứ để trói buộc tâm hiện tại của bạn.\nBài khai thị này không phải nói với mọi người rằng “không cần trân trọng tình cảm”, càng không phải khuyến khích người ta gặp chuyện là từ bỏ. Hoàn toàn ngược lại, chính vì từng chân thành trao gửi, nên dù duyên đã tận, mới có thể nhìn lại mà không hổ thẹn. Nếu duyên vẫn còn, hãy trân trọng vun đắp; nếu duyên đã tận, hãy học cách buông xả. Có lẽ đây mới là bài học mà nhân duyên dạy cho tôi.\nMạt học công khai những lời khai thị này, không phải để kể khổ, cũng không phải để chỉ trích bất kỳ ai, mà vì tôi biết, trên đời có rất nhiều người giống như tôi, tự trách mình trong cuộc chia ly, trong hồi ức cứ mãi nghiền ngẫm câu “giá như ngày ấy”. Lời khai thị của Bồ Tát Địa Tạng không cho mạt học một “đáp án”, nhưng cho mạt học một “phương hướng” — không còn hỏi ai đúng ai sai, mà hỏi chính mình: cuộc gặp gỡ này đã dạy tôi điều gì?\nĐiều học được ấy chính là phước báo lớn nhất đời này của mạt học."]}, "038": {"title": "Nếu nhân quả nghiệp lực đã định sẵn, thì một niệm hướng thiện và sự tinh tấn tu hành của chúng sinh lúc này rốt cuộc còn thay đổi được gì?", "summary": "Nhân cũ đã gieo, hôm nay vẫn có thể thêm nhân mới; thỉnh hỏi tu hành thay đổi phương hướng như thế nào.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: nếu nhân quả nghiệp lực đã định sẵn từ lâu, thì một niệm hướng thiện, sự tinh tấn tu hành của chúng sinh ngay lúc này rốt cuộc còn có thể thay đổi được gì? Kính xin Bồ Tát từ bi khai thị.", "“Thiện nam tử,\ncon hỏi:\n‘Nếu nhân quả nghiệp lực đã định sẵn từ lâu,\nthì một niệm hướng thiện nay của chúng sinh,\ncòn có thể thay đổi được gì?’”\n“Nên biết,\nnếu nghiệp hoàn toàn định sẵn,\nthì chư Phật chẳng cần thuyết pháp;\nBồ Tát chẳng cần độ chúng sinh;\nchúng sinh cũng không còn ý nghĩa tu hành.”\n“Nhân quả chẳng phải định mệnh,\nnhân quả chính là nhân duyên.”\n“Nhân của quá khứ,\ncó thể thành quả hôm nay;\nnhân của hôm nay,\nlại thành quả của vị lai.”\n“Chúng sinh cho rằng,\nquả không thể đổi;\nnhưng chẳng biết,\nquả đã chín muồi,\ncó khi khó chuyển trọn;\nquả chưa chín muồi,\ncó thể nhờ nhân hiện tại mà chuyển.”\n“Ví như hạt giống vào đất,\nchưa nảy mầm;\nsiêng tưới cam lộ,\nthì mầm thiện được lớn;\nnếu buông thả cỏ dại,\nthì mầm thiện bị che lấp.”\n“Một niệm từ bi,\nchẳng diệt nhân cũ;\nlại có thể tăng trưởng nhân mới.”\n“Một niệm sám hối,\nchẳng đổi được hôm qua;\nlại có thể thay đổi ngày mai.”\n“Cho nên người tu hành,\nchẳng phải tranh đấu với nhân quả;\nmà là lìa xa vô minh.”\n“Biết nghiệp mà không sợ nghiệp,\ntin nhân mà siêng gieo nhân,\nấy gọi là chánh kiến.”\n“Nay con một niệm hướng thiện,\nchính là khởi đầu của ánh sáng ngày sau.”\n(Khai thị kết thúc)"]}, "039": {"title": "Thỉnh hỏi Địa Tạng Vương Bồ Tát về cách chư Phật, Bồ Tát thành tựu Chánh Đẳng Chánh Giác", "summary": "Từ tàm quý, nhân quả, chúng sinh đến tự tâm — ghi lại lời thỉnh hỏi về con đường giác ngộ.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: Ngài đã y theo phương pháp nào mà tu trì thành Chánh Đẳng Chánh Giác?", "Con hỏi:\nta xưa nương theo pháp gì mà thành Chánh Đẳng Chánh Giác.”\n“Nên biết,\nchư Phật tuy xuất thế có trước có sau,\nBồ Tát tuy nguyện hạnh có sai khác,\nsong lý được chứng,\nkhông có hai pháp.”\n“Chẳng phải đạo riêng của một mình ta,\ncũng chẳng phải chư Phật mỗi vị có đạo riêng.”\n“Đều nhờ giác ngộ tâm tánh,\nviên mãn từ bi,\nlợi ích chúng sinh,\nmà đến bờ bên kia.”\n“Trước lấy tàm quý làm thầy,\nkế lấy nhân quả làm thầy,\nlại lấy chúng sinh làm thầy,\nsau cùng lấy tự tâm làm thầy.”\n“Thấy khổ mà phát nguyện,\nthấy mê mà sinh bi,\nthấy tánh mà phá chấp,\nthấy không mà chẳng trụ nơi không.”\n“Chẳng phải một lần ngồi mà thành,\nchẳng phải một lần ngộ mà xong.”\n“Tu hành trải trần kiếp,\nmỗi hạnh đều là đạo;\nniệm niệm giác chiếu,\nchốn chốn đều là cửa.”\n“Nếu hỏi lối tắt thành Phật,\nnên biết:\nkhông có lối tắt.”\n“Nếu hỏi đường gần thành Phật,\nnên biết:\nphát tâm Bồ-đề,\nchính là đường gần.”\n(Khai thị kết thúc)"]}, "040": {"title": "“Chưa trải nỗi khổ của người, chớ khuyên người hướng thiện; nếu bạn trải nỗi khổ của tôi, chưa chắc đã thiện được như tôi” — có trái với tư tưởng Phật giáo không?", "summary": "Trước nỗi khổ của người khác, suy ngẫm về chừng mực của sự thấu hiểu, lời khuyên và lòng từ bi.", "blocks": ["Thỉnh hỏi Bồ Tát Địa Tạng: Bồ Tát nhìn nhận thế nào về câu nói “Chưa trải nỗi khổ của người, chớ khuyên người hướng thiện; nếu bạn trải nỗi khổ của tôi, chưa chắc đã thiện được như tôi”? Câu này có phải không phù hợp với tư tưởng Phật giáo?", "“Lời này chẳng hoàn toàn sai, song chỉ dừng ở tình phàm.\nThấy khổ mà dừng khuyên, là trí tự bảo vệ;\nbiết khổ mà phát lòng bi, là hạnh Bồ Tát.\nNếu lấy nỗi khổ của mình làm cánh cửa khước từ người,\nthì khổ thành ngã chấp, chẳng phải nhân giải thoát.”", "Câu nói này không hoàn toàn sai, nhưng tầng bậc của nó chỉ dừng lại ở cảnh giới phàm phu (dựa trên sự tự bảo vệ và phản ứng cảm xúc).\nThấy người khác chịu khổ mà chọn không khuyên nhủ, không can thiệp, đó là trí tuệ tự bảo vệ (thuộc về trí tuệ thế gian).\nBiết được bản chất chân thật của khổ đau, nhờ vậy khởi lòng từ bi, sẵn lòng giúp chúng sinh lìa khổ, đó là sự tu hành của Bồ Tát.\nNếu lấy nỗi khổ của chính mình làm cái cớ để khước từ người khác, khước từ sự trưởng thành, thì nỗi khổ ấy sẽ biến thành “ngã chấp” kiên cố, chứ không phải là nhân duyên giải thoát."]}, "041": {"title": "Lời khai thị của Bồ Tát Địa Tạng: vô ngã và nhân duyên của thiện và tuệ", "summary": "Từ mối quan hệ giữa “cái tôi” và việc thiện, thỉnh hỏi về vô ngã, từ bi và trí tuệ.", "blocks": ["Đệ tử xin hỏi Bồ Tát: nếu không có “cái tôi”, thì thiện và trí tuệ từ đâu mà sinh? “Cái tôi” mà chúng ta chấp trước, có thật sự cần thiết không?", "“Vô ngã chẳng phải không có,\nhữu ngã chẳng phải thật.\nChúng sinh chấp ngã,\nnên sinh phân biệt;\nBồ-đề lìa ngã,\nnên khởi từ bi.\nThiện chẳng do ngã tạo,\nmà do nhân duyên thành;\ntuệ chẳng phải ngã có,\nbản tánh tự sáng.\nNếu chấp có ngã,\nthiện dễ thành mạn;\nnếu chấp vô ngã,\nlại đọa không tịch.\nLìa kiến chấp hai bên,\ntrung đạo hiện tiền.\nĐiều con hỏi nay,\ngần với pháp yếu.\nNên biết tu hành,\nchẳng phải diệt thân;\nmà là phá chấp.\nChấp mất thì sáng,\ntrong sáng có bi;\ntrong bi có trí,\ntrong trí không ngã.”", "“‘Vô ngã’ không phải nói rằng chẳng có gì cả; ‘hữu ngã’ cũng không phải nói rằng thật sự có một cái tôi chân thật, bất biến. Chúng sinh vì chấp trước có một ‘cái tôi’, nên mới sinh ra tâm phân biệt; còn trí tuệ Bồ-đề, chính vì lìa được sự chấp trước vào ‘cái tôi’, nên mới có thể khởi lên lòng từ bi chân thật.\nViệc thiện không phải do ‘cái tôi’ tạo ra, mà do nhân duyên hòa hợp mà thành; trí tuệ cũng không phải là thứ ‘cái tôi’ sở hữu, mà là bản tánh tự nhiên hiển lộ.\nNếu chấp trước rằng ‘thật sự có một cái tôi’, việc thiện rất dễ biến thành ngã mạn (cảm thấy mình đang làm thiện, cao hơn người khác một bậc); nhưng nếu ngược lại chấp trước rằng ‘hoàn toàn không có cái tôi’, thì lại rơi vào một bên không tịch, tiêu cực, vô vi.\nLìa bỏ hai kiến giải cực đoan này, trung đạo mới hiển hiện.\nCâu hỏi con đang hỏi đây đã rất gần với cốt lõi của pháp.\nNên biết, tu hành không phải là diệt bỏ thân này (hay diệt bỏ chính con người mình), mà là phá trừ sự chấp trước vào ‘cái tôi’.\nChấp trước một khi được trừ bỏ, trí tuệ sẽ hiển lộ; trong trí tuệ tự nhiên mang theo từ bi; trong từ bi tự nhiên hàm chứa trí tuệ; và trong trí tuệ như vậy, không có một ‘cái tôi’ nào đứng ra làm chủ.”"]}, "042": {"title": "Cầu rồi sau mới xả — Bồ Tát Địa Tạng khai thị về trung đạo trong việc làm thiện", "summary": "Làm thiện có thể bắt đầu từ chỗ có điều mong cầu, rồi dần dần buông xả sự chấp trước vào báo đáp.", "blocks": ["Đệ tử xin hỏi Bồ Tát: người đời thường nói làm thiện mà cầu báo đáp thì không thuần, nhưng một người hoàn toàn dửng dưng với thiện ác, chẳng làm gì cả, dường như còn tệ hơn. Rốt cuộc phải dùng tâm như thế nào để làm thiện mới là đúng? Giữa việc thiện cầu công đức và việc thiện từ chân tâm, lằn ranh ấy nằm ở đâu?", "Ban đầu làm thiện,\nphần nhiều có cầu;\nấy chẳng phải lỗi lớn,\ncòn hơn chẳng làm.\nVì cầu mà làm thiện,\nhạt thiện đã gieo;\nlàm lâu chẳng thoái,\ntâm tự dần tịnh.\nNếu cầu danh lợi,\nthiện dễ cạn kiệt;\nnếu cầu giải thoát,\nthiện dần vô tư.\nChớ lo sơ tâm,\nchưa được thuần tịnh;\nchỉ lo tu lâu,\nchẳng chịu chuyển tâm.\nCông đức chẳng phải tội,\nchấp công thành chướng;\nbiết thiện có thể tu,\nbiết công có thể xả,\nấy là trung đạo.\nVí như trẻ nhỏ,\nmới tập bước đi;\ntuy nhờ thưởng khuyến,\nrốt cuộc tự đứng.\nThiện cũng như vậy,\ntừ chỗ có được,\ndần đến vô cầu.\nVô cầu chẳng phải đoạn,\nmà là từ bi thành;\ntâm quên nơi ngã,\nthiện hạnh thường trôi chảy.", "Người mới bắt đầu làm thiện, phần lớn đều mang tâm mong cầu, điều này không phải là lỗi lớn gì, dù sao vẫn tốt hơn hoàn toàn không làm thiện. Vì có điều mong cầu mà làm thiện, thì hạt giống thiện rốt cuộc cũng đã được gieo xuống; chỉ cần kiên trì lâu dài không thoái chuyển, tâm tự nhiên sẽ dần dần thanh tịnh lại.\nNếu điều mong cầu là danh lợi, thì việc thiện như vậy dễ có ngày cạn kiệt; nếu điều mong cầu là giải thoát, thì việc thiện như vậy sẽ dần dần trở nên vô tư.\nĐừng lo lắng rằng tâm ban đầu của mình chưa đủ thuần tịnh; điều thật sự nên lo, là tu đã lâu mà vẫn không chịu chuyển đổi tâm niệm của mình.\nBản thân công đức không phải là tội lỗi, chấp trước vào công đức mới trở thành chướng ngại. Biết rằng thiện là cần phải tu, cũng biết rằng công đức có thể buông xả, đó mới là trung đạo.\nCũng giống như đứa trẻ mới tập đi, tuy nhờ người lớn khen thưởng, khích lệ mới chịu bước, nhưng cuối cùng vẫn học được cách tự đứng, tự đi.\nLàm thiện cũng cùng một đạo lý như vậy: từ lúc đầu có điều mong cầu, có điều đạt được, dần dần đi đến cảnh giới không còn mong cầu.\nMà “không mong cầu” này không phải là đoạn tuyệt việc thiện, mà là sự thành tựu tự nhiên của lòng từ bi; khi trong tâm ngay cả “cái tôi” cũng đã quên, việc thiện sẽ như dòng nước, tự nhiên mà tiếp nối không ngừng."]}, "043": {"title": "Thế nào là “không”?", "summary": "Từ hình ảnh hoa nở hoa tàn và mây tụ thành mưa, đọc hiểu ẩn dụ về duyên khởi và tánh không.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: thế nào là không? Cúi xin Bồ Tát khai thị cho đại chúng.", "Chúng sinh nghe không, phần nhiều sinh sợ hãi;\ncho rằng không là hết thảy đều không có.\nVì thế mất nghĩa, rơi vào đoạn kiến.\nKhông chẳng phải không có, mà không tự tánh;\ncó là nương nhân duyên, duyên tan thì diệt.\nHoa nở chẳng phải thường, hoa tàn chẳng phải đoạn;\nmây tụ thành mưa, mưa tạnh lại về không.\nCon chấp nơi có, nên sinh tham luyến;\ncon chấp nơi không, nên sinh tuyệt vọng.\nLìa có lìa không, ấy gọi Trung đạo.\nBiết không mà chẳng bỏ, từ bi càng rộng;\nngộ không mà chẳng lìa, nhân quả rõ ràng.\nNếu thấy nghĩa không, chẳng hoại pháp thế gian;\nnếu trụ tướng không, trở lại mất chân không.\nVì thế người tu, nên quán các pháp,\nduyên khởi tánh không; tánh không duyên khởi,\nhai không sai biệt.", "Chúng sinh nghe đến “không”, phần lớn trong lòng sinh sợ hãi;\ncho rằng cái gọi là “không” nghĩa là mọi thứ đều chẳng còn gì, đã đoạn diệt.\nVì vậy mà đánh mất ý nghĩa chân thật của tánh không, rơi vào tà kiến đoạn diệt.\n“Không” không phải là “chẳng có gì tồn tại”,\nmà là nói mọi sự vật đều không có “bản chất tự ngã độc lập, bất biến”;\nsự tồn tại của hiện tượng là nương vào điều kiện nhân duyên mà sinh ra,\nnhân duyên tan đi thì hiện tượng cũng tan đi.\nHoa nở, nhưng sẽ không ở lại mãi mãi (không phải vĩnh hằng);\nhoa tàn, nhưng không phải “hoàn toàn đoạn diệt thành hư vô” (năm sau vẫn sẽ nở lại).\nMây tụ lại thành mưa, mưa rơi xuống rồi lại trở về “không”.\nCon chấp vào “có”, nên sinh ra tham luyến;\ncon chấp vào “không”, nên sinh ra tuyệt vọng.\nRời bỏ hai cực đoan “chấp có” và “chấp không”, đó gọi là Trung đạo.\nBiết “không” nhưng không vì thế mà bỏ từ bi, từ bi lại càng rộng lớn hơn;\nngộ “không” nhưng không vì thế mà rời bỏ thế gian, nhân quả vẫn rõ ràng minh bạch.\nNếu thật sự thấy được ý nghĩa của tánh không, sẽ không phá hoại quy luật vận hành của thế gian;\nnếu chấp vào “tướng không” (cho rằng không là một “trạng thái” hay “cảnh giới”), trái lại sẽ đánh mất chân không.\nCho nên người tu hành nên quán sát mọi hiện tượng\nđều là “duyên khởi mà tánh không”;\nvì “tánh không” nên mới có thể “duyên khởi”,\nhai điều này chẳng phải là hai thứ khác nhau, mà là hai mặt của một thể."]}, "044": {"title": "Người thân qua đời, nhớ thương có phải là chấp trước?", "summary": "Không cần ép mình quên đi người mình thương; hãy để nỗi nhớ đồng hành cùng việc tiếp tục sống.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: xin làm phiền Bồ Tát khai thị cho chúng sinh: “Sau khi người thân ruột thịt qua đời, nhớ thương có tính là một sự chấp trước không?”", "Người thân nếu mất, nhớ thương có tội gì?\nNhớ ân đức ấy, lòng sinh cảm hoài;\nnhớ tiếng nói dung nhan, lệ tự nhiên rơi.\nĐây chẳng phải chấp trước, mà là tình người.\nNếu nhớ mà chẳng ngại, nghĩ mà vẫn hành;\nnhớ càng sâu đậm, thiện tâm càng lớn.\nNếu chấp hình dáng, chẳng cho người đi;\nnếu oán vô thường, ngày ngày tự khổ;\nấy là chấp tướng.\nNên phải biết: nhớ thương có thể có, chấp trước có thể lìa.\nNgười thương người ấy, chẳng cần giam lòng mình.\nNgười nhớ ân ấy, có thể nối điều thiện ấy.\nNếu đem nhớ thương, tu phước hồi hướng;\nthì trong bi có nguyện, trong đau có từ.\nNgười tuy lìa đời, duyên chẳng đứt hẳn;\nhình lìa mà ân còn, tướng lìa mà thiện vẫn còn.\nChớ ép chính mình, quên người mình thương;\ncũng chớ ôm sầu chẳng buông.\nHãy để nhớ thương đến, để nước mắt tuôn;\ntuôn rồi, vẫn bước về phía trước.\nĐó chính là buông xả, chẳng phải lãng quên.", "Người thân đã qua đời, nhớ thương họ lẽ nào lại là một tội lỗi?\nHoài niệm ân đức của họ, trong lòng tự nhiên dâng lên niềm cảm hoài;\nnhớ lại giọng nói và gương mặt của họ, nước mắt tự nhiên tuôn rơi.\nĐây không phải là chấp trước, đây là tình cảm chân thật giữa người với người.\nNếu nỗi nhớ không ảnh hưởng đến cuộc sống bình thường của con, mà vẫn giúp con tiếp tục hành động;\nthì nỗi nhớ này càng sâu, thiện tâm của con lại càng tăng trưởng.\nNếu chấp vào hình ảnh trong quá khứ, không cho phép họ “thật sự ra đi”;\nnếu oán trách vô thường, mỗi ngày để mình chìm trong đau khổ;\nthì đó mới là “chấp vào tướng”.\nVì vậy phải biết: nhớ thương thì có thể có, chấp trước thì có thể buông xả.\nThật sự thương một người, không cần phải khóa chặt lòng mình trong quá khứ.\nHoài niệm ân tình của họ, có thể tiếp nối điều thiện mà họ để lại.\nNếu có thể chuyển nỗi nhớ này thành sức mạnh tu phước và hồi hướng;\nthì trong đau buồn sẽ có nguyện lực, trong khổ đau sẽ có từ bi.\nNgười tuy đã ra đi, nhưng duyên phận không hoàn toàn đứt đoạn;\nhình hài đã rời đi, nhưng ân tình vẫn còn; dáng vẻ đã mất, nhưng việc thiện vẫn còn.\nĐừng ép mình phải quên người mà con thương yêu;\ncũng đừng ôm chặt nỗi buồn mà không buông.\nCho phép nỗi nhớ đến, cho phép nước mắt chảy;\nchảy qua rồi, hãy tiếp tục bước về phía trước.\nĐó chính là buông xả, chứ không phải lãng quên."]}, "045": {"title": "Bồ Tát muốn độ chúng sinh có phải là một dục vọng? Câu hỏi chạm đến tâm can của Thái Khang Vĩnh", "summary": "Nguyện có phương hướng, dục có chấp thủ; suy ngẫm về sự khác biệt giữa đại nguyện và tham cầu.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\nThái Khang Vĩnh (Kevin Tsai) khi được phỏng vấn trong chương trình của Lương Tử từng công khai nói rằng ông muốn hỏi Bồ Tát: muốn phổ độ chúng sinh, chẳng phải chính là một dục vọng sao?\nNếu Ngài có dục vọng, vào những lúc chưa đạt được, lẽ nào Ngài lại không cảm thấy thất vọng?", "Dục có hai loại: một là thủ trước, một là đại nguyện.\nCùng gọi là dục, mà tâm chẳng đồng.\nNếu muốn danh lợi, vì mình cầu lấy;\nchẳng được thì oán, được rồi lại sợ mất, dục này trói buộc.\nNếu nguyện chúng sinh, lìa khổ được vui;\ntuy nguyện thành tựu, chẳng dùng sức ta cưỡng cầu,\ntuy cầu chẳng được, cũng chẳng lui thiện.\nVì thế đại nguyện, chẳng đồng tham dục.\nNguyện có phương hướng, dục có chấp thủ;\nnguyện buông được quả, dục ắt nắm quả.\nBồ Tát phát nguyện, chẳng phải không cần kết quả,\nmà là không bị kết quả trói buộc.\nNếu độ chúng sinh mà chẳng độ được, vẫn chẳng mất từ bi;\nnếu làm thiện mà không ai biết, vẫn nguyện làm thiện;\nnếu cầu pháp mà chưa chứng đắc, vẫn chẳng thoái chuyển.\nẤy mới là nguyện.\nNếu tâm muốn độ chúng, chỉ để chứng minh mình,\nchỉ để thành tựu mình, chỉ để được chúng sinh tán thán,\nthì tuy miệng nói từ bi, tâm vẫn đang cầu lấy.\nCho nên chớ hỏi có dục hay không dục, hãy hỏi tâm này:\nVì mình chăng? Vì người chăng? Chấp quả chăng? Hành nguyện chăng?\nNguyện mà chẳng được, nếu an trụ được;\ncầu mà chẳng được, nếu sinh sân hận,\nchỗ khác biệt ấy, nơi đây thấy rõ.\nChúng sinh làm thiện, ban đầu cũng có thể có chỗ cầu;\nBồ Tát phát nguyện, cũng chẳng phải không chỗ cầu.\nChỉ là đi đến chỗ sâu, dần lìa nơi ngã, dần lìa nơi đắc.\nNếu một niệm từ bi, vẫn còn tâm cầu, chớ vội tự trách;\nchỉ cần soi thấy, dần dần buông xả.\nChân thật vô cầu, chẳng phải không nguyện điều gì;\nmà là nguyện mà chẳng buộc, hành mà chẳng chấp.", "Dục vọng có hai loại: một loại là “chấp thủ”, một loại là “đại nguyện”.\nTuy đều gọi là “dục”, nhưng bản chất tâm thái của chúng khác nhau.\nNếu theo đuổi danh lợi, là vì bản thân mà cầu lấy;\nkhông được thì oán trách, được rồi lại sợ mất — loại dục vọng này sẽ trói buộc con.\nNếu là phát nguyện cho chúng sinh lìa khổ được vui;\ntuy mong điều đó được thành tựu, nhưng không dùng sức của mình để cưỡng cầu kết quả,\ndù cầu không được, cũng không vì thế mà thoái mất thiện tâm.\nCho nên nói, đại nguyện không đồng nghĩa với tham dục.\nNguyện có phương hướng, dục có chấp thủ;\nnguyện có thể buông bỏ kết quả, dục thì nhất định phải nắm lấy kết quả.\nBồ Tát phát nguyện, không phải là không cần kết quả,\nmà là không bị kết quả trói buộc.\nNếu độ chúng sinh mà không độ được, vẫn không mất đi từ bi;\nnếu làm việc thiện mà không ai biết, vẫn nguyện tiếp tục làm việc thiện;\nnếu cầu pháp mà chưa chứng đắc, vẫn không thoái chuyển.\nĐó gọi là nguyện.\nNếu trong lòng con muốn độ chúng sinh chỉ để chứng minh bản thân,\nchỉ để thành tựu bản thân, chỉ để được chúng sinh tán thán,\nthì dù miệng nói từ bi, trong lòng vẫn đang cầu lấy.\nCho nên đừng hỏi “có dục vọng hay không”,\nmà nên tự hỏi tâm mình: là vì mình? Hay vì người khác? Là chấp vào kết quả? Hay đang thực hành tâm nguyện?\nPhát nguyện mà chưa đạt được, nếu vẫn có thể an trụ;\ncầu lấy mà không được, nếu vì thế sinh lòng sân hận —\nsự khác biệt giữa hai điều này, có thể nhìn thấy ngay từ đây.\nChúng sinh làm việc thiện, lúc đầu cũng có thể có điều mong cầu;\nBồ Tát phát nguyện, cũng không phải hoàn toàn không có điều mong cầu.\nChỉ là khi tu hành đến chỗ sâu, sẽ dần dần rời xa cái “ngã”, dần dần rời xa sự “được”.\nNếu trong một niệm từ bi vẫn còn tâm cầu lấy, đừng vội trách mình;\nchỉ cần nhìn thấy nó, rồi dần dần buông xả là được.\n“Vô cầu” chân thật, không phải là không muốn gì cả;\nmà là “nguyện mà chẳng buộc, hành mà chẳng chấp” — có nguyện, nhưng không bị nguyện trói buộc; có hành động, nhưng không chấp vào kết quả."]}, "046": {"title": "Nói thật chưa hẳn là thiện; nói dối chưa hẳn là ác", "summary": "Khi lời thật và thiện ý dường như xung đột, suy ngẫm về lời nói, thời điểm và tâm không lừa dối.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: “Đệ tử xin hỏi Bồ Tát: lời nói dối thiện ý để không làm tổn thương người khác, có tính là phạm giới vọng ngữ không? Nếu lời thật và từ bi xung đột, nên lấy điều nào làm trước?”", "Giới vọng ngữ, chẳng chỉ xét thật hay giả; cũng nên quán nơi tâm.\nNếu biết rõ là dối, dùng tâm gian trá mà nói, khiến người bị hại, ấy là vọng ngữ.\nNếu vì hộ người, chẳng để họ chịu khổ; tâm không lừa hại, lời nói có phương tiện thiện xảo; chỗ này nên phân biệt kỹ.\nLời thật có thể tổn thương người, lời dối cũng có thể hại người; từ bi và chân thật, không thể dễ dàng nói chọn bên nào, bỏ bên nào.\nNếu lời thật thốt ra, chỉ để trút giận; tuy lời chân thật, cũng chẳng phải từ bi.\nNếu lời thiện ý, chẳng để lừa dối, chẳng vì lợi mình, chỉ mong dứt khổ, thì nên quán phương tiện.\nNói thật được mà chẳng hại, nên nói thật; nói chậm được thì nói chậm; nói ít được thì nói ít; chẳng cần đem hết sự thật, nói thẳng tất cả.\nNếu ngay lúc ấy chẳng thể nói, có thể im lặng; nếu im lặng chẳng thể che chở, thì dùng lời thiện xảo.\nSong chẳng được mượn danh từ bi, che đậy tham dục, sợ hãi và tư tâm của mình.\nCho nên giữ giới vọng ngữ, chẳng phải bảo người chỉ giữ câu chữ; mà là giữ gìn: tâm chân thật, tâm thiện ý, tâm không lừa dối.\nLời thật mà không có từ bi, dễ thành dao bén; từ bi mà không trí tuệ, cũng có thể thành việc làm ngu dại.\nCho nên phải dùng trí tuệ, khiến chân thật và từ bi, cùng nhau thành tựu.\nThật được thì thật, thiện được thì thiện; bất đắc dĩ mới phương tiện, tâm chẳng dối người, về sau cũng chẳng tự dối mình.\nHành trì như thế, mới gần thiện xảo.", "Việc giữ giới vọng ngữ, không chỉ là kiểm tra lời nói ra là thật hay giả; mà còn phải quán sát “tâm” khi nói câu ấy đang ở trạng thái nào.\nNếu biết rõ là giả, lại dùng tâm lừa dối để nói, khiến người khác bị tổn hại, thì đó chính là vọng ngữ.\nNếu là để bảo vệ người khác, không muốn họ chịu khổ, trong lòng không có ý lừa dối hay làm hại, lời nói dùng cách nói phương tiện — chỗ này cần phải phân biệt kỹ lưỡng.\nLời thật có thể làm tổn thương người, lời giả cũng có thể hại người; giữa từ bi và chân thật, không thể dễ dàng nói rằng “chọn cái này là được”.\nNếu con nói thật chỉ để trút cảm xúc, dù nội dung là thật, thì đó cũng không phải là từ bi.\nNếu con nói lời thiện ý, không phải để lừa dối, không phải vì lợi ích của bản thân, chỉ mong giảm bớt nỗi khổ của đối phương, thì cần quán sát đâu là cách “phương tiện”.\nNếu có thể nói thật mà không làm tổn thương đối phương, thì hãy nói thật;\nnếu có thể để muộn hơn mới nói, thì hãy để muộn hơn;\nnếu có thể nói ít, thì hãy nói ít;\nkhông cần phải nói thẳng ra toàn bộ sự thật.\nNếu ngay lúc ấy thật sự không thể nói, có thể giữ im lặng;\nnếu im lặng không thể bảo vệ đối phương, thì hãy dùng lời lẽ thiện xảo.\nNhưng không được nhân danh “từ bi” để che đậy tham dục, sợ hãi hay tư tâm của chính mình.\nCho nên giữ giới vọng ngữ, không phải đòi hỏi người ta khư khư giữ lấy cái thật cái giả trên mặt chữ;\nmà là giữ gìn ba tâm: tâm chân thật, tâm thiện ý, tâm không lừa dối.\nLời thật nếu không có từ bi, dễ biến thành con dao làm tổn thương người;\nhành động từ bi nếu không có trí tuệ, cũng có thể biến thành việc làm ngu dại.\nCho nên phải dùng trí tuệ, để chân thật và từ bi cùng nhau thành tựu.\nCó thể chân thật thì chân thật, có thể lương thiện thì lương thiện;\nkhi bất đắc dĩ cần dùng phương tiện, trong lòng đừng lừa dối người, về sau cũng đừng lừa dối chính mình.\nHành trì như vậy, mới gần với trí tuệ “thiện xảo”."]}, "047": {"title": "Luôn làm việc thiện, sao khổ nạn vẫn tìm đến tôi?", "summary": "Khi khổ nạn đến, đừng vội nghi ngờ việc thiện hay tự trách mình; trước hết hãy xử lý nỗi khổ trước mắt.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: đệ tử xin hỏi Bồ Tát: đệ tử tin nhân quả, làm thiện tích đức, nhưng khổ nạn vẫn liên tiếp kéo đến. Lúc này nên nghi ngờ mình tu chưa đủ, hay nghi ngờ chính nhân quả?", "Con làm thiện mà gặp khổ, chớ vội nghi thiện, cũng chớ vội trách mình.\nLẽ nhân quả, chẳng phải hôm nay gieo thiện, ngày mai liền hết khổ.\nMột quả thành tựu, do muôn duyên hòa hợp; một khổ kéo đến, cũng chẳng do một nhân mà sinh.\nNhân của ngày xưa, duyên của hôm nay, việc làm của người khác, biến đổi của thế gian, đều có thể hội tụ vào lúc này.\nCho nên làm thiện, chẳng phải là giao dịch với trời đất.\nChớ nói: ‘Ta đã làm thiện, cớ sao còn khiến ta chịu khổ?’\nNếu đem thiện đổi lấy thuận, thuận cảnh chẳng đến, thiện tâm liền lui, thiện ấy còn có chỗ cầu.\nNhưng cũng chẳng thể mỗi khi gặp khổ nạn, liền tự trách rằng: ‘Ắt là ta tu chưa đủ, ắt là nghiệp chướng của ta sâu nặng.’\nNhư thế cũng là chấp trước.\nCó những khổ, chẳng phải vì con bất thiện;\ncó những nạn, cũng chẳng phải để trừng phạt con.\nSinh lão bệnh tử, hợp tan được mất, thế gian vô thường, chúng sinh đều có lúc gặp.\nLợi ích của tu hành, chẳng ở chỗ bảo đảm một đời không nạn;\nmà ở chỗ khi khổ đến, con so với trước bớt một phần oán, thêm một phần sáng;\nbớt tạo một phần ác, thêm sinh một phần từ bi.\nNếu làm thiện chỉ để tránh khổ, khổ đến thì lòng tin lay động.\nNếu biết thiện vốn nên làm, dù nghịch cảnh hiện tiền, vẫn chẳng lấy ác trả ác,\nlúc ấy mới biết căn lành đang tăng trưởng.\nCòn về nhân quả, chớ hiểu là sổ sách thưởng thiện phạt ác.\nNhân thiện có quả thiện, nhân ác có quả ác;\nsong quả chín muồi, có chậm có nhanh, có hiện có ẩn, nhân duyên chằng chịt, chẳng phải phàm phu nhất thời thấy hết được.\nCon nếu chịu khổ, trước hãy xử lý cái khổ trước mắt;\nchữa được thì chữa, sửa được thì sửa, tránh được thì tránh, cầu giúp được thì cầu giúp.\nChẳng thể vì nói nhân quả, mà mặc khổ chẳng chữa;\ncũng chẳng thể vì gặp khổ, mà cho rằng làm thiện vô ích.\nKhổ đến, chẳng cần trước nghi nhân quả; cũng chẳng cần trước nghi chính mình.\nTrước hãy hỏi: ‘Trong việc này, hiện giờ ta có thể làm gì?’\nChỗ sửa được, dũng cảm sửa;\nchỗ chẳng sửa được, học cách chịu đựng;\nchỗ nên cầu giúp, chớ lấy tu hành thay cho cầu giúp.\nĐiều con thật sự nên quán sát, chẳng phải là:\n‘Ta làm bao nhiêu thiện, đổi được bao nhiêu phước?’\nmà là:\n‘Trải qua những khổ nạn này, tâm ta có sáng suốt từ bi hơn trước chăng?’\nNếu được như thế, khổ tuy chưa hết, đạo đã đang hành.", "Con làm việc thiện mà lại gặp khổ nạn, đừng vội nghi ngờ việc thiện, cũng đừng vội trách bản thân.\nĐạo lý nhân quả, không phải hôm nay gieo nhân thiện thì ngày mai sẽ không còn đau khổ.\nMột kết quả hình thành cần rất nhiều nhân duyên hội tụ; một nỗi khổ kéo đến, cũng không phải do một nguyên nhân duy nhất gây ra.\nNhân của quá khứ, duyên của hiện tại, hành vi của người khác, sự đổi thay của hoàn cảnh, đều có thể hội tụ vào cùng một thời điểm.\nCho nên làm việc thiện, không phải là làm giao dịch với trời đất.\nĐừng nói: “Tôi đã làm việc thiện rồi, tại sao vẫn để tôi chịu khổ?”\nNếu làm thiện chỉ để đổi lấy thuận cảnh, khi thuận cảnh không đến, thiện tâm liền thoái lui; việc thiện như vậy vẫn còn có điều mong cầu.\nNhưng cũng không được hễ gặp khổ nạn là trách bản thân rằng: “Chắc chắn là tôi tu chưa đủ tốt, chắc chắn là nghiệp chướng của tôi quá nặng.”\nLàm như vậy cũng là một loại chấp trước.\nCó những khổ nạn, không phải vì con không tốt;\ncó những nghịch cảnh, cũng không phải để trừng phạt con.\nSinh lão bệnh tử, hợp tan được mất, thế gian vốn dĩ vô thường, chúng sinh ai cũng sẽ gặp phải.\nLợi ích mà tu hành mang lại, không nằm ở chỗ bảo đảm một đời không có khổ nạn;\nmà nằm ở chỗ khi khổ nạn đến, con so với trước kia bớt đi một phần oán hận, thêm một phần hiểu lẽ;\nbớt tạo một phần nghiệp ác, thêm sinh một phần từ bi.\nNếu làm việc thiện chỉ để tránh khổ nạn, thì khi khổ nạn đến, lòng tin sẽ lung lay.\nNếu biết làm thiện vốn là điều nên làm, dù nghịch cảnh hiện ra trước mắt, vẫn không lấy ác báo ác,\nthì lúc ấy mới thật sự biết rằng căn lành đang tăng trưởng.\nCòn về nhân quả, đừng hiểu nó như một cuốn sổ sách thưởng thiện phạt ác.\nNhân thiện có quả thiện, nhân ác có quả ác;\nnhưng sự chín muồi của quả báo có nhanh có chậm, có rõ ràng có ẩn kín, nhân duyên đan xen phức tạp, không phải người phàm trong chốc lát có thể nhìn thấy hết.\nNếu con gặp khổ nạn, trước hết hãy xử lý vấn đề trước mắt;\nđi khám bệnh được thì đi khám bệnh, thay đổi được thì thay đổi, tránh được thì tránh, tìm người giúp được thì tìm người giúp.\nKhông được vì có quan niệm nhân quả mà mặc kệ nỗi khổ không xử lý;\ncũng không được vì gặp khổ nạn mà cho rằng làm việc thiện là vô ích.\nKhi khổ nạn đến, không cần trước tiên nghi ngờ nhân quả; cũng không cần trước tiên nghi ngờ bản thân.\nTrước hết hãy hỏi: “Vào lúc này, ngay bây giờ tôi có thể làm gì?”\nChỗ nào có thể thay đổi, hãy dũng cảm thay đổi;\nchỗ nào không thể thay đổi, hãy học cách chấp nhận;\nchỗ nào cần tìm sự giúp đỡ, đừng lấy “tu hành” thay cho việc tìm sự giúp đỡ.\nĐiều con thật sự nên quán sát, không phải là:\n“Tôi đã làm bao nhiêu việc thiện, đổi được bao nhiêu phước báo?”\nmà là:\n“Sau khi trải qua những khổ nạn này, tâm tôi có sáng suốt hơn, từ bi hơn trước kia hay không?”\nNếu được như vậy, thì khổ nạn tuy chưa kết thúc, nhưng con đã đang bước đi trên con đường tu hành rồi."]}, "048": {"title": "Sau khi thấy mặt tối nhất của nhân tính, có nên tiếp tục tin người?", "summary": "Từ bi có thể vô lượng, lòng tin phải có chừng mực; giữ lại trí tuệ và ranh giới cho thiện ý.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát: nếu một người đã thấy quá nhiều ích kỷ, phản bội, bạo lực và lừa dối, thì còn nên tin vào nhân tính không? Làm sao để vừa không ngây thơ, lại vừa không vì thế mà mất đi lòng từ bi và niềm tin đối với chúng sinh?", "Con thấy điều ác nơi nhân gian, mà hỏi có còn tin người được chăng,\ncâu hỏi này chẳng phải vì con không từ bi, mà vì thấy khổ dần sâu.\nChúng sinh có thiện, cũng có ác;\ncó từ bi, cũng có tham, sân, si.\nCho nên người tu, chẳng cần cho rằng ai ai cũng thiện, mới có thể từ bi.\nBiết họ có thể làm ác, vẫn chẳng muốn lấy ác đối đãi; ấy là từ bi.\nNếu biết rõ họ lừa, vẫn mặc họ lừa, ấy chẳng phải từ bi, là thiếu trí tuệ.\nNếu biết rõ họ hại, vẫn chẳng tránh hại, ấy chẳng phải lương thiện, là thiếu phòng hộ.\nPhật pháp chẳng dạy con nhận kẻ ác làm người thiện;\ncũng chẳng dạy con vì thấy kẻ ác, liền cho rằng chúng sinh đều ác.\nĐiều nên tin, chẳng phải ‘ai ai cũng đáng tin’;\nđiều nên tin, là tâm chúng sinh chẳng phải mãi mãi không đổi.\nKẻ tham hôm nay, có thể biết đủ;\nkẻ sân hôm nay, có thể tỉnh ngộ;\nkẻ mê hôm nay, cũng có thể tỉnh thức.\nSong khi họ chưa đổi, con vẫn phải phòng điều ác của họ.\nTừ bi có thể vô lượng, lòng tin phải có chừng mực.\nTừ bi là nguyện họ lìa khổ, lòng tin thì phải do hành vi của họ chứng minh.\nCho nên có thể từ bi với một người, mà chẳng cho họ vay tiền;\ncó thể nguyện một người hướng thiện, mà chẳng còn cùng họ làm việc;\ncó thể tha thứ một người, mà chẳng để họ lại làm hại con;\ncó thể chẳng ôm hận, mà vẫn giữ khoảng cách với họ.\nNhững điều ấy đều chẳng trái từ bi.\nCon nếu vì từng bị lừa, từ đó chẳng tin ai cả,\nthì cái ác của một người, lại khiến vô số người chưa từng hại con phải chịu sự nghi ngờ của con trước.\nCon nếu vì muốn tin nhân tính, liền bỏ qua mọi việc ác,\nthì từ bi lại thành ngu si.\nCho nên nên học:\nthấy thiện mà chẳng mù quáng tin, thấy ác mà chẳng tuyệt vọng.\nXem người, quán hành vi lâu dài; nghe lời, cũng xét có làm được chăng.\nLòng tin trao dần, ranh giới lập trước.\nMột lần lừa dối, có thể khoan thứ; có tin lại hay không, thì xem họ có thật sự sửa lỗi chăng.\nChúng sinh đáng được từ bi, chẳng có nghĩa chúng sinh đều đáng tin.\nĐiều con thật sự phải giữ, chẳng phải ảo tưởng ‘nhân tính ắt thiện’;\nmà là chớ vì thấy hết bóng tối nhân gian, liền để bóng tối vào trong tâm mình.\nThấy người ích kỷ, con vẫn học bố thí;\nthấy người phản bội, con vẫn giữ chữ tín;\nthấy người bạo lực, con chẳng lấy bạo chế bạo;\nthấy người lừa dối, con vẫn giữ chân thật.\nNhư thế, cái ác thế gian chẳng biến con thành người mà con chán ghét.\nẤy thật khó được.\nChẳng ngây thơ, là có trí tuệ; chẳng tuyệt vọng, là có từ bi.\nBiết ác mà phòng ác, thấy khổ mà thương khổ; chẳng dung túng, cũng chẳng thù hận.\nHành như thế, chính là Trung đạo.", "Con nhìn thấy đủ mọi việc ác nơi nhân gian, rồi hỏi: “Còn nên tin vào nhân tính nữa không?”\nCâu hỏi này nảy sinh, không phải vì con thiếu từ bi, mà vì những nỗi khổ con từng thấy ngày càng nhiều.\nTrong chúng sinh có lương thiện, cũng có tà ác;\ncó từ bi, cũng có tham, sân, si.\nCho nên người tu hành không cần phải xem mỗi người đều là người lương thiện thì mới có thể từ bi với người.\nBiết một người có thể làm ác, nhưng vẫn không muốn lấy ác báo ác — đó mới gọi là từ bi.\nNếu biết rõ đối phương đang lừa dối, mà lại mặc cho họ tiếp tục lừa dối, đó không phải là từ bi, đó là thiếu trí tuệ.\nNếu biết rõ đối phương sẽ gây tổn hại, mà lại không bảo vệ chính mình, đó không phải là lương thiện, đó là thiếu sự phòng hộ.\nPhật pháp không dạy con “phải xem kẻ ác như người thiện”;\nPhật pháp cũng không dạy con “vì nhìn thấy kẻ ác mà cho rằng tất cả chúng sinh đều xấu ác”.\nĐiều thật sự đáng tin, không phải là “mỗi người đều đáng tin cậy”;\nđiều thật sự đáng tin, là “tâm chúng sinh không phải mãi mãi không thay đổi”.\nNgười hôm nay tham lam, tương lai có thể sẽ biết đủ;\nngười hôm nay sân giận, tương lai có thể sẽ tỉnh ngộ;\nngười hôm nay mê muội, tương lai cũng có thể sẽ thức tỉnh.\nNhưng trước khi họ thay đổi, con vẫn cần đề phòng những hành vi xấu ác của họ.\nTừ bi có thể là vô hạn, nhưng lòng tin phải có chừng mực.\nTừ bi là “mong họ lìa khổ”, còn lòng tin thì phải được chứng minh bằng hành vi của họ.\nCho nên, con có thể từ bi với một người, nhưng không nhất thiết phải cho họ vay tiền;\ncon có thể mong một người quay đầu hướng thiện, nhưng không còn cùng họ làm việc nữa;\ncon có thể tha thứ cho một người, nhưng không để họ lại làm tổn thương con lần nữa;\ncon có thể không ôm oán hận trong lòng, nhưng vẫn giữ khoảng cách.\nNhững điều này đều không trái với từ bi.\nNếu con vì từng bị lừa mà từ đó không còn tin bất kỳ ai nữa,\nthì cái ác của một người lại khiến vô số người chưa từng làm hại con phải gánh chịu sự nghi ngờ của con trước.\nNếu con vì muốn “tin vào nhân tính” mà bỏ qua mọi dấu hiệu của hành vi xấu ác,\nthì lòng từ bi của con sẽ biến thành ngu si.\nCho nên nên học cách:\nnhìn thấy cái thiện, nhưng không mù quáng tin theo;\nnhìn thấy cái ác, nhưng không vì thế mà tuyệt vọng.\nNhìn một người, phải nhìn hành vi lâu dài của họ;\nnghe một lời nói, cũng phải xem họ có thật sự làm được hay không.\nLòng tin phải trao từ từ, ranh giới phải đặt ra trước.\nMột lần lừa dối, có thể khoan thứ;\nnhưng có tin lại hay không, phải xem đối phương có thật sự sửa đổi hay chưa.\nChúng sinh đáng để con từ bi, không có nghĩa là mỗi chúng sinh đều đáng để con tin cậy.\nĐiều con thật sự nên giữ, không phải là ảo tưởng “nhân tính nhất định là lương thiện”;\nmà là đừng vì đã nhìn thấu bóng tối của thế gian, mà để bóng tối cũng trú ngụ trong lòng con.\nThấy người khác ích kỷ, con vẫn học hạnh bố thí;\nthấy người khác phản bội, con vẫn giữ chữ tín;\nthấy người khác bạo lực, con không lấy bạo lực chế ngự bạo lực;\nthấy người khác lừa dối, con vẫn giữ gìn sự chân thật.\nNhư vậy, cái ác của thế gian đã không biến con thành loại người mà chính con chán ghét.\nĐó mới là điều khó có được.\nKhông ngây thơ, là vì có trí tuệ;\nkhông tuyệt vọng, là vì có từ bi.\nBiết ác mà phòng ngừa ác, thấy khổ mà thương xót khổ; không dung túng, cũng không thù hận.\nLàm được như vậy, chính là Trung đạo."]}, "049": {"title": "Nhân tánh vốn thiện, vốn ác hay tùy nhân duyên mà chuyển?", "summary": "Không đóng khung con người là thiện hay ác, mà quán sát tập khí, hoàn cảnh và lựa chọn ngay trong hiện tại.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\nCâu hỏi: Nhân tánh rốt cuộc vốn thiện, vốn ác, hay tùy nhân duyên mà chuyển?", "Nếu nói nhân tánh vốn thiện,\ncớ sao chúng sinh\nlại khởi tham, sân, si?\nNếu nói nhân tánh vốn ác,\ncớ sao kẻ ác\ncũng có thể một niệm tỉnh ngộ?\nCho nên hai chữ thiện ác,\nkhông thể định hết tâm chúng sinh.\nTâm của chúng sinh\ntheo nhân duyên mà khởi,\ntheo tập khí mà động,\ntheo điều được huân tập mà chuyển.\nMột niệm tham khởi lên,\ncó thể làm điều ác;\nmột niệm từ sinh ra,\ncũng có thể làm điều thiện.\nThiện niệm thường huân,\nthiện căn dần lớn;\nác niệm thường tập,\nác nghiệp dần sâu.\nCho nên người thiện hôm nay,\nnếu không giữ gìn tâm,\ncũng có thể làm ác;\nngười ác hôm nay,\nnếu biết lỗi mình,\ncũng có thể chuyển thành thiện.\nCon người không sinh ra đã mãi thiện,\ncũng không sinh ra đã mãi ác;\ntâm theo duyên mà khởi,\nhành do niệm mà thành.\nNhưng con chớ vì thế mà nói:\n‘Đã là tùy duyên,\nthì thiện ác chẳng còn ý nghĩa.’\nChính vì tâm có thể chuyển,\ntu hành mới có ý nghĩa.\nNếu tất cả sinh ra đã định,\nkẻ ác mãi ác,\nngười thiện mãi thiện,\nthì cần gì giáo hóa?\nCần gì sám hối?\nCần gì tu hành?\nChúng sinh có vô minh,\nnên mới tạo ác;\nchúng sinh cũng có giác tánh,\nnên biết ác mà sửa.\nNhư nước vốn không hình cố định,\nvào bình vuông thì vuông,\nvào bình tròn thì tròn;\nnhưng nước nếu bị vẩn đục,\nvẫn có thể lắng trong.\nTâm cũng như vậy.\nSự dạy dỗ của gia đình,\nsự giao du với bạn bè,\nhoàn cảnh nơi mình sống,\ntập khí của bản thân,\nkinh nghiệm trong quá khứ,\nđều có thể thành duyên.\nNhưng nhân duyên ảnh hưởng con,\nkhông có nghĩa là nhân duyên\nquyết định thay con tất cả.\nKhi cảnh đến,\ncon vẫn còn một niệm\nđể lựa chọn.\nCó người làm hại con,\ncon có thể báo thù,\ncũng có thể dừng ác mà không báo thù;\ncó người lừa dối con,\ncon có thể học theo sự dối trá ấy,\ncũng có thể nhân đó\ncàng giữ chữ tín hơn.\nCho nên tu hành không phải chờ đợi\nnhân duyên tốt khiến mình thành thiện,\nmà là khi nhân duyên hiện tiền,\nhọc cách chọn điều thiện.\nNếu con hỏi:\n‘Vậy con có nên tin vào nhân tánh không?’\nChớ tin chúng sinh\nvĩnh viễn không làm ác;\ncũng chớ tin chúng sinh\nvĩnh viễn không thể thay đổi.\nBiết người có thể ác,\nnên có trí tuệ phòng hộ;\nbiết người có thể thiện,\nnên không bỏ từ bi.\nThấy người ác,\nphòng điều ác của họ,\nmà không dứt đi\nkhả năng sửa lỗi của họ;\nthấy người thiện,\nkính điều thiện của họ,\ncũng không đem họ\ntôn làm người không bao giờ lầm lỗi.\nNhìn người như thế,\nsẽ ít thất vọng,\ncũng ít thiên chấp.\nĐiều Phật pháp coi trọng,\nkhông phải tranh luận\nnhân tánh rốt cuộc nên dán\ncái tên ‘thiện’ hay ‘ác’,\nmà là hỏi con:\nmột niệm ngay lúc này,\nsẽ đi về đâu?\nMột niệm rồi một niệm,\nthành tập khí;\ntập khí lâu ngày,\nhình thành nên con người ấy;\nngười nếu biết tỉnh giác,\ntập khí cũng có thể chuyển.\nCho nên Ta nói:\nthiện ác không phải bất di bất dịch,\nnhân duyên không phải định mệnh;\ntâm chúng sinh có thể chuyển,\ncho nên chúng sinh có thể được độ.", "Nếu nói nhân tánh vốn dĩ là thiện, thì tại sao chúng sinh vẫn khởi lên tham, sân, si?\nNếu nói nhân tánh vốn dĩ là ác, thì tại sao kẻ ác cũng có thể tỉnh ngộ chỉ trong một niệm?\nCho nên hai chữ “thiện” và “ác” không thể định nghĩa trọn vẹn tâm của chúng sinh.\nTâm của chúng sinh sinh khởi theo nhân duyên, bị tập khí lôi kéo, và chuyển biến theo sự huân nhiễm mình chịu hằng ngày.\nMột niệm tham khởi lên thì có thể làm ra việc ác;\nmột niệm từ bi khởi lên thì cũng có thể làm ra việc thiện.\nThiện niệm không ngừng được huân tập, thiện căn sẽ từ từ lớn lên;\nác niệm không ngừng lặp lại, ác nghiệp sẽ dần dần sâu thêm.\nCho nên người thiện hôm nay, nếu không giữ gìn tâm mình, cũng có thể làm điều ác;\nngười ác hôm nay, nếu biết được lỗi lầm, cũng có thể quay về đường thiện.\nCon người không phải sinh ra là mãi mãi thiện, cũng không phải sinh ra là mãi mãi ác;\ntâm chuyển động theo nhân duyên, hành vi do niệm mà thành.\nNhưng con không thể vì thế mà nói: “Đã là mọi thứ đều tùy nhân duyên, thì thiện ác chẳng còn ý nghĩa gì.”\nChính vì tâm có thể chuyển đổi, nên tu hành mới có ý nghĩa.\nNếu tất cả đều đã được định sẵn từ lúc sinh ra, kẻ ác mãi mãi là ác, người thiện mãi mãi là thiện,\nthì cần gì giáo hóa? Cần gì sám hối? Cần gì tu hành?\nChúng sinh vì có vô minh nên mới tạo ác;\nchúng sinh cũng có giác tánh nên có thể biết ác mà sửa đổi.\nGiống như nước vốn không có hình dạng cố định, đổ vào bình vuông thì thành vuông, đổ vào bình tròn thì thành tròn;\nnhưng nước nếu bị vẩn đục cũng có thể lắng trong trở lại.\nTâm cũng như vậy.\nSự giáo dục của gia đình, sự giao du với bạn bè, môi trường mình sống, tập khí của bản thân, những kinh nghiệm trong quá khứ,\ntất cả đều có thể trở thành nhân duyên.\nNhưng nhân duyên ảnh hưởng con không có nghĩa là nhân duyên đã quyết định thay con mọi thứ.\nKhi cảnh giới đến, con vẫn còn một niệm để lựa chọn.\nCó người làm hại con, con có thể chọn báo thù, cũng có thể chọn dừng điều ác lại mà không báo thù;\ncó người lừa dối con, con có thể học theo mà đi lừa dối người khác, cũng có thể nhân đó mà càng giữ chữ tín hơn.\nCho nên tu hành không phải là chờ đợi nhân duyên tốt đến khiến mình trở nên thiện,\nmà là khi nhân duyên hiện tiền, học cách lựa chọn điều thiện.\nNếu con hỏi: “Vậy con có nên tin vào nhân tánh không?”\nĐừng tin rằng chúng sinh vĩnh viễn không làm ác;\ncũng đừng tin rằng chúng sinh vĩnh viễn không thể thay đổi.\nBiết rằng con người có thể làm ác, nên có trí tuệ để phòng hộ;\nbiết rằng con người có thể làm thiện, nên không từ bỏ lòng từ bi.\nThấy người ác, hãy đề phòng điều ác của họ, nhưng đừng cắt đứt khả năng sửa lỗi của họ;\nthấy người thiện, hãy tôn kính điều thiện của họ, nhưng cũng đừng xem họ là người không bao giờ phạm sai lầm.\nNhìn người như vậy, sẽ bớt đi phần nào thất vọng, cũng bớt đi phần nào thiên chấp.\nĐiều Phật pháp coi trọng không phải là tranh luận xem nhân tánh rốt cuộc nên dán nhãn “thiện” hay “ác”,\nmà là hỏi con:\nniệm này ngay lúc này, sẽ đi về đâu?\nNiệm này nối tiếp niệm kia thì thành tập khí;\ntập khí tích lũy lâu ngày thì hình thành tính cách của một con người;\ncon người nếu biết giác sát, tập khí cũng có thể chuyển đổi.\nCho nên Ta nói:\nthiện ác không phải là điều bất di bất dịch, nhân duyên cũng không phải là định mệnh;\ntâm chúng sinh có thể chuyển đổi, cho nên chúng sinh có thể được độ hóa."]}, "050": {"title": "Thế nào là nhân quả, thế nào là nghiệp lực?", "summary": "Lấy hạt giống, đất và thói quen thường ngày để trình bày những ghi chép của tác giả về nhân quả và nghiệp lực.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\nĐệ tử xin thỉnh hỏi: Thế nào là nhân quả? Thế nào là nghiệp lực?", "“Con hỏi về nhân quả, lại hỏi về nghiệp lực.\nTrước hết nên biết: nhân quả không phải là thưởng phạt; nghiệp lực không phải là thiên mệnh.\nMột niệm khởi, một lời nói ra, một việc làm, đều có thể thành nhân. Nhân gặp duyên của nó, rồi sau mới thành quả. Như hạt giống vào đất, hạt giống là nhân; nước, đất, ánh mặt trời đều là duyên; nhân duyên đầy đủ, mới sinh ra quả. Cho nên có nhân, chưa chắc liền thấy quả; có quả, cũng không phải chỉ do một nhân mà thành. Đó gọi là nhân quả.\nThế nào là nghiệp? Chúng sinh có ý mà tạo tác: thân có điều làm, miệng có điều nói, ý có điều nghĩ; lặp đi lặp lại, liền huân tập vào tâm. Một niệm hôm nay, dường như rất nhỏ; ngày ngày lặp lại, liền thành tập khí. Tập khí lại khiến người càng dễ khởi lên những niệm tương tự, những hành vi tương tự. Thế lực tương tục ấy, có thể gọi là nghiệp lực.\nNghiệp lực không phải là một đôi tay trong bóng tối trừng phạt con; mà là những gì chúng sinh đã làm, để lại sức mạnh, rồi lại ảnh hưởng đến các duyên về sau.\nMột người thường sân, tâm sân càng thuần thục; gặp chuyện nhỏ, cũng dễ nổi giận. Một người thường dối, tập khí dối trá càng sâu; gặp lợi hại, liền dễ dối lần nữa. Một người thường từ, tâm từ càng thuần thục; thấy chúng sinh khổ, liền dễ đưa tay giúp. Cho nên nghiệp do hành mà thành, hành cũng bị nghiệp huân tập.\nTuy nhiên con phải hiểu rõ: chịu ảnh hưởng của nghiệp, không có nghĩa là bị nghiệp khóa chặt. Nếu nghiệp không thể chuyển, thì tu hành vô nghĩa; nếu quả không thể đổi, thì sám hối vô ích. Chính vì nhân duyên chưa định, nên một niệm hôm nay vẫn có thể gieo thêm nhân mới. Nhân đã gieo trong quá khứ, không thể khiến nó như chưa từng xảy ra; nhưng hôm nay có thể thay đổi duyên của nó, cũng có thể gieo nhân mới khác.\nVí như một thửa ruộng đã có hạt cỏ dại, con không thể nói hạt giống chưa từng rơi xuống; nhưng có thể nhổ cỏ, cải đất, tưới nước, rồi trồng mầm lành. Lâu dần, cảnh tượng trong ruộng sẽ khác. Đó chính là tu hành.\nCho nên chớ hễ gặp khổ liền hỏi: ‘Rốt cuộc mình đã tạo ác nghiệp gì?’\nMột việc ở thế gian, thường do nhiều duyên hòa hợp. Bệnh tật có nguyên nhân từ thân thể, tai nạn có nguyên nhân thực tế, người khác gây hại cũng có lựa chọn riêng của người ấy. Không thể hễ gặp khổ nạn, đều quy cho nghiệp báo đời trước. Như thế không phải là hiểu rõ nhân quả, mà ngược lại thành mê lầm về nhân quả.\nNhân quả dạy người biết chịu trách nhiệm, không phải dạy người tự trách; nghiệp lực dạy người thận trọng trong tạo tác, không phải dạy người cam chịu số phận. Điều con có thể nắm giữ hôm nay, chính là khoảnh khắc này. Ác niệm khởi, biết mà không theo; lời ác sắp thốt ra, biết mà dừng được; thiện niệm sinh, khiến nó thành hành động. Một lần tuy nhỏ, lâu ngày thì sâu. Cho nên chớ xem nhẹ một niệm thiện, cũng chớ xem nhẹ một niệm ác.\nNhân quả khiến người biết: việc đã làm không uổng.\nNghiệp lực khiến người biết: điều đã huân tập thành thế lực.\nTu hành khiến người biết: thế lực dù đã thành, vẫn có thể chuyển hướng.\nCon nếu hiểu rõ điều này, thì không cần lấy nhân quả để tự dọa mình, cũng không được dùng nghiệp lực để tìm cớ cho lựa chọn của mình. Nghiệp hôm qua, thành một duyên của hôm nay; tâm hôm nay, lại thành một nhân của ngày mai.\nCho nên Ta nói:\nnhân quả không phải là bản án, nghiệp lực không phải là gông xiềng.\nBiết nhân quả, nên thận trọng điều mình gieo;\nbiết nghiệp lực, nên thận trọng điều mình tập;\nbiết duyên khởi, nên biết có thể chuyển;\nbiết có thể chuyển, nên không tuyệt vọng.”", "Con hỏi về nhân quả, lại hỏi về nghiệp lực.\nTrước hết phải biết: nhân quả không phải là thưởng phạt, nghiệp lực cũng không phải là thiên mệnh.\nMột niệm khởi lên, một câu nói ra, một việc làm ra, đều có thể trở thành “nhân”. Nhân gặp được “duyên” của nó, rồi mới kết thành “quả”.\nGiống như hạt giống được vùi vào đất, hạt giống là nhân; đất, nước, ánh nắng đều là duyên; nhân duyên đầy đủ rồi mới sinh ra quả.\nCho nên có nhân, không nhất định sẽ thấy quả ngay; có quả, cũng không phải chỉ do một nhân duy nhất tạo thành. Đó chính là nhân quả.\nThế nào là nghiệp?\nChúng sinh có ý thức mà tạo tác, thân thể có hành động, miệng có lời nói, ý có suy nghĩ, lặp đi lặp lại làm như vậy, sẽ huân nhiễm tâm của chính mình.\nMột niệm hôm nay, nhìn qua thì rất nhỏ bé; nhưng mỗi ngày lặp lại, sẽ trở thành tập khí. Tập khí lại khiến con người dễ khởi lên những ý niệm tương tự, những hành vi tương tự. Sức mạnh nối tiếp không dứt này, gọi là nghiệp lực.\nNghiệp lực không phải là một đôi tay ngấm ngầm trừng phạt con; mà là chính những việc chúng sinh đã làm, để lại sức mạnh, rồi lại ảnh hưởng đến các nhân duyên về sau.\nMột người thường hay nổi giận, tâm sân sẽ ngày càng thuần thục; gặp chuyện nhỏ cũng rất dễ phát cáu. Một người thường hay lừa dối, tập khí lừa dối sẽ ngày càng sâu; gặp lúc lợi hại, sẽ dễ lừa dối lần nữa. Một người thường hay từ bi, lòng từ bi sẽ ngày càng thuần thục; thấy chúng sinh chịu khổ, sẽ dễ đưa tay giúp đỡ.\nCho nên nghiệp do hành vi tạo thành, hành vi lại bị nghiệp huân nhiễm trở lại.\nTuy nhiên con phải hiểu rõ: chịu ảnh hưởng của nghiệp, không có nghĩa là bị nghiệp khóa chặt.\nNếu nghiệp hoàn toàn không thể chuyển, thì tu hành chẳng có ý nghĩa; nếu quả hoàn toàn không thể đổi, thì sám hối chẳng có tác dụng.\nChính vì nhân duyên chưa cố định, nên một niệm hôm nay vẫn có thể thêm vào một nhân mới.\nNhân đã gieo trong quá khứ, không thể khiến nó như chưa từng xảy ra; nhưng hôm nay có thể thay đổi duyên của nó, cũng có thể gieo thêm nhân mới.\nVí như một thửa ruộng đã có sẵn hạt cỏ dại, con không thể nói hạt giống chưa từng rơi xuống; nhưng con có thể nhổ cỏ, cải tạo đất, tưới nước, rồi trồng xuống mầm lành. Lâu dần, cảnh tượng trong ruộng sẽ khác đi. Đó chính là tu hành.\nCho nên đừng hễ gặp khổ nạn là hỏi: “Rốt cuộc mình đã tạo ác nghiệp gì?” Một việc ở thế gian thường do nhiều nhân duyên hòa hợp mà thành. Bệnh tật có nguyên nhân từ thân thể, tai nạn có nguyên nhân thực tế, người khác làm hại con cũng là do lựa chọn của chính họ. Không thể hễ gặp khổ nạn là đổ hết cho nghiệp báo đời trước. Như vậy không phải là hiểu rõ nhân quả, mà ngược lại là mê lầm về nhân quả.\nNhân quả dạy con người biết chịu trách nhiệm, không phải dạy con người tự trách; nghiệp lực dạy con người cẩn trọng trong tạo tác, không phải dạy con người cam chịu số phận.\nĐiều con có thể nắm giữ hôm nay, chính là khoảnh khắc này. Ác niệm khởi lên, biết nó nhưng không chạy theo; lời ác sắp thốt ra, biết nó mà dừng lại được; thiện niệm khởi lên, hãy để nó trở thành hành động. Một lần tuy rất nhỏ, nhưng lâu ngày sẽ rất sâu.\nCho nên đừng xem nhẹ một thiện niệm, cũng đừng xem nhẹ một ác niệm.\nNhân quả khiến con người biết: những việc mình làm sẽ không uổng phí. Nghiệp lực khiến con người biết: những gì mình huân tập sẽ hình thành thế lực. Tu hành khiến con người biết: thế lực dù đã hình thành, vẫn có thể chuyển hướng.\nNếu con hiểu được đạo lý này, thì không cần dùng nhân quả để tự dọa mình, cũng không được dùng nghiệp lực để tìm cớ cho lựa chọn của mình.\nNghiệp của hôm qua trở thành một duyên của hôm nay; tâm của hôm nay lại trở thành một nhân của ngày mai.\nCho nên Ta nói:\nnhân quả không phải là bản án, nghiệp lực không phải là gông xiềng. Biết nhân quả, nên cẩn trọng điều mình gieo; biết nghiệp lực, nên cẩn trọng điều mình huân tập; biết duyên khởi, nên biết có thể chuyển; biết có thể chuyển, nên sẽ không tuyệt vọng."]}, "051": {"title": "Từ bi có thể không gần gũi, hiếu thuận có thể có ranh giới", "summary": "Khi quan hệ gia đình mang đến tổn thương, tìm hiểu về hiếu thuận, khoảng cách và sự tự bảo vệ.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\n“Thường nghe nói có những người con bất hòa với cha mẹ, nhiều năm bị cha mẹ chế giễu, mắng chửi, khống chế bằng lời nói, hoặc vì thế mà về sau trở nên bất hiếu.\nXin hỏi theo góc nhìn Phật pháp, đây có phải là nhân quả nghiệp lực đời trước của riêng cha mẹ và con cái (đòi nợ, trả nợ) không?\nKhi đối diện với cha mẹ ruột thịt cùng huyết mạch, nếu lời nói và hành động của họ đã gây tổn thương nghiêm trọng cho con cái, mà con cái vì tự bảo vệ nên chọn ‘giữ khoảng cách, người nên tránh xa thì tránh xa’, thì dưới gánh nặng đạo đức và cảm giác tội lỗi của đạo hiếu truyền thống, nên an định nội tâm thế nào để vừa có trí tuệ phòng hộ, vừa không mất lòng từ bi của người làm con?”", "Cha mẹ con cái, nhân duyên rất sâu.\nNhưng duyên sâu, không có nghĩa đều là thiện duyên;\nhuyết mạch tương liên, cũng không có nghĩa là mãi mãi không làm tổn thương nhau.\nNgười đời thường nói:\n“Con đến đòi nợ, cha mẹ đến trả nợ; đời trước nợ nhau, đời này đền nhau.”\nLời này có thể dùng làm ví dụ, không thể chấp làm định luận.\nCon không biết đời trước, thì chớ lấy khổ đau đời này mà vọng đoán tội lỗi đời trước.\nCha mẹ làm hại con, không thể liền nói:\n“Đây là con cái đời trước mắc nợ, nên phải gánh chịu.”\nCon cái oán cha mẹ, cũng không thể liền nói:\n“Đây là cha mẹ đời trước tạo nghiệp, đời này đáng phải chịu.”\nNói nhân quả như thế, dễ mượn danh nhân quả để hợp lý hóa tổn thương hôm nay.\nNhân chưa biết, chớ vội kết luận;\nđiều ác trước mắt, phải dừng ngay trước mắt.\nCha mẹ nếu dùng giận mắng, sỉ nhục, khống chế, làm tổn thương con cái lâu dài,\nviệc làm ấy nếu bất thiện, thì chính là bất thiện.\nKhông thể vì họ là cha mẹ, mà đổi tên tổn thương thành từ ái.\nCũng không thể vì con cái chịu khổ, mà đòi hỏi họ:\n“Đây là nghiệp của con, con phải nhẫn chịu.”\nNhẫn nhục, không phải để mặc người khác làm hại mình;\nhiếu thuận, không phải đánh mất ranh giới;\ntừ bi, không phải dung túng việc ác.\nNếu gần nhau, thì sân hận đôi bên càng sâu;\nnếu mỗi lần gặp mặt, đều khiến lời ác lại khởi;\nnếu ở chung lâu ngày, đã khiến thân tâm khó yên,\nthì tạm rời cảnh ấy, chưa chắc là bất hiếu.\nTránh xa ác duyên, không phải là dứt bỏ lòng từ.\nCó thể ít gặp, mà không nguyền rủa;\ncó thể từ chối, mà không sỉ nhục;\ncó thể đặt ranh giới, mà không báo thù;\ncó thể không còn chịu sự khống chế, mà vẫn mong họ bình an.\nĐó là: thân có thể có khoảng cách, tâm không cần có hận.\nNếu cha mẹ có điều cần, trong sức con có thể lo,\nlại không khiến mình rơi vào tổn thương lần nữa, thì có thể chăm lo vừa phải.\nNếu tự mình tiếp xúc ắt sinh khổ lớn, cũng có thể tìm cách khác,\nkhông cần việc gì cũng tự thân gánh chịu.\nHiếu có trí tuệ, mới có thể lâu dài.\nHiếu chân chính, không phải cha mẹ nói gì, con cái đều theo.\nCha mẹ nếu làm điều bất thiện, con cái dịu lời khuyên can, cũng là hiếu;\nkhuyên mà không nghe, thì giữ lấy chánh trực của mình,\nkhông thể vì thuận theo cha mẹ, mà ngược lại khiến mình cùng tạo bất thiện.\nNếu trong lòng con sinh cảm giác tội lỗi:\n“Dù sao họ cũng là cha mẹ mình, sao mình có thể tránh xa?”\nHãy tự hỏi:\n“Mình đang ruồng bỏ cha mẹ, hay đang dừng lại việc hai bên tiếp tục làm tổn thương nhau?”\nHai điều ấy khác nhau.\nCó những khoảng cách, không phải là tuyệt tình;\ntrái lại là để đôi bên không còn ngày ngày tạo khẩu nghiệp, khởi tâm sân, kết oán mới.\nNếu rời xa một phần, mà đôi bên bớt tạo một phần ác,\nthì khoảng cách ấy cũng có thể là một phương tiện thiện xảo.\nNhưng con cũng nên tự xét:\nchớ vì từng bị tổn thương, mà lấy báo thù làm ranh giới;\nchớ vì cha mẹ có lỗi, mà phán cả đời họ đều là ác.\nChỗ sai thì thấy là sai, chỗ ân cũng biết là ân.\nCó ân, không có nghĩa là tổn thương không tồn tại;\ncó tổn thương, cũng không cần xóa đi mọi ân tình từng có.\nCó thể cùng lúc thấy cả hai, tâm sẽ dần rời xa hai cực yêu và ghét.\nCòn về cái gọi là nhân quả đời trước, nếu con tin, có thể hiểu như vầy:\nhôm nay đã gặp nhau, thì có nhân duyên của hôm nay.\nCòn đời trước ai nợ ai bao nhiêu, chớ nhọc lòng tính toán.\nĐiều thật sự quan trọng là: đời này, đừng tiếp tục nợ nhau nữa.\nCha mẹ dùng lời ác làm tổn thương con, nên dừng;\ncon cái dùng lời ác để trả đũa, cũng nên dừng.\nMột bên không thể đổi, bên kia vẫn có thể quyết định,\nkhông để ác nghiệp tiếp tục từ chính mình.\nĐó mới là chỗ chuyển nghiệp.\nCho nên Ta khuyên những người con bị tổn thương:\nkhông cần lấy thù hận để chứng minh nỗi đau của mình;\ncũng không cần lấy sự hy sinh bản thân để chứng minh lòng hiếu của mình.\nĐiều cần chữa lành, thì nên chữa lành;\nđiều cần cầu giúp, thì nên cầu giúp;\nnơi cần đặt ranh giới, thì nên đặt ranh giới;\nnơi cần tránh xa, có thể tránh xa.\nNhưng nếu một ngày tâm lực đã đủ, nguyện từ từ buông xuống oán hận,\nkhông phải vì những gì cha mẹ làm đều đúng,\nmà vì không muốn để vết thương quá khứ tiếp tục chi phối phần đời còn lại.\nSự tha thứ nếu có, cũng phải từ tâm mà sinh, không thể cưỡng cầu.\nChưa thể tha thứ, trước hết đừng báo thù;\nchưa thể gần gũi, trước hết giữ khoảng cách;\nchưa thể buông xả, trước hết bảo vệ tốt bản thân.\nTừng bước từng bước, cũng là tu hành.\nCho nên con hỏi: làm sao vừa có trí tuệ phòng hộ, vừa không mất lòng từ bi của người làm con?\nTa nói:\ntừ bi có thể không gần gũi, hiếu thuận có thể có ranh giới.\nKhông dung túng điều ác của họ, là trí tuệ;\nkhông mong họ chịu khổ, là từ bi;\nkhông lấy ác báo ác, là tu hành;\nkhông để mình bị tổn thương thêm, cũng là bảo hộ sự sống.\nChớ lấy chữ “hiếu” ép người gánh chịu tổn thương;\nchớ lấy chữ “nhân quả” tìm lý do cho tổn thương.\nNếu hỏi đời trước, đời trước khó biết;\nnếu hỏi hôm nay, hôm nay có thể dừng việc làm tổn thương nhau.\nNhân quả không phải bảo con nhẫn chịu điều ác,\nmà là nhắc con: chớ để điều ác lại từ chính mình tiếp nối.", "Nhân duyên giữa cha mẹ và con cái rất sâu. Nhưng duyên phận sâu, không có nghĩa nhất định là thiện duyên; huyết mạch tương liên, cũng không có nghĩa là hai bên vĩnh viễn không làm tổn thương nhau.\nNgười đời thường nói: “Con cái đến để đòi nợ, cha mẹ đến để trả nợ; đời trước nợ nhau, đời này đền nhau.” Câu nói này có thể xem như một phép ví von, nhưng không được chấp chặt làm định luận. Con không biết đời trước đã xảy ra chuyện gì, thì đừng dùng nỗi khổ của đời này để vọng đoán tội lỗi của đời trước.\nCha mẹ làm tổn thương con cái, không thể cứ thế mà nói: “Đây là do con cái đời trước mắc nợ, nên phải gánh chịu.” Con cái oán hận cha mẹ, cũng không thể cứ thế mà nói: “Đây là do cha mẹ đời trước tạo nghiệp, đời này đáng phải chịu.” Nói nhân quả như vậy rất dễ mượn danh nghĩa nhân quả để hợp lý hóa tổn thương của hôm nay.\nNhân chưa biết thì đừng vội kết luận; điều ác trước mắt thì nên dừng lại ngay trước mắt.\nNếu cha mẹ dùng lời giận mắng, sỉ nhục, khống chế để làm tổn thương con cái lâu dài, thì hành vi ấy nếu là bất thiện, chính là bất thiện. Không thể vì họ là cha mẹ mà đổi tên tổn thương thành từ ái. Cũng không thể vì con cái đang chịu khổ mà đòi hỏi họ: “Đây là nghiệp của con, con phải nhẫn chịu.”\nNhẫn nhục không phải là mặc cho người khác làm hại; hiếu thuận không phải là đánh mất ranh giới; từ bi không phải là dung túng việc ác.\nNếu đến gần chỉ khiến sân hận đôi bên càng sâu; nếu mỗi lần gặp mặt đều khiến lời ác lại nổi lên; nếu ở chung lâu ngày đã khiến thân tâm khó được yên ổn, thì tạm thời rời khỏi môi trường ấy chưa chắc đã là bất hiếu. Tránh xa ác duyên không phải là cắt đứt lòng từ.\nCó thể ít gặp, nhưng không nguyền rủa; có thể từ chối, nhưng không sỉ nhục; có thể đặt ranh giới, nhưng không báo thù; có thể không còn chịu sự khống chế, nhưng vẫn chúc họ bình an. Đó chính là: thân có thể có khoảng cách, tâm không cần có hận.\nNếu cha mẹ có điều cần đến, trong phạm vi khả năng của con và với điều kiện không khiến bản thân lại rơi vào tổn thương, con có thể chăm lo ở mức vừa phải. Nếu tự mình tiếp xúc chắc chắn sẽ sinh ra khổ đau rất lớn, cũng có thể tìm cách khác, không cần việc gì cũng tự thân gánh chịu. Hiếu thuận phải có trí tuệ thì mới lâu dài được.\nHiếu chân chính không phải là cha mẹ nói gì con cái cũng đều nghe theo. Nếu cha mẹ hành xử bất thiện, con cái dùng cách ôn hòa để khuyên can, cũng là một cách hiếu; khuyên rồi mà không nghe, thì hãy giữ vững sự chánh trực của mình, không được vì thuận theo cha mẹ mà ngược lại khiến bản thân cũng đi tạo điều bất thiện.\nNếu trong lòng con khởi lên cảm giác tội lỗi: “Dù sao họ cũng là cha mẹ mình, sao mình có thể tránh xa được?” thì con nên tự hỏi: “Mình đang ruồng bỏ cha mẹ, hay đang chấm dứt việc hai bên tiếp tục làm tổn thương nhau?” Hai điều này không giống nhau.\nCó những khoảng cách không phải là tuyệt tình; trái lại là giúp đôi bên không còn ngày ngày tạo khẩu nghiệp, khởi tâm sân, kết thêm oán mới. Nếu rời xa một phần mà có thể giúp đôi bên bớt tạo một phần ác, thì khoảng cách ấy cũng có thể là một phương tiện thiện xảo.\nTuy nhiên con cũng nên tự phản tỉnh: đừng vì từng bị tổn thương mà xem báo thù là ranh giới; đừng vì cha mẹ có lỗi lầm mà phán định cả cuộc đời họ đều là ác. Chỗ sai thì phải thấy là sai, chỗ có ân cũng phải biết là ân. Có ân, không có nghĩa là tổn thương không tồn tại; có tổn thương, cũng không cần xóa đi mọi ân tình từng có. Có thể cùng lúc nhìn thấy cả hai điều này, tâm sẽ dần dần rời khỏi hai cực yêu và ghét.\nCòn về cái gọi là nhân quả đời trước, nếu con tin, có thể hiểu như thế này: hôm nay đã gặp nhau, thì có nhân duyên của hôm nay. Còn đời trước ai nợ ai bao nhiêu, đừng nhọc lòng tính toán. Điều thật sự quan trọng là: đời này, đừng tiếp tục nợ nhau nữa.\nCha mẹ dùng lời ác làm tổn thương con cái, nên dừng lại; con cái dùng lời ác để trả đũa, cũng nên dừng lại. Một bên không thể thay đổi, bên kia vẫn có thể quyết định không để ác nghiệp tiếp tục từ chính mình. Đó mới là chỗ chuyển nghiệp.\nCho nên Ta khuyên những người con bị tổn thương: không cần dùng thù hận để chứng minh nỗi đau của mình; cũng không cần hy sinh bản thân để chứng minh lòng hiếu của mình. Điều cần chữa lành thì hãy đi chữa lành; điều cần cầu giúp thì hãy đi cầu giúp; nơi cần đặt ranh giới thì hãy đặt ranh giới; nơi cần tránh xa thì có thể tránh xa.\nNhưng nếu một ngày nào đó, tâm lực đã đủ, nguyện từ từ buông xuống oán hận, thì không phải vì những gì cha mẹ đã làm đều đúng, mà vì không muốn để vết thương quá khứ tiếp tục chi phối phần đời còn lại.\nSự tha thứ nếu có, cũng phải từ tâm mà sinh ra, không thể cưỡng cầu. Chưa thể tha thứ, thì trước hết đừng báo thù; chưa thể gần gũi, thì trước hết giữ khoảng cách; chưa thể buông xả, thì trước hết hãy bảo vệ tốt bản thân. Từng bước từng bước, cũng là tu hành.\nCho nên con hỏi: làm sao vừa có trí tuệ phòng hộ, vừa không mất lòng từ bi của người làm con? Ta nói:\ntừ bi có thể không gần gũi, hiếu thuận có thể có ranh giới. Không dung túng điều ác của họ, là trí tuệ; không mong họ chịu khổ, là từ bi; không lấy ác báo ác, là tu hành; không để mình bị tổn thương thêm, cũng là bảo hộ sự sống.\nĐừng dùng chữ “hiếu” để ép người gánh chịu tổn thương; đừng dùng chữ “nhân quả” để tìm lý do cho tổn thương. Nếu hỏi đời trước, đời trước khó biết; nếu hỏi hôm nay, thì ngay hôm nay có thể dừng việc làm tổn thương nhau.\nNhân quả không phải bảo con nhẫn chịu điều ác, mà là nhắc nhở con: đừng để điều ác lại từ chính mình tiếp nối."]}, "052": {"title": "Sống trong hiện tại, phải chăng chỉ là một lời an ủi?", "summary": "Quá khứ có thể học hỏi, tương lai có thể chuẩn bị; hãy đưa bước mình có thể làm trở về khoảnh khắc này.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\nSống trong hiện tại có phải chỉ là một câu nói để an ủi người khác?", "“Con hỏi:\n‘Sống trong hiện tại,\nphải chăng chỉ là lời an ủi người?’\nTa nói:\nnếu chỉ treo nơi miệng,\nquả thật chỉ là một câu nói;\nnếu thực hành được trong tâm,\nấy là một môn công phu.\nKhổ của chúng sinh,\ncó cái khổ ở ngày hôm nay;\nlại có nhiều nỗi khổ\nđến từ hôm qua đã qua,\nvà ngày mai chưa tới.\nHôm qua chịu nhục,\nhôm nay vẫn tiếp tục chịu nhục;\nngày mai chưa đến,\nhôm nay đã sợ ngày mai trước.\nSự việc chỉ xảy ra một lần,\nmà tâm lại khiến nó\nxảy ra trăm lần.\nCho nên cái gọi là hiện tại,\nkhông phải bảo con\nquên đi quá khứ,\ncũng không phải bảo con\nđừng nghĩ đến tương lai.\nMà là:\nquá khứ dùng để hiểu rõ,\nkhông phải để cư ngụ;\ntương lai dùng để chuẩn bị,\nkhông phải để chịu khổ trước.\nCó người nói:\n‘Đã sống trong hiện tại,\ncần gì lo kế hoạch cho ngày mai?’\nĐó không phải hiện tại.\nHôm nay để dành tiền,\nlà việc làm của hôm nay;\nhôm nay đọc sách,\nlà việc làm của hôm nay;\nhôm nay chữa bệnh,\nlà việc làm của hôm nay;\nhôm nay chuẩn bị cho ngày mai,\nvẫn là hành sự trong hiện tại.\nĐiều thật sự khiến người rời khỏi hiện tại,\nkhông phải là hoạch định tương lai,\nmà là tâm đã chạy vào\nnhững việc chưa xảy ra,\nsợ hãi mãi không thôi.\nLại có người nói:\n‘Đã sống trong hiện tại,\nthì đừng nghĩ đến quá khứ.’\nCũng chẳng phải vậy.\nQuá khứ nếu có lỗi lầm,\nnên tự xét lại;\nquá khứ nếu có thương tổn,\nnên chữa lành;\nquá khứ nếu có ân tình,\nnên ghi nhớ biết ơn.\nNhưng chớ để hôm qua\nngày ngày tái diễn,\ncho đến khi hôm nay\ncũng thành tù nhân của hôm qua.\nGhi nhớ,\nvà bị giam hãm,\nkhông phải là một.\nNếu con từng bị người làm tổn thương,\nsống trong hiện tại\nkhông phải là tự nhủ:\n‘Không sao,\nmọi chuyện qua rồi.’\nMà là biết rằng:\n‘Việc ấy quả thật đã xảy ra,\nmình cũng quả thật đã bị tổn thương.\nNhưng mình của hôm nay,\ncó thể quyết định\nbước tiếp theo đi thế nào.’\nNhư vậy,\nkhông phải trốn tránh,\nmà là lấy lại khoảnh khắc này.\nNếu con lo âu về tương lai,\ncũng không phải tự nhủ:\n‘Đừng nghĩ gì cả,\nthuyền đến đầu cầu ắt tự thẳng.’\nMà là hỏi:\n‘Ngay lúc này có việc gì\nmà mình làm được?’\nViệc làm được,\nthì làm;\nviệc không làm được,\ntạm gác lại.\nTrí tuệ không phải\nlà không có lo âu;\nmà là biết\nđiều gì bây giờ xử lý được,\nđiều gì bây giờ chỉ có thể chờ.\nChúng sinh thường nghĩ:\nđợi khi có tiền,\nsẽ được an tâm;\nđợi khi lập gia đình,\nsẽ được an tâm;\nđợi việc này ổn định,\nsẽ được an tâm;\nđợi mọi vấn đề giải quyết xong,\ntôi mới sống cho tử tế.\nThế nhưng một việc vừa xong,\nviệc khác lại sinh.\nNếu nhất định phải đợi\nđời không còn vấn đề,\nmới cho phép mình an trú,\nthì trọn cả một đời,\nngày nào mới được sống?\nCho nên tu hiện tại,\nkhông phải vì\ntương lai không quan trọng;\nchính vì đời người vô thường,\nnên hôm nay mới quan trọng.\nKhi con ăn cơm,\nbiết mình đang ăn cơm;\nkhi sum họp cùng người,\nbiết lúc này đang sum họp;\nkhi tâm buồn đau,\nbiết mình đang buồn đau;\nkhi tâm hoan hỷ,\nbiết mình đang hoan hỷ.\nKhông cần mỗi khoảnh khắc\nđều vui vẻ,\nchỉ cần mỗi khoảnh khắc\nkhông dối gạt tâm mình.\nHiện tại không phải là vui sướng,\nhiện tại là chân thật.\nHôm nay có khổ,\nthì xử lý cái khổ của hôm nay;\nhôm nay có vui,\ncũng biết niềm vui này vô thường.\nKhông đuổi theo,\nkhông chối bỏ,\nbiết nó đến,\ncũng biết nó đi —\nấy chính là tu tâm.\nCho nên ta nói:\nsống trong hiện tại,\nkhông phải an ủi con rằng\n‘mọi thứ rồi sẽ tốt đẹp’;\nmà là nhắc nhở con:\ndù tương lai tốt hay xấu,\nchỗ con thật sự có thể bắt tay vào,\nmãi mãi chỉ là hiện tại.\nHôm qua không thể sửa,\nngày mai chưa đến;\nnhưng một niệm lúc này,\nmột lời lúc này,\nmột việc làm lúc này,\nđang trở thành\nnhân của khoảnh khắc kế tiếp.\nCho nên lý nhân quả,\ncũng không rời hiện tại.\nNếu con hỏi:\n‘Đời người nhiều khổ như thế,\nlàm sao sống trong hiện tại?’\nKhông cần đòi hỏi mình\nlúc nào cũng an trú.\nTâm chạy đi,\nbiết nó đã chạy đi,\nrồi quay về.\nLại chạy đi,\nlại biết,\nlại quay về.\nKhông phải là chẳng bao giờ tán loạn,\nmà là mỗi lần tán loạn,\nvẫn biết quay về.\nChỉ vậy mà thôi.\nChớ xem nhẹ việc này.\nMột đời người,\ntrông như mấy chục năm;\ncái thật sự đã sống,\nxưa nay chỉ là\nhết hiện tại này đến hiện tại khác.\nCho nên:\nquá khứ có thể học,\nkhông thể ở lại;\ntương lai có thể chuẩn bị,\nkhông thể chấp chặt;\nhiện tại có thể hành động,\nkhông thể đánh mất.\nĐây không phải lời an ủi.\nĐây là nơi duy nhất\nchúng sinh thật sự có thể\nkhởi tâm, lựa chọn,\nvà thay đổi.”", "Con hỏi:\n“Sống trong hiện tại, có phải chỉ là một câu nói để an ủi người khác?”\nTa nói:\nnếu chỉ treo trên miệng, thì nó quả thật chỉ là một câu nói;\nnhưng nếu có thể thực hành trong tâm, nó chính là một môn công phu.\nNỗi khổ của chúng sinh, có những cái đang xảy ra ngay lúc này;\nnhưng cũng có rất nhiều nỗi khổ đến từ hôm qua đã qua đi,\nvà từ ngày mai chưa tới.\nHôm qua bị sỉ nhục, hôm nay vẫn còn chịu đựng mãi sự sỉ nhục ấy;\nngày mai chưa đến, hôm nay đã sợ ngày mai rồi.\nSự việc chỉ xảy ra một lần, nhưng tâm lại khiến nó xảy ra một trăm lần.\nCho nên cái gọi là hiện tại, không phải bảo con quên quá khứ, cũng không phải bảo con đừng nghĩ đến tương lai.\nMà là:\nquá khứ dùng để hiểu rõ, không phải để cư ngụ;\ntương lai dùng để chuẩn bị, không phải để chịu khổ trước.\nCó người nói:\n“Đã sống trong hiện tại, cần gì lập kế hoạch cho ngày mai?”\nĐó không phải là hiện tại.\nHôm nay để dành tiền là hành động của hôm nay;\nhôm nay đọc sách là hành động của hôm nay;\nhôm nay chữa bệnh là hành động của hôm nay;\nhôm nay chuẩn bị cho ngày mai vẫn là hành động trong hiện tại.\nĐiều thật sự khiến người ta rời khỏi hiện tại không phải là lập kế hoạch cho tương lai,\nmà là tâm đã chạy vào những chuyện chưa xảy ra, rồi sợ hãi hết lần này đến lần khác.\nLại có người nói:\n“Đã sống trong hiện tại, thì đừng nghĩ đến quá khứ nữa.”\nCũng không phải như vậy.\nQuá khứ nếu có lỗi lầm, nên tự xét lại;\nquá khứ nếu có thương tổn, nên chữa lành;\nquá khứ nếu có ân tình, nên ghi nhớ biết ơn.\nNhưng đừng để hôm qua mỗi ngày lại tái diễn,\ncho đến khi hôm nay cũng biến thành tù nhân của hôm qua.\nGhi nhớ và bị giam hãm là hai chuyện khác nhau.\nNếu con từng bị người khác làm tổn thương,\nsống trong hiện tại không phải là tự nhủ:\n“Không sao, mọi chuyện qua rồi.”\nMà là biết rằng:\n“Chuyện đó thật sự đã xảy ra, mình cũng thật sự đã bị tổn thương.\nNhưng mình của hôm nay có thể quyết định bước tiếp theo sẽ đi thế nào.”\nNhư vậy không phải là trốn tránh, mà là lấy lại khoảnh khắc này.\nNếu con lo âu về tương lai,\ncũng không phải là tự nhủ:\n“Đừng nghĩ gì cả, rồi mọi chuyện sẽ đâu vào đấy.”\nMà là hỏi:\n“Ngay lúc này có việc gì mà mình làm được?”\nViệc làm được thì đi làm;\nviệc không làm được thì tạm gác lại.\nTrí tuệ không phải là không có lo âu;\nmà là biết điều gì bây giờ xử lý được, điều gì bây giờ chỉ có thể chờ đợi.\nChúng sinh thường nghĩ rằng:\nđợi khi tôi có tiền, tôi sẽ an tâm;\nđợi khi tôi lập gia đình, tôi sẽ an tâm;\nđợi khi chuyện này ổn định, tôi sẽ an tâm;\nđợi khi mọi vấn đề được giải quyết, tôi mới sống cho thật tốt.\nThế nhưng một chuyện vừa kết thúc, chuyện khác lại đến.\nNếu nhất định phải đợi đến khi đời không còn vấn đề mới cho phép mình an trú,\nthì suốt cả một đời, đến ngày nào mới thật sự được sống?\nCho nên tu hiện tại không phải vì tương lai không quan trọng;\nmà chính vì đời người vô thường, nên hôm nay mới quan trọng.\nKhi con ăn cơm, biết mình đang ăn cơm;\nkhi sum họp cùng người khác, biết lúc này đang sum họp;\nkhi trong lòng buồn đau, biết mình đang buồn đau;\nkhi trong lòng hoan hỷ, biết mình đang hoan hỷ.\nKhông cần mỗi khoảnh khắc đều phải vui vẻ;\nchỉ cần mỗi khoảnh khắc không dối gạt tâm mình.\nHiện tại không phải là vui sướng, hiện tại là chân thật.\nHôm nay có khổ, thì xử lý cái khổ của hôm nay;\nhôm nay có vui, cũng biết niềm vui này là vô thường.\nKhông đuổi theo, không chống cự; biết nó đến, cũng biết nó đi.\nĐó chính là tu tâm.\nCho nên ta nói:\nsống trong hiện tại không phải là an ủi con rằng “mọi thứ rồi sẽ tốt đẹp”;\nmà là nhắc nhở con:\ndù tương lai tốt hay xấu, chỗ con thật sự có thể bắt tay vào, mãi mãi chỉ là hiện tại.\nHôm qua không thể sửa, ngày mai chưa đến;\nnhưng một ý niệm lúc này, một lời nói lúc này, một hành động lúc này\nđang trở thành nhân của khoảnh khắc kế tiếp.\nCho nên đạo lý nhân quả cũng không tách rời hiện tại.\nNếu con hỏi:\n“Đời người nhiều khổ như thế, làm sao sống trong hiện tại?”\nCon không cần đòi hỏi mình lúc nào cũng an trú.\nTâm chạy mất rồi, biết là nó đã chạy mất; rồi kéo nó về.\nLại chạy mất, lại biết; lại kéo về.\nKhông phải là mãi mãi không tán loạn, mà là mỗi lần tán loạn, vẫn còn biết quay về.\nChỉ vậy mà thôi.\nĐừng xem nhẹ việc này.\nMột đời người trông như có mấy chục năm;\nnhưng cái thật sự đã sống, xưa nay chỉ là hết hiện tại này đến hiện tại khác.\nCho nên:\nquá khứ có thể học hỏi, nhưng không được dừng lại ở đó;\ntương lai có thể chuẩn bị, nhưng không được chấp trước;\nhiện tại có thể hành động, nhưng không được bỏ lỡ.\nĐây không phải là lời an ủi.\nĐây là nơi duy nhất chúng sinh thật sự có thể khởi tâm, lựa chọn và thay đổi."]}, "053": {"title": "Tụng kinh chưa xong là uổng công? Một lời của Bồ Tát giúp vô số người buông bỏ tự trách", "summary": "Khi việc tụng kinh phải tạm dừng vì có việc, làm sao an định nỗi tự trách và tiếp tục giữ lòng cung kính cùng thiện tâm.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\n“Khi đang tụng kinh, tụng được nửa chừng mà bỗng có việc — có điện thoại, có người đến tìm — nên không thể không đặt kinh xuống, thì kinh đã tụng có phải là uổng công không? Xin Bồ Tát từ bi khai thị.”", "Con hỏi: tụng kinh chưa xong,\nbỗng có việc đến,\nkhông thể không dừng lại,\nnhững gì đã tụng trước đó,\ncó phải đều thành uổng phí?\nTa nói:\nkinh tụng chưa trọn,\nkhông có nghĩa công đức mất hết;\nmột lúc gián đoạn,\nkhông có nghĩa công phu trước đổ bỏ.\nCông đức tụng kinh,\nkhông chỉ nằm ở chỗ\nmột quyển từ đầu đến cuối.\nMà còn ở nơi\ntâm cung kính,\nlợi ích của việc nghe pháp,\nvà hạnh nhiếp niệm.\nCon tụng một câu,\nnếu sinh được một phần cung kính;\nđọc một bài kệ,\nnếu hiểu được một phần pháp nghĩa —\ndù chưa tụng xong,\nthiện tâm thiện hạnh ấy,\nsao có thể nói là hoàn toàn không?\nPhật pháp coi trọng phát tâm,\ncũng coi trọng thực hành.\nNếu khi đang tụng kinh,\nbỗng có điện thoại,\ncó người đến thăm,\nhoặc có việc gấp phải làm,\ntrước hết hãy phân biệt nặng nhẹ.\nNếu việc không gấp,\ncó thể đợi tụng xong rồi đáp ứng;\nnếu việc khẩn yếu,\nthì có thể tạm dừng để xử lý.\nChớ vì chấp trước\nmột quyển nhất định phải tụng xong,\nmà đánh mất lòng từ bi đáng có.\nNếu cha mẹ có việc cần gấp,\ncon cái gặp nguy nan,\nhoặc có người đang chờ giúp đỡ,\nmà con lại nói:\n‘Kinh còn chưa tụng xong,\nkhông thể gián đoạn,’\nlúc ấy nên hỏi:\ncon đang tu từ bi,\nhay đang chấp trước hình thức?\nTụng kinh là để tu tâm,\nkhông phải để trói buộc tâm.\nKinh dạy chúng sinh từ bi;\nnếu vì tụng kinh\nmà lại không đoái hoài nỗi khổ trước mắt,\nthì nên quán chiếu lại\ný nghĩa của tu hành.\nNhưng cũng không thể vì thế\nmà sinh lười biếng.\nChớ cho rằng việc gì cũng có thể gián đoạn,\nrồi để việc tụng kinh\nthường theo tán loạn mà dừng.\nKhi chuyên chú được,\nhãy chuyên chú;\nkhi cần lo việc,\nhãy lo việc.\nCó việc mà dừng,\nkhông mất cung kính;\nviệc xong tụng tiếp,\ncũng là tinh tấn.\nNếu giữa chừng con phải rời đi,\ncó thể đặt quyển kinh\nnơi thanh tịnh, thích hợp,\ntrong tâm biết rõ\nchỗ mình tạm dừng.\nĐợi việc xong,\nnếu thời gian cho phép,\nthì tụng tiếp từ chỗ gián đoạn.\nNếu muốn tụng lại từ đầu,\ncũng không có gì là không được.\nNếu hôm nay thật không còn thời gian,\nngày mai tụng tiếp,\nkhông cần vì thế mà tự trách.\nCòn về hồi hướng,\ncó thể sau khi tụng xong một đoạn,\ntheo thói quen tu trì của mình mà hồi hướng;\nnếu vì có việc mà chưa tụng xong,\ncũng có thể phát tâm hồi hướng\nphần thiện đã tu.\nTâm hồi hướng,\nkhông cần đợi một quyển viên mãn\nmới có thể khởi lên.\nNếu con hỏi:\n‘Chưa tụng xong,\nBồ Tát có trách không?’\nTa khuyên con:\nchớ xem tụng kinh\nnhư nộp đủ số lượng\ncho chư Phật, Bồ Tát.\nCũng chớ cho rằng\ntụng thiếu một câu,\nlà thành ra mắc nợ.\nPhật pháp không phải giao dịch,\ntu hành không phải đếm số.\nSố lượng có thể giúp tinh tấn,\nkhông được trở thành nỗi sợ.\nTụng xong một quyển,\nnếu tâm sinh kiêu mạn,\nvẫn nên quán chiếu;\nnửa quyển chưa xong,\nmà tâm còn cung kính,\ncũng không phải uổng công.\nĐiều thật sự quan trọng,\nlà pháp trong kinh\ncó dần thấm vào tâm con hay không.\nTụng Kinh Địa Tạng,\nnên học bi nguyện;\ntụng Kinh Kim Cang,\nnên học ly tướng;\ntụng Phẩm Phổ Môn,\nnên học từ bi.\nNếu kinh văn tuy thuộc,\ngặp việc vẫn thường nổi sân,\nthì nên tự xét\nnghĩa lý mình tụng,\ncó dùng vào đời sống hay không.\nNếu giữa lúc tụng kinh\ncó người đến tìm,\ncon có thể ôn hòa ứng đối,\nkhông vì gián đoạn mà bực bội,\nđó cũng là đem nghĩa kinh\ndùng vào hiện tại.\nCho nên ta nói:\ntụng kinh gián đoạn,\nkhông có nghĩa là đọc uổng;\nthiện niệm đã khởi,\nkhông vì tạm dừng mà thành không.\nTiếp được thì tiếp,\nkhông được thì an;\nkhông mất cung kính,\nkhông sinh sợ hãi.\nChớ chấp trước vào\nkinh văn có trọn vẹn hay không,\nmà quên mất\ntu hành vốn là vì điều gì.\nKinh có thể tạm dừng,\nthiện tâm không thể quên;\nvăn tự có thể buông xuống,\npháp nghĩa vẫn có thể phụng hành.", "Con hỏi: tụng kinh còn chưa xong, bỗng có việc đến, không thể không gián đoạn, thì những gì đã tụng trước đó có phải đều thành uổng phí không?\nTa nói:\nkinh chưa tụng xong, không có nghĩa là công đức mất hết;\ngián đoạn một lúc, không có nghĩa là công phu trước đó đều uổng phí.\nCông đức tụng kinh không chỉ nằm ở việc tụng trọn một quyển từ đầu đến cuối.\nMà còn nằm ở tâm cung kính khi tụng kinh, lợi ích của việc nghe Phật pháp, và sự tu hành thu nhiếp tâm niệm.\nCon tụng một câu, nếu có thể sinh khởi một phần cung kính;\nđọc một bài kệ, nếu có thể hiểu được một phần pháp nghĩa,\nthì dù chưa tụng xong, thiện tâm thiện hạnh ấy sao có thể nói là hoàn toàn không có?\nPhật pháp coi trọng phát tâm, cũng coi trọng thực hành.\nNếu khi đang tụng kinh, bỗng có điện thoại, có người đến thăm, hoặc có việc gấp cần phải xử lý,\nthì trước hết nên phân biệt việc nặng nhẹ, gấp hoãn.\nNếu việc không gấp, có thể đợi tụng xong rồi xử lý;\nnếu việc khẩn yếu, thì có thể tạm dừng để đi xử lý.\nĐừng vì chấp trước “một quyển nhất định phải tụng xong” mà đánh mất lòng từ bi đáng có.\nNếu cha mẹ có việc cần gấp, con cái gặp nguy nan, hoặc có người đang chờ được giúp đỡ,\nmà con lại nói: “Kinh còn chưa tụng xong, không thể gián đoạn,”\nthì lúc ấy nên tự hỏi: con đang tu từ bi, hay đang chấp trước hình thức?\nTụng kinh là để tu tâm, không phải để tâm bị trói buộc.\nKinh điển dạy chúng sinh từ bi; nếu vì tụng kinh mà lại không đoái hoài đến khổ nạn trước mắt,\nthì nên quán chiếu lại ý nghĩa của tu hành.\nNhưng cũng không thể vì thế mà sinh lười biếng.\nĐừng cho rằng việc gì cũng có thể gián đoạn, rồi để việc tụng kinh thường xuyên dừng lại vì tán loạn.\nKhi chuyên chú được thì chuyên chú; khi cần xử lý việc thì xử lý việc.\nCó việc mà tạm dừng, không mất cung kính;\nxong việc rồi tụng tiếp, cũng là tinh tấn.\nNếu giữa chừng con phải rời đi, có thể đặt quyển kinh ở nơi thanh tịnh, thích hợp,\ntrong lòng biết rõ mình tạm dừng ở chỗ nào.\nĐợi xong việc, nếu thời gian cho phép, thì tụng tiếp từ chỗ gián đoạn.\nNếu muốn tụng lại từ đầu, cũng không sao cả.\nNếu hôm nay thật sự không có thời gian, ngày mai tụng tiếp, không cần vì thế mà tự trách.\nCòn về hồi hướng, có thể sau khi tụng xong một đoạn, theo thói quen tu trì của mình mà hồi hướng;\nnếu vì có việc mà chưa tụng xong, cũng có thể phát tâm hồi hướng những thiện hạnh đã tu.\nTâm hồi hướng không cần đợi đến khi một quyển viên mãn mới có thể khởi lên.\nNếu con hỏi: “Chưa tụng xong, Bồ Tát có trách không?”\nTa khuyên con: đừng xem tụng kinh như nộp đủ số lượng cho chư Phật, Bồ Tát.\nCũng đừng cho rằng tụng thiếu một câu là thành ra mắc nợ.\nPhật pháp không phải là giao dịch, tu hành không phải là đếm số.\nSố lượng có thể giúp tinh tấn, nhưng không được trở thành nỗi sợ hãi.\nTụng xong một quyển, nếu tâm sinh kiêu mạn, vẫn nên quán chiếu;\nnửa quyển chưa tụng xong, nếu tâm còn cung kính, cũng không phải là uổng công.\nĐiều thật sự quan trọng là pháp trong kinh có dần dần đi vào tâm con hay không.\nTụng Kinh Địa Tạng, nên học bi nguyện;\ntụng Kinh Kim Cang, nên học ly tướng;\ntụng Phẩm Phổ Môn, nên học từ bi.\nNếu kinh văn tuy đã rất thuộc, mà gặp việc vẫn thường nổi sân hận,\nthì nên tự xét xem nghĩa lý mình tụng có được dùng trong đời sống hay không.\nNếu giữa lúc tụng kinh có người đến tìm con, mà con có thể ôn hòa ứng đối, không vì bị gián đoạn mà bực bội,\nthì đó cũng là đem nghĩa kinh dùng vào hiện tại.\nCho nên ta nói:\ntụng kinh gián đoạn, không có nghĩa là đọc uổng;\nthiện niệm đã sinh khởi, sẽ không vì tạm dừng mà mất đi.\nTiếp được thì tiếp, không tiếp được thì an tâm;\nkhông mất cung kính, không sinh sợ hãi.\nĐừng chấp trước vào việc kinh văn có trọn vẹn hay không, mà quên mất tu hành vốn là vì điều gì.\nKinh có thể tạm dừng, thiện tâm không thể quên;\nvăn tự có thể buông xuống, pháp nghĩa vẫn có thể phụng hành."]}, "054": {"title": "Thấy ác mà không khuyên, là từ bi hay hèn nhát?", "summary": "Không đồng ý chưa hẳn là ác, im lặng cũng chưa hẳn là sai; trước hết hãy phân biệt khác biệt và tổn hại, khuyên mà không cưỡng cầu, từ bi không dung túng cái ác.", "blocks": ["Thỉnh hỏi Địa Tạng Vương Bồ Tát:\n“Nếu bạn bè làm việc mà tôi không đồng ý, nhưng tôi không ngăn cản hay khuyên bảo, như vậy có phải là không đúng không? Xin Bồ Tát từ bi khai thị.”", "Thiện nam tử,\ncon hỏi bạn bè hành sự,\nkhông hợp với ý mình,\nnếu không ngăn cản,\ncũng không khuyên bảo,\ncó phải là thiếu từ bi,\ncó phải là có lỗi chăng?\nNay ta bảo con:\nđiều không đồng ý, chưa hẳn là ác;\nkhông khuyên bảo, chưa hẳn là sai.\nChúng sinh thế gian,\nmỗi người có kiến giải riêng,\nmỗi người có tập tánh riêng,\nmỗi người có nhân duyên riêng.\nĐiều con ưa thích,\nhọ chưa chắc ưa thích;\nđiều con tin tưởng,\nhọ chưa chắc tin tưởng.\nNếu hễ điều gì không hợp ý mình,\nliền muốn người khác phải sửa,\nthì đó không phải từ bi;\ncó khi là ngã chấp.\nCho nên trước hết hãy hỏi:\nviệc này rốt cuộc là bất thiện,\nhay chỉ khác với kiến giải của mình?\nNếu chỉ là tính tình khác nhau,\nlựa chọn khác nhau,\ncách sống khác nhau,\nkhông hại mình,\ncũng không hại người,\nthì không cần việc gì cũng khuyên.\nBao dung được người khác mình,\ncũng là tu hành.\nKiến giải có thể khác nhau,\ntừ bi không vì thế mà giảm.\nNhưng nếu việc bạn con làm\nthật sự làm hại người khác —\nlừa dối, chiếm đoạt,\nhoặc tạo các điều bất thiện —\ncon đã biết là không ổn,\nlại có nhân duyên để khuyên,\nthì nên suy xét:\nlàm sao dùng thiện xảo phương tiện,\nkhiến họ biết lỗi.\nLúc ấy nếu chỉ cầu\ngiữ gìn thể diện,\nbiết rõ có người bị hại,\nmà hoàn toàn không đoái hoài,\nthì nên tự xét\ncó phải vì sợ hãi,\nlạnh lùng hay tham luyến mối quan hệ,\nmà bỏ đi việc thiện đáng làm.\nNhưng ta cũng bảo con:\nkhuyên người làm thiện,\nkhông có nghĩa là phải tranh cãi với người;\nthấy người có lỗi,\nkhông có nghĩa là phải cưỡng ép ngăn cản.\nCó những người,\nmột lời liền tỉnh;\ncó những người,\ntrăm lời không nghe.\nCó những lúc,\nnên nói thẳng;\ncó những lúc,\nphải đợi nhân duyên.\nCho nên trước khi khuyên người,\nhãy quán sát bốn điều:\nViệc ấy có thật sự sai không?\nLời mình có đúng sự thật không?\nThời điểm có thích hợp không?\nTâm mình có phát xuất từ lòng từ bi không?\nNếu lời tuy thật,\nmà mang lòng sân hận,\nthì lời thiện cũng có thể\ntrở thành khí cụ làm tổn thương người.\nNếu lời tuy mềm mỏng,\nmà dung túng điều hại,\nthì sự ôn hòa cũng chưa hẳn\nlà từ bi chân thật.\nChân thật mà không ác khẩu;\ntừ bi mà không dung túng.\nNếu con thấy bạn có lỗi,\ncó thể khuyên riêng trước,\nkhông cần trách móc trước mặt mọi người,\nkhiến họ mất thể diện.\nKhi khuyên,\nchớ dùng tâm cao hơn người,\nmà chỉ ra lỗi của họ.\nHãy dùng tâm bình đẳng,\nnói rõ lợi hại.\nCó thể nói:\n‘Tôi chưa chắc đã hiểu hết,\nnhưng việc này e rằng gây tổn hại,\nmong bạn suy nghĩ lại.’\nNếu họ chịu nghe,\nthì khéo léo giải thích;\nnếu họ không chịu,\ncũng không cần dùng giận dữ ép buộc.\nKhuyên bảo là thiện ý của con;\nthay đổi là lựa chọn của họ.\nNhưng lời này cũng có giới hạn.\nNếu trước mắt có người đang bị hại,\nmà tình thế cấp bách,\ncon có khả năng giúp đỡ an toàn,\nthì không được chỉ lấy\n‘mỗi người có nhân quả riêng’\nlàm lý do khoanh tay đứng nhìn.\nCó thể ngăn chặn an toàn,\nthì nên ngăn chặn;\ncó thể tìm người trợ giúp,\nthì nên cầu viện;\nkhông thể tự mình xử lý,\ncũng có thể tìm người thích hợp\ngiúp ngăn chặn điều hại.\nTôn trọng lựa chọn của người khác,\nkhông phải là để mặc người khác gây hại.\nNếu bạn con nhiều lần được khuyên mà không nghe,\nvẫn tiếp tục tạo điều bất thiện,\ncon cũng nên biết:\ntừ bi có thể luôn còn,\ngiao du có thể có giới hạn.\nKhông cần vì tình nghĩa nhiều năm,\nmà che giấu lỗi lầm cho họ;\ncũng không cần vì họ phạm lỗi,\nmà sinh lòng oán ghét mãi mãi.\nKhông giúp cái ác của họ,\ncũng không bỏ cái thiện của họ;\nkhông dung túng việc làm của họ,\ncũng không oán ghét con người họ.\nCon lại nên quán tâm mình.\nCó khi không khuyên,\nlà vì trí tuệ,\nbiết lúc này không nên nói.\nCó khi không khuyên,\nlà vì sợ hãi,\nsợ mất đi người bạn.\nCó khi không khuyên,\nlà vì lạnh lùng,\ncho rằng người khác chịu khổ\nchẳng liên quan đến mình.\nBên ngoài đều là im lặng,\nbên trong lại khác nhau.\nCho nên chớ chỉ hỏi:\n‘Tôi không khuyên —\ncó phải là sai không?’\nMà càng nên hỏi:\n‘Vì sao tôi không khuyên?\nTôi có biết rõ là có hại không?\nTôi có khả năng giúp đỡ không?\nSự im lặng của tôi,\ncó khiến tổn hại tiếp diễn không?’\nCùng một sự im lặng,\ncó thể là trí tuệ,\ncũng có thể là hèn nhát;\nphải quán xét tâm,\ncũng phải quán xét kết quả.\nThiện nam tử,\ntu hành không phải là\ncải tạo tất cả bạn bè\nthành người mình tán đồng.\nCũng không phải là\nthấy điều bất thiện,\nliền nhất loạt im lặng.\nTừ bi chân thật,\ncó khi là lời ôn hòa khuyên nhủ;\ncó khi là lặng lẽ lắng nghe;\ncó khi là tôn trọng khác biệt;\ncó khi là kiên quyết ngăn ác.\nTừ bi phải có trí tuệ;\ntrí tuệ không thể thiếu lòng bi.\nNếu con đã tận hết thiện ý,\nmà họ vẫn không chịu sửa,\nthì không cần đem mọi hậu quả của họ\ngánh lên vai mình.\nCon có thể khuyên về nhân,\nkhông thể làm thay họ;\ncon có thể chỉ đường,\nkhông thể đi thay họ.\nNhưng nếu vẫn còn chúng sinh bị hại,\nhãy nghĩ xem mình còn có cách giúp\nhợp lý, an toàn nào.\nSau cùng ta dùng bốn câu bảo con:\nThấy khác chẳng cần tranh,\nthấy ác nên nghĩ khuyên;\nkhuyên mà không cưỡng cầu,\ntừ bi không dung ác.\nLại nói:\nChẳng lấy ý mình trói buộc người,\nchẳng vì tình nghĩa che lỗi họ;\nkhuyên được thì khuyên, nên dừng thì dừng,\ntận hết thiện hạnh, chẳng chấp quả.", "Thiện nam tử,\ncon hỏi: bạn bè làm việc không hợp với ý con,\nnếu con không ngăn cản, cũng không khuyên bảo,\nnhư vậy có phải là thiếu từ bi không? Có phải là có lỗi không?\nNay ta bảo con:\nđiều không đồng ý, chưa chắc đã là ác; không khuyên bảo, cũng chưa chắc đã là sai.\nChúng sinh trong thế gian,\nmỗi người có kiến giải riêng,\nmỗi người có tập tánh riêng,\nmỗi người có nhân duyên riêng.\nĐiều con thích, người kia chưa chắc thích;\nđiều con tin, người kia chưa chắc tin.\nNếu hễ không hợp ý mình là muốn người khác phải sửa đổi,\nthì đó không phải từ bi, mà có thể là ngã chấp.\nCho nên trước hết nên hỏi:\nviệc này rốt cuộc là tự nó bất thiện, hay chỉ là khác với kiến giải của mình?\nNếu chỉ là tính tình khác nhau,\nlựa chọn khác nhau,\ncách sống khác nhau,\nmà không làm hại bản thân, cũng không làm hại người khác,\nthì không cần việc gì cũng phải khuyên bảo.\nBao dung được người khác không giống mình, cũng là một cách tu hành.\nKiến giải có thể khác nhau, từ bi không vì thế mà giảm bớt.\nNhưng nếu việc bạn con làm thật sự gây hại cho người khác,\nchẳng hạn như lừa dối, chiếm đoạt, hoặc tạo các điều bất thiện,\nmà con đã biết là không ổn, lại có nhân duyên để khuyên,\nthì nên suy nghĩ: làm sao dùng thiện xảo phương tiện, để họ biết lỗi lầm của mình.\nLúc ấy nếu chỉ cầu giữ gìn thể diện,\nbiết rõ có người bị hại mà hoàn toàn không đoái hoài,\nthì nên tự xét: có phải vì sợ hãi, lạnh lùng, hay tham luyến mối quan hệ này, mà đã bỏ đi việc thiện lẽ ra nên làm.\nNhưng ta cũng bảo con:\nkhuyên người làm thiện, không có nghĩa là nhất định phải tranh cãi với họ; thấy người có lỗi, cũng không có nghĩa là nhất định phải cưỡng ép ngăn cản.\nCó những người, chỉ một câu là tỉnh ngộ;\ncó những người, nói trăm câu cũng không nghe lọt.\nCó những lúc, nên nói thẳng;\ncó những lúc, phải đợi nhân duyên.\nCho nên trước khi khuyên người, nên quán sát bốn điều:\nViệc này có thật sự sai không?\nLời con nói có đúng sự thật không?\nLúc này có thích hợp để nói không?\nTâm con có phát xuất từ lòng từ bi không?\nNếu lời tuy chân thật mà mang theo sân hận,\nthì lời thiện ý cũng có thể trở thành vũ khí làm tổn thương người.\nNếu lời tuy ôn hòa mà dung túng điều gây hại,\nthì sự ôn hòa cũng chưa chắc là từ bi chân thật.\nChân thật mà không ác khẩu, từ bi mà không dung túng.\nNếu con thấy bạn có lỗi, có thể khuyên riêng trước,\nkhông cần trách móc trước mặt mọi người, khiến họ mất thể diện.\nKhi khuyên, đừng dùng thái độ cao hơn người để chỉ trích lỗi của họ.\nHãy dùng tâm bình đẳng, nói cho họ biết lợi hại.\nCó thể nói như thế này:\n“Tôi chưa chắc đã hiểu hết, nhưng việc này e rằng sẽ gây tổn hại, mong bạn suy nghĩ thêm.”\nNếu họ chịu nghe, thì khéo léo giải thích cho họ;\nnếu họ không chịu nghe, cũng không cần dùng giận dữ để ép buộc họ.\nKhuyên bảo là thiện ý của con, thay đổi là lựa chọn của họ.\nNhưng lời này cũng có giới hạn.\nNếu trước mắt có người đang bị hại, mà tình thế cấp bách,\ncon có khả năng giúp đỡ một cách an toàn, thì không được chỉ lấy “mỗi người có nhân quả riêng” làm lý do khoanh tay đứng nhìn.\nCó thể ngăn chặn an toàn, thì nên ngăn chặn;\ncó thể tìm trợ giúp, thì nên cầu viện;\nkhông thể tự mình xử lý, cũng có thể tìm người thích hợp giúp ngăn chặn tổn hại.\nTôn trọng lựa chọn của người khác, không phải là để mặc người khác gây hại.\nNếu bạn con nhiều lần được khuyên mà không nghe, vẫn tiếp tục tạo điều bất thiện,\ncon cũng nên biết:\ntừ bi có thể luôn còn, giao du có thể có ranh giới.\nKhông cần vì tình nghĩa nhiều năm mà che giấu lỗi lầm cho họ;\ncũng không cần vì họ phạm lỗi mà sinh lòng oán ghét mãi mãi.\nKhông tiếp tay cho cái ác của họ, cũng không bỏ đi cái thiện của họ;\nkhông dung túng hành vi của họ, cũng không oán ghét con người họ.\nCon lại nên quán sát tâm mình.\nCó khi không khuyên là vì trí tuệ, biết lúc này không thích hợp để nói.\nCó khi không khuyên là vì sợ hãi, sợ mất đi người bạn.\nCó khi không khuyên là vì lạnh lùng, cho rằng người khác chịu khổ chẳng liên quan gì đến mình.\nBên ngoài đều là im lặng, nhưng bên trong lại khác nhau.\nCho nên đừng chỉ hỏi: “Tôi không khuyên — có phải là sai không?”\nMà càng nên hỏi:\n“Vì sao tôi không khuyên?\nTôi có biết rõ là có hại không?\nTôi có khả năng giúp đỡ không?\nSự im lặng của tôi có khiến tổn hại tiếp diễn không?”\nCùng là im lặng, có thể là trí tuệ, cũng có thể là hèn nhát;\nphải quán sát tâm mình, cũng phải quán sát kết quả của nó.\nThiện nam tử,\ntu hành không phải là cải tạo tất cả bạn bè thành người mình tán đồng.\nCũng không phải là thấy điều bất thiện thì nhất loạt im lặng.\nTừ bi chân thật,\ncó khi là lời ôn hòa khuyên nhủ;\ncó khi là lặng lẽ lắng nghe;\ncó khi là tôn trọng khác biệt;\ncó khi là kiên quyết ngăn ác.\nTừ bi phải có trí tuệ, trí tuệ không thể thiếu từ bi.\nNếu con đã tận hết thiện ý mà người kia vẫn không chịu sửa,\nthì không cần đem mọi hậu quả của họ gánh hết lên vai mình.\nCon có thể khuyên họ từ nơi nhân, nhưng không thể hành động thay họ;\ncon có thể chỉ đường, nhưng không thể đi thay họ.\nNhưng nếu vẫn còn chúng sinh bị hại, thì nên nghĩ xem mình còn có cách nào hợp lý, an toàn để giúp đỡ.\nSau cùng ta dùng bốn câu bảo con:\nThấy khác chẳng cần tranh,\nthấy ác nên nghĩ khuyên;\nkhuyên mà không cưỡng cầu,\ntừ bi không dung ác.\nLại nói:\nChẳng lấy ý mình trói buộc người,\nchẳng vì tình nghĩa che lỗi họ;\nkhuyên được thì khuyên, nên dừng thì dừng,\ntận hết thiện hạnh, chẳng chấp quả."]}, "055": {"title": "Đức Phật có phản đối chú ngữ không?", "summary": "Điều Đức Phật quở trách là dùng chú thuật để mưu sinh, mê hoặc chúng sinh; trì chú là để nhiếp tâm, hộ sinh, không thể đánh đồng với tà mạng, nhưng trì chú không đồng nghĩa với chứng ngộ.", "blocks": ["Đệ tử xin thỉnh hỏi:\nKinh số 189 trong Trung A Hàm, tức Kinh Thánh Đạo, có nói “dùng các loại chú thuật súc sinh, sống bằng tà mạng”. Nhưng trong các kinh điển Đại thừa về sau, cũng có ghi chép Đức Phật tuyên thuyết đà-la-ni và chân ngôn. Điều Đức Phật phản đối lúc ban đầu, rốt cuộc là bản thân chú ngữ, hay là hành vi dùng chú thuật để mưu cầu lợi ích thế gian và lấy đó làm kế sinh nhai? “Chú thuật súc sinh” rốt cuộc là chỉ điều gì?", "“Thiện nam tử,\ncon đọc Trung A Hàm,\nthấy Phật nói về ‘chú thuật súc sinh’,\nsống bằng tà mạng.\nLại xem giáo pháp Đại thừa,\nthấy đà-la-ni, chân ngôn\ncũng do cửa Phật truyền lại.\nTrong tâm sinh nghi vấn:\ncùng là chú ngữ,\nvì sao một bên bị quở trách,\nmột bên được thọ trì?\nNay ta khuyên con:\nhọc Phật phải phân biện nghĩa lý,\nkhông thể chỉ chấp vào danh xưng.\nPhật pháp có giới,\ncó định,\ncó tuệ.\nCũng có phương tiện,\ntùy căn cơ chúng sinh\nthiết lập nhiều pháp môn.\nNhưng hết thảy phương tiện\nđều phải xét xem hướng về đâu.\nNếu dùng chú thuật\nbói toán cát hung,\nhù dọa chúng sinh,\ntham cầu cúng dường,\nhoặc mượn danh thần dị\nlừa người lấy của,\nthì dù miệng xưng Phật pháp,\ncũng phải thận trọng xét kỹ.\nDanh tuy xưng Phật,\nhạnh nếu trái Đạo,\nkhông thể vì danh mà cho là chánh pháp.\nCòn nếu trì tụng kinh chú\nđể nhiếp giữ chánh niệm,\nnhớ nghĩ Tam Bảo,\nphát nguyện hộ sinh,\nnuôi lớn từ bi,\nthì cũng không thể chỉ vì\nmang danh chú ngữ\nmà đánh đồng với tà mạng.\nNhưng phải hiểu rõ:\ntrì chú không đồng nghĩa với chứng ngộ,\ncảm ứng không đồng nghĩa với giải thoát.\nNếu tụng chú ngàn biến\nmà tham sân vẫn như cũ,\nnếu cầu che chở\nmà chẳng tu thiện,\nthì nên tự xét\nsự tu hành có lệch khỏi bản ý chăng.\nCon lại hỏi:\nthế nào là ‘chú thuật súc sinh’?\nChớ thấy hai chữ ‘súc sinh’\nmà cho rằng đó là\nchú do súc sinh tụng.\nNghĩa ở đây\nphải thận trọng phân tích\ntheo mạch văn của kinh\nvà ngữ nghĩa Ấn Độ cổ.\nKhông thể chỉ nhìn mặt chữ\nmà đoán định điều được chỉ.\nĐọc kinh nên cầu bản nghĩa,\ntu hành nên xét nơi tâm.\nLại chớ vì\nđời sau có đà-la-ni\nmà cho rằng điều kinh giáo thời đầu\nbài xích\nhoàn toàn không có phân biệt.\nCũng chớ vì\nkinh giáo thời đầu phê phán chú thuật\nmà đoán định mọi\npháp tu đà-la-ni\nđều là tà pháp.\nGiữa hai điều ấy,\nvừa có sự phân biện về giới luật,\ncũng có sự khác biệt trong sự phát triển của giáo pháp.\nNên như thật mà tìm hiểu,\nkhông thể gượng ép cho giống nhau,\ncũng không thể dễ dàng nói là khác.\nThiện nam tử,\nnếu con hỏi\nđiều Đức Phật thật sự xem trọng là gì,\nthì hãy quán từ chánh mạng,\nchánh kiến,\nlìa tham,\nvà con đường lìa khổ.\nLấy pháp nuôi tuệ,\nkhông lấy thuật nuôi tham;\nlấy giới giữ tâm,\nkhông lấy dị tướng mê hoặc chúng sinh.\nChớ vì một câu kinh\nmà khinh suất chê bai tông phái khác;\nchớ vì một đoạn chân ngôn\nmà xem nhẹ giới luật.\nNguyện con trì kinh\nkhông mất sự suy xét;\nnguyện con tu pháp\nkhông mất chánh kiến.\nBiết điều được nói,\ncàng biết điều được chỉ;\nphân biện phương tiện,\ncũng phân biện mục đích.\nChớ chấp văn tự mà sinh tranh cãi,\nhãy y chánh pháp mà cầu sáng tỏ.”", "Thiện nam tử,\ncon đọc Kinh Trung A Hàm,\nthấy Đức Phật nói “chú thuật súc sinh, sống bằng tà mạng”.\nRồi con lại thấy trong kinh điển Đại thừa\ncó ghi chép đà-la-ni và chân ngôn,\ncũng là do nhà Phật truyền lại.\nThế là trong lòng con nảy sinh thắc mắc:\ncùng là chú ngữ,\ntại sao một loại bị Đức Phật quở trách,\ncòn loại kia lại được Phật giáo trì tụng?\nNay ta khuyên con:\nhọc Phật nên phân biện ý nghĩa của nó,\nkhông được chỉ chấp vào tên gọi.\nPhật pháp có giới, có định, có tuệ.\nCũng có các pháp môn phương tiện,\ntùy theo căn cơ của chúng sinh\nmà thiết lập nhiều phương pháp tu hành.\nNhưng mọi pháp môn phương tiện\nđều nên xem xét phương hướng và mục đích của nó.\nNếu lợi dụng chú thuật\nđể bói toán cát hung,\nhù dọa chúng sinh,\ntham cầu cúng dường,\nhoặc nhân danh thần dị\nđể lừa gạt người khác, lừa lấy tiền của,\nthì dù miệng có xưng niệm Phật pháp,\ncũng nên thận trọng quan sát.\nTên gọi tuy nói là Phật,\nnhưng nếu hành vi đi ngược chánh đạo,\nthì không được vì tên gọi mà cho đó là chánh pháp.\nNhưng nếu trì tụng kinh chú\nlà để thu nhiếp chánh niệm,\nnhớ nghĩ Tam Bảo,\nphát nguyện bảo vệ sự sống,\nnuôi lớn lòng từ bi,\nthì cũng không được chỉ vì\nnó mang tên chú ngữ\nmà đánh đồng nó với tà mạng.\nNhưng phải hiểu rõ:\ntrì chú không đồng nghĩa với chứng ngộ,\ncảm ứng không đồng nghĩa với giải thoát.\nNếu tụng chú ngàn biến\nmà tham sân vẫn y như cũ,\nnếu cầu Phật che chở\nmà không tu thiện,\nthì nên tự xét lại\nxem sự tu hành có lệch khỏi bản ý hay không.\nCon lại hỏi:\nthế nào là “chú thuật súc sinh”?\nĐừng thấy hai chữ “súc sinh”\nmà cho rằng đó là chú do súc sinh tụng.\nÝ nghĩa ở đây\nphải được phân tích thận trọng\ndựa theo mạch văn của kinh\nvà ngữ nghĩa của Ấn Độ cổ đại.\nKhông được chỉ nhìn vào mặt chữ\nmà đoán định nó chỉ điều gì.\nĐọc kinh nên tìm cầu bản nghĩa;\ntu hành nên quan sát tâm mình.\nCũng đừng vì\nđời sau có đà-la-ni\nmà cho rằng những điều kinh giáo thời đầu\nđã quở trách\nhoàn toàn không có gì khác biệt.\nCũng đừng vì\nkinh giáo thời đầu phê phán chú thuật\nmà đoán định rằng mọi\npháp tu đà-la-ni\nđều là tà pháp.\nGiữa hai điều này,\nvừa có sự phân biện về mặt giới luật,\ncũng có sự khác biệt về mặt phát triển giáo pháp.\nNên như thật mà tìm hiểu,\nkhông được gượng ép nói chúng giống nhau,\ncũng không được dễ dàng nói chúng hoàn toàn khác nhau.\nThiện nam tử,\nnếu con hỏi\nrốt cuộc Đức Phật xem trọng điều gì,\nthì nên quan sát từ chánh mạng, chánh kiến,\nvà con đường lìa tham, lìa khổ.\nLấy Phật pháp nuôi lớn trí tuệ,\nkhông lấy phương thuật nuôi lớn tham dục;\nlấy giới luật giữ gìn tâm mình,\nkhông lấy tướng lạ mê hoặc chúng sinh.\nĐừng vì một câu kinh\nmà khinh suất chê bai tông phái khác;\nđừng vì một đoạn chân ngôn\nmà xem nhẹ giới luật.\nNguyện con trì kinh\nmà không mất khả năng suy xét;\nnguyện con tu pháp\nmà không mất chánh kiến.\nBiết nó đã nói gì,\ncàng phải biết nó hướng đến điều gì;\nphân biện phương tiện của nó,\ncũng phân biện mục đích của nó.\nĐừng chấp vào văn tự mà sinh ra tranh cãi,\nhãy y theo chánh pháp mà cầu được sáng tỏ."]}, "056": {"title": "Thế nào là dụng tâm?", "summary": "Dụng tâm không phải là dùng sức, mà là tâm thật sự có mặt: chuyên chú, tư duy, thực hành, để điều đã học thật sự chuyển hóa chính mình.", "blocks": ["🔶 Đệ tử xin thỉnh hỏi Địa Tạng Vương Bồ Tát:\n“Đệ tử thường nghe nói ‘dụng tâm học tập’, chữ ‘tâm’ này rốt cuộc là chỉ điều gì?”", "“Thiện nam tử,\nnay con hỏi:\nngười đời thường nói\n‘dụng tâm học tập’.\nNhưng tâm này rốt cuộc là vật gì?\nLà trái tim đập trong lồng ngực?\nLà ý niệm suy nghĩ trong đầu óc?\nLà thức nhớ giữ và phân biệt?\nHay là tâm mà Phật pháp nói đến?\nNay ta vì con nói rõ.\nTâm chẳng phải một vật,\nkhông thể chấp một chỗ mà tìm.\nDụng tâm mà người đời nói,\nphần nhiều chỉ sự chuyên chú, tư duy,\nthấu hiểu, ghi nhớ và ý nguyện.\nNhưng theo Phật pháp mà quán,\ntác dụng của tâm\nchẳng dừng ở đó.\nMắt thấy sắc,\ntai nghe tiếng,\ný có thể tư duy,\nthức có thể phân biệt.\nGặp việc sinh vui,\ngặp nghịch sinh sân,\nthấy thiện muốn làm,\nthấy ác muốn tránh.\nNhững hoạt động thân tâm ấy\nđều liên quan đến tâm thức.\nNhưng con phải biết:\nbiết suy nghĩ\nchưa hẳn là dụng tâm;\nbiết ghi nhớ\nchưa hẳn là học thật.\nCó người đọc kinh ngàn lượt,\nchỉ cầu thuộc làu văn chữ,\nchẳng nghĩ pháp nghĩa trong kinh,\ncũng chẳng quán chiếu tự thân.\nCó người nghe một câu pháp,\ntư duy đi tư duy lại,\ntrong đời sống hằng ngày\ndần dần bớt được phiền não.\nĐiều hai người ấy học,\nđiều nào thấm vào tâm hơn?\nCho nên ta nói:\ndụng tâm không chỉ là ghi nhớ tri thức,\nmà là khiến điều đã học thật sự thay đổi chính mình.\nCon nếu học một pháp,\nnên có ba tầng.\nThứ nhất, tâm an trú được.\nKhi đọc kinh biết mình đang đọc kinh,\nkhi nghe pháp biết mình đang nghe pháp.\nKhông để tán loạn lôi kéo,\nkhông theo vọng niệm rong ruổi.\nĐó là chuyên chú.\nThứ hai, tâm tư duy được.\nNghe một pháp nghĩa,\nkhông chỉ tiếp nhận,\nmà còn hỏi nguyên nhân,\nquán đạo lý,\nphân biện xem có hợp\nvới kinh giáo và thực tế chăng.\nĐó là tư trạch.\nThứ ba, tâm thực hành được.\nNgười biết từ bi\nnên hành từ bi khi đối đãi với người.\nNgười biết vô thường\nnên bớt chấp trước khi được mất.\nNgười biết nhân quả\nnên thận trọng tạo tác\nkhi khởi tâm động niệm.\nĐó là tu hành.\nChuyên chú khiến tâm không tán loạn,\ntư duy khiến lý dần sáng tỏ,\nthực hành khiến pháp thấm vào thân.\nCon nếu chỉ cầu chuyên chú\nmà không phân biện phải trái,\nthì sự chuyên chú cũng có thể\nbị dùng vào việc bất thiện.\nCon nếu chỉ cầu tri thức\nmà không chịu thực hành,\nthì điều biết tuy nhiều,\nphiền não chưa chắc giảm bớt.\nCho nên tâm mà người học Phật nói đến,\nkhông chỉ ở định,\nmà còn phải có tuệ.\nKhông chỉ ở tuệ,\nmà còn phải có từ bi.\nThiện nam tử,\ncon lại nên biết:\ntâm không phải là người chủ vĩnh viễn bất biến.\nTâm hôm nay\nvới tâm hôm qua\nniệm niệm sinh diệt.\nNhân cảnh mà khởi,\ntheo duyên mà chuyển.\nMột niệm hoan hỷ,\nmột niệm âu sầu;\nmột niệm từ bi,\nmột niệm đố kỵ.\nNếu chấp một niệm trong đó,\ncho rằng đó chính là\nchân ngã vĩnh hằng,\nthì lại sinh mê lầm.\nPhật pháp quán tâm,\nkhông chỉ là tìm xem\n‘tâm ở đâu’,\nmà còn quán sát:\ntâm sinh khởi thế nào?\nVì sao phan duyên?\nThọ khổ ra sao?\nVà làm sao dứt được nhân của khổ?\nBiết tâm khởi thế nào,\nmới quán được tâm biến đổi;\nbiết tâm vô thường,\nmới không bị tâm trói buộc.\nVí như con tụng Kinh Kim Cang,\nnghe câu ‘Ưng vô sở trụ nhi sinh kỳ tâm’.\nĐó không phải dạy con\nđừng suy nghĩ,\nđừng cảm nhận,\ncũng không phải dạy con\nthành người vô niệm.\nMà là khuyên con:\nkhi làm thiện,\nkhông chấp trước công đức;\nkhi đối đãi với người,\nkhông chấp trước sự đền đáp;\nkhi học pháp,\nkhông chấp rằng mình\nđã hơn người một bậc.\nTâm có thể có chỗ hành,\nnhưng chẳng cần chỗ nào cũng có chỗ chấp.\nCon nếu hỏi:\n‘Rốt cuộc thế nào mới gọi là dụng tâm?’\nTa lấy một việc mà nói với con.\nCó người nói chuyện với con,\ncon tuy nghe thấy tiếng,\nnhưng trong lòng chỉ nghĩ\nlàm sao bác lại,\nđó là tai nghe,\nchưa hẳn là tâm nghe.\nNếu con có thể tạm gác kiến giải của mình,\nlắng nghe ý họ,\nthấu hiểu nỗi khổ của họ,\nrồi lấy trí tuệ mà đáp lại,\nđó chính là dụng tâm.\nCó người đọc kinh,\nchỉ đếm hôm nay tụng được mấy quyển,\nđó là một phần của tinh tấn,\nnhưng chưa phải là tất cả.\nNếu đọc đến một câu,\nbỗng thấy nơi mình thường ngày\nnhững chỗ tham đắm, sân hận,\nmà chịu sửa đổi,\nđó chính là pháp đã vào tâm.\nDụng tâm không phải là tâm gắng sức,\nmà là tâm thật sự có mặt.\nKhông phải nắm chặt từng ý niệm,\nmà là biết rõ\nmình đang làm gì.\nKhông phải việc gì nghĩ càng nhiều\nthì càng là dụng tâm.\nSuy nghĩ quá độ\ncũng có thể thành chướng ngại.\nCó khi dụng tâm\nlà suy nghĩ nghiêm túc;\ncó khi dụng tâm\nlà buông xả tạp niệm;\ncó khi dụng tâm\nlà chuyên tâm lắng nghe;\ncó khi dụng tâm\nlà thấy được sự chấp trước của mình\nvà chịu buông xả.\nThiện nam tử,\nta lại bảo con:\ntâm nếu tán loạn,\nhọc mà khó vào;\ntâm nếu chấp trước,\nhọc mà khó thông;\ntâm nếu trong sáng,\nhọc mà phân biện được;\ntâm nếu từ bi,\nhọc mà thực hành được.\nCho nên dụng tâm học tập,\nkhông chỉ là cầu hiểu biết,\nmà còn là học cách\nvận dụng tâm của chính mình.\nLấy chánh niệm nhiếp tâm,\nlấy trí tuệ biện lý,\nlấy từ bi đãi người,\nlấy hành động ấn chứng.\nSau cùng ta dùng bốn câu\nkhuyên con:\ndụng tâm chẳng phải dụng sức,\nchuyên chú chẳng phải chấp trước;\nnghe pháp phải nghĩ nghĩa,\nrõ lý phải thực hành.\nLại nói:\ntâm không ở chỗ cầu hình tướng,\nmà ở chỗ quán tác dụng;\nhọc không ở chỗ biết nhiều,\nmà ở chỗ có chuyển được tâm hay không.\nThiện nam tử,\nnếu hôm nay con nghe một pháp,\nngày mai bớt khởi một phần sân hận,\nhôm nay con hiểu một lý,\nngày mai thêm hành một phần từ bi,\nđó chính là\nquả lành\nmà sự dụng tâm học tập chân thật có thể kết thành.”", "Thiện nam tử,\nnay con hỏi:\nngười đời thường nói “dụng tâm học tập”.\nNhưng “tâm” này rốt cuộc là gì?\nLà trái tim đập trong lồng ngực?\nLà những ý nghĩ trong đầu?\nLà ý thức ghi nhớ và phân biệt?\nHay là tâm mà Phật pháp nói đến?\nNay ta nói rõ cho con.\nTâm không phải là một vật cố định,\nkhông thể chấp vào một chỗ nào đó mà đi tìm nó.\nDụng tâm mà người đời nói,\nphần nhiều là chỉ sự chuyên chú, suy nghĩ, thấu hiểu, ghi nhớ và ý nguyện.\nNhưng theo Phật pháp mà xét,\ntác dụng của tâm không chỉ có vậy.\nMắt thấy sắc tướng,\ntai nghe âm thanh,\ný niệm có thể suy nghĩ,\ný thức có thể phân biệt.\nGặp chuyện thì sinh vui mừng,\ngặp nghịch cảnh thì sinh sân hận,\nthấy điều thiện thì muốn làm,\nthấy điều ác thì muốn tránh.\nNhững hoạt động thân tâm này\nđều có liên quan đến tâm thức.\nNhưng con phải biết:\nbiết suy nghĩ chưa hẳn đã là dụng tâm;\nbiết ghi nhớ chưa hẳn đã là học thật.\nCó người đọc kinh cả ngàn lượt,\nchỉ cầu học thuộc văn chữ,\nkhông suy nghĩ về pháp nghĩa trong kinh,\ncũng không quán chiếu bản thân.\nCó người nghe được một câu pháp,\nsuy ngẫm đi suy ngẫm lại,\ntrong đời sống dần dần bớt được phiền não.\nĐiều mà hai người này học,\nđiều nào thấm vào tâm hơn?\nCho nên ta nói:\ndụng tâm không chỉ là ghi nhớ tri thức,\nmà là để điều đã học thật sự thay đổi chính mình.\nKhi con học một pháp,\nnên có ba tầng.\nThứ nhất, tâm có thể an trú.\nKhi đọc kinh biết mình đang đọc kinh,\nkhi nghe pháp biết mình đang nghe pháp.\nKhông để tâm bị tán loạn lôi đi,\nkhông chạy theo vọng niệm.\nĐó là chuyên chú.\nThứ hai, tâm có thể tư duy.\nKhi nghe một pháp nghĩa,\nkhông chỉ tiếp nhận,\nmà còn phải hỏi nguyên nhân của nó,\nquan sát đạo lý của nó,\nphân biện xem nó có phù hợp với kinh giáo và thực tế hay không.\nĐó là tư trạch (suy xét và phân định).\nThứ ba, tâm có thể thực hành.\nNgười biết từ bi,\nnên thực hành từ bi khi đối đãi với người.\nNgười biết vô thường,\nnên bớt chấp trước khi được mất.\nNgười biết nhân quả,\nnên thận trọng tạo tác khi khởi tâm động niệm.\nĐó là tu hành.\nChuyên chú khiến tâm không tán loạn,\ntư duy khiến lý dần sáng tỏ,\nthực hành khiến pháp thấm vào thân.\nNếu con chỉ cầu chuyên chú\nmà không phân biện phải trái,\nthì sự chuyên chú cũng có thể bị dùng vào những việc không tốt.\nNếu con chỉ cầu tri thức\nmà không chịu thực hành,\nthì dù biết nhiều,\nphiền não chưa chắc đã giảm bớt.\nCho nên tâm mà người học Phật nói đến,\nkhông chỉ ở định, mà còn phải có tuệ.\nKhông chỉ ở tuệ, mà còn phải có từ bi.\nThiện nam tử,\ncon lại nên biết:\ntâm không phải là người chủ vĩnh viễn không thay đổi.\nTâm của hôm nay\nvà tâm của hôm qua\nniệm niệm sinh diệt.\nTheo cảnh giới mà sinh khởi,\ntheo nhân duyên mà chuyển đổi.\nMột niệm vui mừng,\nmột niệm âu sầu;\nmột niệm từ bi,\nmột niệm đố kỵ.\nNếu chấp vào một niệm trong đó\nmà cho rằng đó chính là chân ngã vĩnh hằng,\nthì lại sinh ra mê lầm.\nPhật pháp quán tâm,\nkhông chỉ là tìm xem “tâm ở đâu”,\nmà còn là quán sát:\ntâm sinh khởi như thế nào?\nVì sao phan duyên?\nThọ khổ ra sao?\nVà làm thế nào để dứt được nguyên nhân của khổ?\nBiết tâm sinh khởi thế nào, mới quán sát được sự biến đổi của tâm;\nbiết tâm là vô thường, mới không bị tâm trói buộc.\nVí như con tụng Kinh Kim Cang,\nnghe câu “Ưng vô sở trụ nhi sinh kỳ tâm”.\nĐó không phải dạy con đừng suy nghĩ, đừng cảm nhận,\ncũng không phải dạy con trở thành một người không có ý niệm.\nMà là khuyên con:\nkhi làm thiện, không chấp trước công đức;\nkhi đối đãi với người, không chấp trước sự đền đáp;\nkhi học pháp, không chấp rằng mình đã hơn người một bậc.\nTâm có thể có hành động,\nnhưng không cần chỗ nào cũng chấp trước.\nNếu con hỏi:\n“Rốt cuộc thế nào mới gọi là dụng tâm?”\nTa dùng một việc để nói với con.\nCó người đang nói chuyện với con,\ncon tuy nghe thấy tiếng nói,\nnhưng trong lòng chỉ nghĩ cách bác lại,\nđó là tai nghe thấy, chưa hẳn là tâm nghe thấy.\nNếu con có thể tạm gác lại kiến giải của mình,\nlắng nghe ý của người ấy,\nthấu hiểu nỗi khổ của người ấy,\nrồi dùng trí tuệ để đáp lại,\nđó chính là dụng tâm.\nCó người đọc kinh,\nchỉ đếm hôm nay tụng được mấy quyển,\nđó là một phần của tinh tấn,\nnhưng chưa phải là tất cả.\nNếu đọc đến một câu nào đó,\nbỗng thấy những chỗ tham đắm, sân hận thường ngày của mình,\nmà chịu sửa đổi,\nđó chính là pháp đã đi vào tâm mình.\nDụng tâm không phải là tâm gắng sức,\nmà là tâm thật sự có mặt.\nKhông phải nắm chặt từng ý niệm,\nmà là biết rõ mình đang làm gì.\nKhông phải việc gì cũng nghĩ càng nhiều thì càng là dụng tâm.\nSuy nghĩ quá độ\ncũng có thể trở thành chướng ngại.\nCó khi dụng tâm là suy nghĩ nghiêm túc;\ncó khi dụng tâm là buông xả tạp niệm;\ncó khi dụng tâm là chuyên tâm lắng nghe;\ncó khi dụng tâm là thấy được sự chấp trước của mình mà chịu buông xả.\nThiện nam tử,\nta lại nói với con:\ntâm nếu tán loạn, học rồi cũng khó vào;\ntâm nếu chấp trước, học rồi cũng khó thông;\ntâm nếu trong sáng, học rồi thì phân biện được;\ntâm nếu từ bi, học rồi thì thực hành được.\nCho nên dụng tâm học tập,\nkhông chỉ là cầu tri thức,\nmà còn là học cách vận dụng tâm của chính mình.\nLấy chánh niệm thu nhiếp tâm,\nlấy trí tuệ phân biện đạo lý,\nlấy từ bi đối đãi với người,\nlấy hành động ấn chứng điều đã học.\nSau cùng ta dùng bốn câu khuyên con:\ndụng tâm chẳng phải dụng sức,\nchuyên chú chẳng phải chấp trước;\nnghe pháp phải nghĩ nghĩa,\nrõ lý phải thực hành.\nLại nói:\ntâm không ở chỗ cầu hình dạng của nó,\nmà ở chỗ quán sát tác dụng của nó;\nhọc không ở chỗ biết được nhiều,\nmà ở chỗ có chuyển hóa được tâm mình hay không.\nThiện nam tử,\nnếu hôm nay con nghe được một pháp,\nngày mai bớt khởi một phần sân hận,\nhôm nay con hiểu được một đạo lý,\nngày mai thêm hành một phần từ bi,\nđó chính là quả lành\nmà sự dụng tâm học tập chân thật có thể kết thành."]}}, "notices": {"011": "<strong>Lưu ý khi đọc · Khủng hoảng tâm lý</strong>Đây là ghi chép cảm ứng của tác giả. Câu “cửa địa ngục đã khép lại một nửa” là lối nói ẩn dụ, không phải là số liệu y khoa, và cũng không thể chỉ dựa vào vẻ bình thản hay buồn bã của một người để đánh giá nguy cơ. Nếu bạn lo rằng ai đó có thể tự làm hại bản thân, hãy trực tiếp quan tâm và hỏi han, ở bên họ, giúp bảo đảm an toàn và kết nối họ với sự hỗ trợ chuyên môn. Nếu có nguy hiểm tức thời, hãy liên hệ ngay dịch vụ cấp cứu tại địa phương.<br><a href=\"https://www.nimh.nih.gov/health/publications/5-action-steps-to-help-someone-having-thoughts-of-suicide\" target=\"_blank\" rel=\"noopener noreferrer\">Tham khảo NIMH: 5 bước hành động giúp người có ý nghĩ tự tử (tiếng Anh) ↗</a>", "013": "<strong>Lưu ý khi đọc · Quyết định y tế</strong>Bài này ghi lại quan niệm sinh tử ở phương diện đức tin, không phải là phán định y khoa. Việc người bệnh có đang ở giai đoạn cuối đời hay không, tình trạng ý thức và các lựa chọn về điều trị duy trì sự sống cần được bàn bạc với đội ngũ y tế, dựa trên mong muốn của người bệnh, tình trạng lâm sàng và các quy trình áp dụng; không nên dựa vào lời văn cảm ứng để kết luận người bệnh đã mất ý thức, hay để quyết định có nên ngừng điều trị hay không.<br><a href=\"https://www.hpa.gov.tw/EngPages/List.aspx?nodeid=210\" target=\"_blank\" rel=\"noopener noreferrer\">Cục Nâng cao Sức khỏe Quốc dân Đài Loan: Chăm sóc an dưỡng cuối đời (tiếng Anh) ↗</a>", "017": "<strong>Lưu ý khi đọc · Hỗ trợ người chăm sóc</strong>Bài này có đề cập đến áp lực chăm sóc dài hạn, việc tự làm hại bản thân và làm hại người khác. Ghi chép cảm ứng không thể thay thế sự hỗ trợ thực tế về y tế, tâm lý hay chăm sóc. Nếu bạn đã lo lắng cho sự an toàn của bản thân hoặc người nhà, trước hết hãy tìm người có thể đến hỗ trợ trực tiếp và sự giúp đỡ chuyên môn; khi có nguy hiểm tức thời, hãy liên hệ dịch vụ cấp cứu tại địa phương.", "030": "<strong>Ghi chú khi đọc · Trải nghiệm cá nhân</strong>Bài này được giữ nguyên theo lời tự thuật của đạo hữu Hứa. Mối quan hệ nhân quả giữa sự cải thiện thân tâm và đức tin chưa được y học kiểm chứng; trải nghiệm cá nhân không phải là bảo đảm về hiệu quả chữa trị. Khi cơ thể không khỏe, vẫn nên tìm đến sự chăm sóc y tế.", "033": "<strong>Ghi chú khi đọc · Trải nghiệm cá nhân</strong>Bài này được giữ nguyên theo lời tự thuật của đạo hữu Hứa; những lời giải thích về mối nhân quả giữa giấc mộng, cảm nhận thân tâm và sự việc là cách hiểu của chính người trong cuộc.", "019": "<strong>Ghi chú khi đọc · Ghi chép cảm ứng thường niên</strong>Bài này thu nhận nguyên văn lời thỉnh hỏi năm 2026 theo bản thảo gốc; nội dung không được dùng làm lời tiên đoán về thiên tai hay các sự kiện tương lai. Bản gửi đến của bài này không kèm diễn nghĩa và có một dấu ngoặc kép chưa đóng; trang web giữ nguyên văn bản như cũ.", "037": "<strong>Ghi chú khi đọc · Nhân duyên cá nhân</strong>Bài này là những lời thỉnh hỏi và ghi chú về mười năm tình cảm của chính tác giả. Bản gốc cũng nhắc nhở: “Duyên có muôn mối, không thể lấy một trường hợp mà suy cho cả thiên hạ.”"}};
